export const EXAM_BANK: Record<string, ExamBankSkill> = {"Internal Auditing":{"levels":{"1":[{"t":"single","q":"Which international standard provides guidelines for auditing management systems?","o":[["ISO 19011:2018",true],["ISO 9001:2015",false],["ISO 17021:2015",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"According to ISO 19011, an audit is best defined as a process that is which of the following?","o":[["Systematic, independent and documented",true],["Informal and continuous",false],["Mandatory and punitive",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"What term describes the records, statements of fact or other information that are relevant to the audit criteria and verifiable?","o":[["Audit evidence",true],["Audit findings",false],["Audit conclusions",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"In ISO 19011, what is meant by 'audit criteria'?","o":[["The set of policies, procedures or requirements used as a reference",true],["The opinion of the lead auditor",false],["The number of auditors assigned",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"A non-fulfilment of a requirement is formally termed a what?","o":[["Nonconformity",false],["Observation",false],["Nonconformity (non-fulfilment of a requirement)",true]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Which of the following is one of the principles of auditing in ISO 19011?","o":[["Integrity",true],["Profitability",false],["Confidentiality of auditor identity",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"The principle 'fair presentation' obligates auditors to report what?","o":[["Truthfully and accurately",true],["Only positive findings",false],["Only major nonconformities",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Which principle requires auditors to exercise due care and professional judgement?","o":[["Due professional care",true],["Independence",false],["Confidentiality",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"What is the term for a person who conducts an audit?","o":[["Auditor",true],["Auditee",false],["Client",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"What is the organization being audited called?","o":[["Auditee",true],["Audit client",false],["Certification body",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"An audit conducted by an organization on itself for internal purposes is known as which type?","o":[["First-party (internal) audit",true],["Second-party audit",false],["Third-party audit",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"What is the collective term for arrangements for a set of one or more audits planned for a specific time frame and directed towards a specific purpose?","o":[["Audit programme",true],["Audit plan",false],["Audit scope",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Which document describes the activities and arrangements for an individual audit?","o":[["Audit plan",true],["Audit programme",false],["Audit report",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"The extent and boundaries of an audit are referred to as the what?","o":[["Audit scope",true],["Audit criteria",false],["Audit evidence",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Results of the evaluation of collected audit evidence against audit criteria are called what?","o":[["Audit findings",true],["Audit conclusions",false],["Audit evidence",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"ISO 19011 provides guidance applicable to internal (first-party) and external (second- and third-party) management system audits.","a":true,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"Audit findings can indicate either conformity or nonconformity.","a":true,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"Confidentiality is one of the auditing principles in ISO 19011.","a":true,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"Under ISO 19011, the auditee is the person who manages the audit programme.","a":false,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"An observation is the same thing as a formal nonconformity.","a":false,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"The audit conclusion is the outcome of an audit after consideration of the audit objectives and all audit findings.","a":true,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"An auditor should base findings on opinions rather than verifiable evidence.","a":false,"p":1,"ref":"ISO 19011:2018"}],"2":[{"t":"single","q":"When planning an audit programme, which factor is most important to base the extent of the programme on?","o":[["The risks and opportunities relevant to the auditee and the significance of processes",true],["The number of auditors who are available that month",false],["The preference of the lead auditor",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"You are preparing an audit plan for a one-day audit of a purchasing process. Which element is essential to include?","o":[["Audit objectives, scope and criteria",true],["The auditee's annual revenue figures",false],["The certification body's accreditation certificate",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"During an interview an auditee gives a verbal claim about a control. What is the appropriate next step to confirm it?","o":[["Seek corroborating objective evidence such as records",true],["Record the verbal statement as conclusive evidence",false],["Raise a nonconformity immediately",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"While sampling 10 of 200 invoices you find 1 with a missing approval. What is the most appropriate immediate action?","o":[["Note it and consider expanding the sample to assess extent",true],["Conclude the whole process is nonconforming",false],["Ignore it because it is only one record",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"An auditor discovers a process not listed in the audit scope but apparently relevant. What should they do?","o":[["Note it and raise with the audit team leader to decide whether to adjust scope",true],["Audit it fully without discussion",false],["Disregard it entirely",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Which questioning technique best elicits detailed information during an audit interview?","o":[["Open-ended questions",true],["Leading questions",false],["Closed yes/no questions only",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"At an opening meeting, which of the following should the audit team leader confirm with the auditee?","o":[["The audit plan, scope, criteria and logistics",true],["The final audit findings",false],["The corrective actions to be taken",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Why should an internal auditor avoid auditing their own work?","o":[["To preserve objectivity and independence",true],["To save travel time",false],["Because the standard forbids any familiarity",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"A finding states a requirement is not met but cites no clause and no evidence. What is the main deficiency?","o":[["It is not traceable to criteria and supporting evidence",true],["It is too short",false],["It uses the wrong font",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"When generating audit findings, evidence should be evaluated against what?","o":[["The audit criteria",true],["The auditor's personal expectations",false],["The auditee's budget",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Which is the best practice when documenting a nonconformity statement?","o":[["State the requirement, the evidence and the nature of the nonfulfilment",true],["State only the auditor's conclusion",false],["State the recommended corrective action only",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Follow-up of an internal audit primarily aims to do what?","o":[["Verify completion and effectiveness of corrective actions",true],["Re-audit the entire system from scratch",false],["Issue a certificate",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"multi","q":"Which of the following are legitimate methods of collecting audit evidence under ISO 19011?","o":[["Interviewing personnel",true],["Reviewing documents and records",true],["Observing activities",true],["Assuming controls work because the process is mature",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"multi","q":"Which items should typically appear in an audit plan?","o":[["Audit objectives",true],["Audit scope and criteria",true],["Schedule and locations",true],["The auditee's marketing strategy",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"multi","q":"Which behaviours support auditor objectivity and impartiality?","o":[["Basing findings on verifiable evidence",true],["Disclosing potential conflicts of interest",true],["Not auditing one's own work",true],["Accepting gifts from the auditee to build rapport",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"multi","q":"Which are appropriate elements of an effective closing meeting?","o":[["Presenting audit findings and conclusions",true],["Confirming the timeframe for corrective action response",true],["Agreeing any divergent opinions are recorded",true],["Negotiating away valid nonconformities to please the auditee",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"tf","q":"An audit checklist is a useful tool but should not constrain the auditor from pursuing relevant lines of inquiry that arise.","a":true,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"It is acceptable to raise a nonconformity based solely on a single uncorroborated verbal statement.","a":false,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"Sampling allows an auditor to draw conclusions about a population without examining every record, but introduces sampling risk.","a":true,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"The audit team leader is responsible for managing the conduct of the individual audit.","a":true,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"During an audit, observed evidence that contradicts a documented procedure should be disregarded if the auditee disagrees.","a":false,"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Which is the most appropriate audit objective for an internal audit of a corrective-action process?","o":[["Determine whether the process conforms to requirements and is effective",true],["Assign blame for past nonconformities",false],["Count the number of corrective actions raised",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"To verify a claim that all operators are trained, which evidence is most reliable?","o":[["Training records cross-checked with the current operator list",true],["The supervisor's verbal assurance alone",false],["The auditor's general impression of the team",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"An auditee challenges a finding at the closing meeting and provides new evidence that the requirement is in fact met. What should the auditor do?","o":[["Re-evaluate the evidence and withdraw or amend the finding if justified",true],["Keep the finding unchanged because it was already written",false],["Escalate to top management for a decision",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Which approach best maintains the audit trail when collecting evidence?","o":[["Recording the source, reference and details of each piece of evidence",true],["Keeping evidence only in the auditor's memory",false],["Recording conclusions but not their basis",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"short","q":"Describe how you would prepare for and structure an opening meeting for a first-party audit of a small department. List at least four items you would cover.","m":"Looks for: confirming attendees/roles; restating audit objectives, scope and criteria; confirming schedule/logistics and resources; method of reporting and findings; communication channels and confidentiality; opportunity for auditee questions.","p":2},{"t":"short","q":"You sampled 8 of 60 training records and found 2 with no evidence of competence evaluation. Explain how you would decide whether this is an isolated issue or a systemic nonconformity.","m":"Looks for: assess representativeness of sample; consider expanding the sample; look for a common cause vs isolated; relate to the criteria/requirement; document evidence trail; characterize as isolated vs systemic based on extent and root pattern.","p":2}],"3":[{"t":"single","q":"You are lead auditor and a team member raises a 'nonconformity' that is actually their personal preference not tied to any requirement. What is the most appropriate action?","o":[["Reject it as a finding because it is not traceable to audit criteria, and explain why",true],["Include it as a minor nonconformity to be safe",false],["Convert it into an opportunity for improvement without checking criteria",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"An audit programme manager notices recurring late corrective actions across multiple internal audits. Which response best reflects a risk-based programme improvement?","o":[["Analyse the trend, adjust programme priorities and competence, and feed it to management review",true],["Increase the number of audits regardless of cause",false],["Stop following up on corrective actions",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"During an audit you find evidence of a serious safety risk outside your defined scope. What is the most professionally responsible action?","o":[["Report the concern promptly to the auditee and audit client even though it is out of scope",true],["Ignore it because it is outside the audit scope",false],["Quietly fix the problem yourself",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Two auditors disagree on whether evidence constitutes a major or minor nonconformity. As team leader, how do you best resolve this?","o":[["Evaluate evidence against criteria and the impact/extent, and decide based on objective grading rules",true],["Always choose major to be cautious",false],["Let the auditee decide the grading",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"An auditee pressures you to downgrade a well-evidenced nonconformity, hinting it could affect your future engagements. Which response best preserves audit integrity?","o":[["Maintain the finding on the basis of evidence and disclose the pressure if it threatens impartiality",true],["Downgrade it to maintain a good relationship",false],["Remove the finding and add a note instead",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"You must allocate limited audit time across a system. Which prioritization is most defensible?","o":[["Focus on processes with highest risk, past nonconformities and significance to objectives",true],["Audit processes alphabetically",false],["Spend equal time on every process regardless of risk",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"A finding reads: 'The maintenance log for pump P-12 has no entries for March, contrary to PM-04 which requires monthly checks.' What is the strongest aspect of this statement?","o":[["It links specific evidence to a specific requirement",true],["It recommends a corrective action",false],["It identifies who is to blame",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"An auditor's spouse works in the department to be audited. As programme manager, what is the best way to manage this objectivity risk?","o":[["Reassign the auditor to avoid the conflict of interest",true],["Allow the audit but ask them to be extra careful",false],["Ignore it since internal auditors know each other anyway",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"During analysis you realize most of your evidence comes from one shift only. What is the key limitation to address?","o":[["The sample may not be representative of all operating conditions",true],["The evidence is automatically invalid",false],["Nothing, one shift is sufficient",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"You find a documented procedure is followed perfectly but the procedure itself does not satisfy the standard's requirement. How should this be characterized?","o":[["A nonconformity against the criteria despite consistent practice",true],["Conformity, because staff follow the procedure",false],["An observation only, since people comply",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Evidence is conflicting: records say a check was done, but the operator and the equipment state both indicate otherwise. What is the soundest auditor judgement?","o":[["Weigh corroborating physical/observational evidence over a single record and investigate the discrepancy",true],["Accept the record because it is documented",false],["Discard all evidence and move on",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"When evaluating the effectiveness of a corrective action at follow-up, which is the strongest indicator?","o":[["Evidence that the root cause is addressed and the nonconformity has not recurred",true],["A signed statement that action was taken",false],["A new procedure issued, regardless of implementation",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"As lead auditor you must judge overall audit conclusions. Which combination most properly informs them?","o":[["The audit objectives together with all audit findings",true],["Only the major nonconformities",false],["The auditee's self-assessment",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"multi","q":"Which factors should the audit programme manager consider when assigning auditors to a specific audit (competence and impartiality)?","o":[["Technical/sector knowledge relevant to the processes",true],["Independence from the area being audited",true],["Required language and interpersonal skills",true],["The auditor's friendship with the department head",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"multi","q":"Which of the following are valid reasons an audit conclusion might note that audit objectives were only partially met?","o":[["Key personnel were unavailable limiting evidence",true],["Access to certain records was restricted",true],["Significant scope areas could not be sampled adequately",true],["The auditor disliked the auditee",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"multi","q":"When grading a finding as a major nonconformity, which considerations are relevant?","o":[["Total breakdown or absence of a required process",true],["A nonconformity that raises significant doubt about system effectiveness",true],["Likelihood of nonconforming product or service reaching the customer",true],["The auditee has many staff",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"multi","q":"Which actions help an auditor manage cognitive bias and remain objective when analysing evidence?","o":[["Actively seeking evidence that could disconfirm an initial hypothesis",true],["Corroborating findings from multiple independent sources",true],["Documenting the evidence trail for each finding",true],["Forming the conclusion before collecting evidence",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"multi","q":"Which are appropriate ways to handle divergent opinions between the audit team and the auditee that remain unresolved?","o":[["Record the divergent opinions in the audit report",true],["Note that they were discussed without resolution",true],["Escalate to the audit client per the programme",true],["Delete the auditor's finding to end the dispute",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"single","q":"You have one hour left and three open lines of inquiry of differing risk. Which is the best use of remaining audit time?","o":[["Pursue the highest-risk line where evidence is still inconclusive",true],["Re-verify a line already well-evidenced as conforming",false],["Split time equally across all three",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"An auditee provides a large volume of records moments before the closing meeting that may reverse a finding. What is the most defensible action?","o":[["Note that there was insufficient time to evaluate and reflect this limitation in the report",true],["Accept the records at face value and withdraw the finding",false],["Reject the records outright without comment",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Which statement best reflects proper use of an opportunity for improvement (OFI) versus a nonconformity?","o":[["An OFI suggests enhancement where requirements are met; a nonconformity records a non-fulfilment of a requirement",true],["OFIs and nonconformities are interchangeable labels",false],["An OFI should be used whenever the auditor wants to avoid conflict",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"A risk-based audit programme should be reviewed and improved over time using results and feedback from completed audits.","a":true,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"If an auditor cannot reach a clear conclusion due to insufficient evidence, it is acceptable and appropriate to state this limitation in the audit report.","a":true,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"Grading every finding as major regardless of impact strengthens the credibility of the audit.","a":false,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"Audit conclusions may address the effectiveness of the management system, not only conformity.","a":true,"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"An internal auditor may proceed with an audit of a process they personally designed as long as they declare it, with no other mitigation needed.","a":false,"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"You observe that a control operates correctly in practice but is undocumented, while the criteria require documented procedures for that activity. The best characterization is:","o":[["A nonconformity against the documentation requirement, regardless of effective practice",true],["Full conformity, since the control works",false],["No issue, because documentation is optional",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"When deciding sample size for a high-volume, high-risk process with weak prior performance, the most defensible approach is to:","o":[["Increase the sample relative to lower-risk processes and justify the basis",true],["Use the same fixed sample size for every process",false],["Sample only one record to save time",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"short","q":"Write a well-formed nonconformity statement for the following situation: calibration certificates for three of five measuring instruments in the lab are expired, while procedure QP-07 requires annual recalibration. Then explain why your statement is defensible.","m":"Looks for: clear statement of requirement (QP-07 annual recalibration), the objective evidence (3 of 5 certificates expired with identifiers/dates), the nature of non-fulfilment; traceable, factual, no blame; explanation that it links evidence to criteria and is verifiable.","p":3},{"t":"short","q":"As audit programme manager, outline how you would build a risk-based annual internal audit programme for an organization with several processes of differing criticality. Address prioritization, resourcing, and review.","m":"Looks for: identify processes and risks/significance; prioritize by risk, past performance, changes, and management priorities; allocate competent and impartial auditors; set frequency/schedule; define objectives/scope/criteria per audit; monitor results and feed into management review; review and improve the programme.","p":3},{"t":"short","q":"During analysis you have three findings supported by different strengths of evidence. Explain how you decide which become reported nonconformities, which become observations/OFIs, and how you grade severity.","m":"Looks for: evaluate each against criteria; require verifiable, corroborated evidence for nonconformities; distinguish non-fulfilment (NC) from improvement suggestion (OFI); grade severity by extent, systemic vs isolated, and impact/risk; document evidence trail; sound, evidence-based judgement.","p":3},{"t":"short","q":"You suspect an interviewee is withholding information and giving rehearsed answers. Describe the interviewing and evidence-gathering strategies you would use to obtain reliable evidence while remaining professional.","m":"Looks for: use open and probing questions; corroborate verbal claims with records/observation; ask to be shown evidence; observe the actual process; triangulate multiple sources; remain calm, impartial and non-accusatory; build rapport; verify rather than rely on statements.","p":3},{"t":"short","q":"At the closing meeting the auditee disputes a finding and senior management is present applying pressure to remove it. Explain how you would handle the situation to uphold the auditing principles while maintaining a constructive relationship.","m":"Looks for: restate the evidence and criteria objectively; apply integrity, fair presentation and independence; offer to re-evaluate genuine new evidence; if no valid new evidence, retain the finding; record divergent opinions; remain professional and non-defensive; escalate per programme if needed; do not let pressure alter an evidence-based conclusion.","p":3}]}},"Risk Assessment":{"levels":{"1":[{"t":"single","q":"In ISO 31000:2018, risk is defined as the:","o":[["effect of uncertainty on objectives",true],["probability of a negative event",false],["product of likelihood and consequence only",false],["financial loss caused by a hazard",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"Which sequence correctly lists the steps of risk assessment in ISO 31000:2018?","o":[["Risk identification, risk analysis, risk evaluation",true],["Risk analysis, risk identification, risk evaluation",false],["Risk evaluation, risk analysis, risk identification",false],["Risk identification, risk evaluation, risk treatment",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"The person or entity with the accountability and authority to manage a risk is called the:","o":[["risk owner",true],["risk analyst",false],["risk auditor",false],["risk sponsor",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"Residual risk is the risk remaining:","o":[["after risk treatment",true],["before any controls are applied",false],["that cannot ever be identified",false],["accepted by external stakeholders only",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"Which of the following is one of the risk treatment options recognised in ISO 31000:2018?","o":[["Avoiding the risk by deciding not to start the activity",true],["Ignoring the risk until it occurs",false],["Transferring accountability to the auditor",false],["Removing the objective entirely",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"Risk criteria are the terms of reference used to:","o":[["evaluate the significance of risk",true],["identify all possible hazards",false],["assign a risk owner",false],["calculate insurance premiums",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"The overall process comprising risk identification, risk analysis and risk evaluation is called:","o":[["risk assessment",true],["risk management",false],["risk treatment",false],["risk governance",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"A measure that maintains and/or modifies risk is referred to in ISO 31000 as a:","o":[["control",true],["criterion",false],["consequence",false],["context",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"Which technique is described in ISO/IEC 31010 as combining a fault-tree-like analysis of causes with an event-tree-like analysis of consequences around a central event?","o":[["Bowtie analysis",true],["Monte Carlo simulation",false],["HAZOP",false],["Delphi technique",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"FMEA is an abbreviation for:","o":[["Failure Mode and Effects Analysis",true],["Functional Method of Event Assessment",false],["Formal Modelling of Enterprise Activities",false],["Failure Mitigation and Escalation Approach",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"A risk matrix is typically used to:","o":[["rank risks by combining likelihood and consequence",true],["simulate thousands of random outcomes",false],["identify deviations from design intent",false],["calculate net present value",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"In ISO 31000:2018, the level of risk is expressed as a combination of:","o":[["consequences and their likelihood",true],["cost and schedule",false],["threats and vulnerabilities only",false],["assets and controls",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"ISO 31000:2018 states that risk can have positive as well as negative effects on objectives.","a":true,"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"Sharing a risk (for example through insurance or contracts) is a recognised risk treatment option in ISO 31000:2018.","a":true,"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"Risk evaluation always comes before risk identification in the ISO 31000 process.","a":false,"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"Residual risk can include unidentified risk.","a":true,"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"Monte Carlo simulation is a deterministic technique that always produces a single fixed result.","a":false,"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"tf","q":"HAZOP uses guide words to identify deviations from design or operating intent.","a":true,"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"tf","q":"A risk owner is the person with accountability and authority to manage a risk.","a":true,"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"Retaining a risk means taking action to completely eliminate its source.","a":false,"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"Risk criteria should reflect the organisation's values, objectives and resources.","a":true,"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"ISO/IEC 31010 provides a single mandatory technique that must be used for all risk assessments.","a":false,"p":1,"ref":"ISO/IEC 31010:2019"}],"2":[{"t":"single","q":"A project team wants to understand both the causes leading to a major data-breach event and the consequences flowing from it, with the controls on each side made visible. Which technique is most appropriate?","o":[["Bowtie analysis",true],["Monte Carlo simulation",false],["Simple checklist",false],["SWIFT only",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"An organisation decides not to launch a new product line because the assessed risk exceeds its risk criteria. Which treatment option is this?","o":[["Avoiding the risk",true],["Sharing the risk",false],["Retaining the risk",false],["Modifying the likelihood",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"During risk analysis a team needs to model the combined effect of several uncertain cost and schedule variables on a project budget. Which ISO/IEC 31010 technique best fits?","o":[["Monte Carlo simulation",true],["Bowtie analysis",false],["HAZOP",false],["Risk matrix",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"A manufacturing firm wants to systematically examine each component of an assembly to find how it could fail and what the effect would be. The most suitable technique is:","o":[["FMEA",true],["Scenario analysis",false],["Monte Carlo simulation",false],["Risk matrix",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"After treatment, the assessed risk still sits above the appetite line but is accepted by the risk owner with documented justification. The accepted level is best described as:","o":[["residual risk that is knowingly retained",true],["inherent risk before controls",false],["a risk that has been avoided",false],["a transferred risk",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"When comparing the results of risk analysis against risk criteria to decide whether a risk is acceptable or needs treatment, the team is performing:","o":[["risk evaluation",true],["risk identification",false],["risk treatment",false],["context establishment",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"A process plant team systematically walks the P&ID applying guide words such as 'no', 'more' and 'reverse' to flow and pressure to find hazards. They are using:","o":[["HAZOP",true],["FMEA",false],["Bowtie analysis",false],["Delphi technique",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"An organisation moves a risk to an insurer through a contract while retaining accountability for managing it. This treatment is best described as:","o":[["sharing the risk",true],["avoiding the risk",false],["eliminating the risk",false],["retaining the risk without action",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"Which statement best reflects how risk criteria should be set?","o":[["They should be defined at the start and reviewed and adapted as needed",true],["They are fixed permanently once approved",false],["They are set only by external auditors",false],["They are unnecessary if a risk matrix is used",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"A team explores several plausible future situations, including a worst case and a best case, to understand how risks could develop over time. The technique is:","o":[["scenario analysis",true],["FMEA",false],["risk matrix",false],["bowtie analysis",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"multi","q":"Which of the following are recognised risk treatment options in ISO 31000:2018? (Select all that apply.)","o":[["Avoiding the risk by deciding not to start the activity",true],["Sharing the risk with another party",true],["Retaining the risk by informed decision",true],["Ignoring the risk and removing it from the register",false],["Reassigning accountability to the internal auditor",false]],"p":2,"ref":"ISO 31000:2018"},{"t":"multi","q":"Which factors should be considered when selecting a risk assessment technique under ISO/IEC 31010? (Select all that apply.)","o":[["The complexity of the problem and methods needed to analyse it",true],["The nature and degree of uncertainty involved",true],["The resources, capability and expertise available",true],["The colour scheme used in the final report",false],["The personal preference of the most senior person regardless of fit",false]],"p":2,"ref":"ISO/IEC 31010:2019"},{"t":"multi","q":"Which of the following are part of the risk assessment process as opposed to the wider risk management process? (Select all that apply.)","o":[["Risk identification",true],["Risk analysis",true],["Risk evaluation",true],["Risk treatment",false],["Establishing the external context",false]],"p":2,"ref":"ISO 31000:2018"},{"t":"multi","q":"Which statements about a risk matrix are correct? (Select all that apply.)","o":[["It combines likelihood and consequence to rank risks",true],["It is useful for screening and prioritising many risks quickly",true],["It can oversimplify and hide important differences between risks",true],["It produces a precise probabilistic distribution of outcomes",false]],"p":2,"ref":"ISO/IEC 31010:2019"},{"t":"multi","q":"Which of the following are inputs typically needed before meaningful risk analysis can occur? (Select all that apply.)","o":[["Identified risks with their sources and causes",true],["Defined risk criteria",true],["Understanding of existing controls",true],["A finalised treatment plan signed off by the board",false]],"p":2,"ref":"ISO 31000:2018"},{"t":"multi","q":"Which of the following are characteristics of FMEA? (Select all that apply.)","o":[["It examines failure modes of components or process steps",true],["It can be extended to FMECA by adding criticality",true],["It helps identify effects of each failure mode",true],["It models random sampling of thousands of scenarios",false],["It relies on guide words applied to design intent",false]],"p":2,"ref":"ISO/IEC 31010:2019"},{"t":"tf","q":"Modifying the likelihood and modifying the consequences are both legitimate ways of treating a risk under ISO 31000:2018.","a":true,"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"Risk analysis must always produce a single numerical value for every risk.","a":false,"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"A bowtie diagram can show preventive controls on the cause side and mitigating controls on the consequence side.","a":true,"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"tf","q":"Establishing the context, including risk criteria, should be done before risk assessment so that evaluation has a basis.","a":true,"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"A risk owner reviews a risk whose likelihood was reduced by a new control but whose consequence is unchanged. The most accurate statement is that treatment:","o":[["reduced the level of risk by modifying likelihood, leaving residual risk to evaluate",true],["eliminated the risk entirely",false],["transferred the risk to a third party",false],["changed the risk criteria",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"Two qualitatively similar risks fall in the same cell of a 5x5 matrix but differ greatly in absolute magnitude. The best response is to:","o":[["recognise the matrix limitation and apply further analysis to differentiate them",true],["treat them identically because the matrix says so",false],["discard the lower one automatically",false],["double the score of both",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"Which of the following best distinguishes risk analysis from risk evaluation?","o":[["Analysis develops understanding of risk; evaluation compares it against criteria to support decisions",true],["Analysis selects treatments; evaluation identifies hazards",false],["Analysis assigns owners; evaluation writes the report",false],["They are identical terms used interchangeably",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"For a highly uncertain, novel hazard with little historical data, which approach is generally most defensible?","o":[["Use techniques suited to high uncertainty and document assumptions, e.g. scenario analysis or expert elicitation",true],["Rely solely on a precise quantitative model treated as fact",false],["Skip assessment because data is missing",false],["Copy the score from an unrelated risk",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"short","q":"Explain the difference between inherent (or untreated) risk and residual risk, and why distinguishing them matters when reporting to a risk owner.","m":"Looks for: inherent/untreated risk = risk before/without controls or treatment; residual risk = risk remaining after treatment/controls; mention that residual may still need acceptance or further treatment; relevance to risk owner decision and acceptance.","p":2},{"t":"short","q":"A team must assess the risk of a chemical reactor over-pressurising. Recommend one suitable ISO/IEC 31010 technique and justify your choice in two or three sentences.","m":"Looks for: a named relevant technique (HAZOP, bowtie, FMEA, or similar) with justification tied to causes/deviations/consequences and controls; reasoning links technique strengths to the problem rather than naming at random.","p":2}],"3":[{"t":"single","q":"An organisation's risk matrix flags a low-likelihood, catastrophic-consequence event as 'medium', the same band as a frequent minor event. From an ISO/IEC 31010 perspective, the most appropriate critique is that:","o":[["aggregating very different consequence and likelihood profiles into one band can obscure tail risk and mislead decisions",true],["the matrix is always correct and the catastrophic event should be downgraded",false],["the two risks are genuinely equivalent and need no further thought",false],["matrices cannot be used for safety risks at all",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"A Monte Carlo cost model returns a P90 budget far above the deterministic estimate. The best interpretation is that:","o":[["there is roughly a 10 percent chance the cost exceeds the P90 value, revealing upside uncertainty the point estimate hid",true],["the model is wrong because it disagrees with the point estimate",false],["the project will definitely cost the P90 amount",false],["the deterministic estimate should always be trusted over the simulation",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"During risk evaluation, several risks fall just below the treatment threshold but share a common cause. The most defensible action is to:","o":[["consider aggregation and the common cause, since combined exposure may warrant treatment despite individual scores",true],["accept each individually because none crosses the threshold",false],["raise the threshold so they all fall below it",false],["assign them to different owners to dilute responsibility",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"A bowtie for a cyber incident shows many preventive barriers but only one shared mitigating barrier on the consequence side, and that barrier also appears as a preventive barrier. The key concern is:","o":[["a single point of failure and lack of independence undermines the assumed defence in depth",true],["the bowtie has too many barriers and should be simplified",false],["preventive and mitigating barriers are interchangeable so this is fine",false],["bowties cannot represent cyber risk",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"An organisation transfers a risk via insurance and removes it from active management. The most significant flaw under ISO 31000:2018 is that:","o":[["sharing does not remove accountability; the risk owner must still manage residual exposure and the limits of the transfer",true],["insurance always fully eliminates the risk",false],["transferred risks need no owner",false],["sharing is not a valid treatment option",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"Two assessors using the same qualitative scale rate the same risk very differently. The most appropriate ISO/IEC 31010-aligned response is to:","o":[["address the subjectivity by clarifying criteria, calibrating scales, and using structured techniques or multiple experts",true],["always take the higher score with no further discussion",false],["average the two scores and move on without analysis",false],["abandon qualitative methods entirely",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"A risk treatment introduces a new control that itself creates a secondary risk. The best practice is to:","o":[["assess the secondary (control-induced) risk and ensure net risk is reduced before adopting the treatment",true],["ignore secondary effects since the primary risk is reduced",false],["adopt the control regardless because more controls are always better",false],["remove the original risk from the register",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"When validating a quantitative risk model used for a major investment decision, the most important check is that:","o":[["assumptions, input data quality and uncertainty are transparent and the model is fit for the decision",true],["the output is a single precise number to remove ambiguity",false],["the model uses the most complex technique available",false],["the result matches management's preferred answer",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"A risk register lists likelihood and consequence but not the existing controls or their effectiveness. The most serious consequence for risk analysis is that:","o":[["the assessed level may not reflect reality because control effectiveness drives residual risk",true],["the register is fine since controls are a treatment-stage concern only",false],["likelihood alone is sufficient to evaluate risk",false],["controls are irrelevant once consequence is known",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"Choosing between FMEA and HAZOP for a continuous process plant, the more suitable choice and reason is:","o":[["HAZOP, because it systematically examines deviations from intended operating parameters across a process",true],["FMEA, because process plants have no components",false],["Either; the techniques are identical in method and output",false],["Neither; only Monte Carlo applies to process plants",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"An evaluation decision relies on a risk appetite statement that is vague and untested against real scenarios. The strongest improvement is to:","o":[["translate appetite into concrete, testable risk criteria and validate against representative scenarios",true],["keep it vague to preserve flexibility for management",false],["replace it with a single risk matrix and discard appetite",false],["delegate all evaluation to external auditors",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"A team claims a risk is 'eliminated' after adding detective controls that find issues faster. The most accurate critique is that:","o":[["detective controls reduce consequence or speed response but do not eliminate the risk; residual risk remains",true],["detection always eliminates risk entirely",false],["residual risk is irrelevant once detection exists",false],["the risk should be removed from the register immediately",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"multi","q":"Which of the following are valid limitations to disclose when presenting a risk matrix result to decision-makers? (Select all that apply.)","o":[["Banding can mask large differences within the same cell",true],["Ordinal scales should not be treated as if they were precise measurements",true],["Results depend heavily on how scale boundaries are defined",true],["The matrix removes all subjectivity from the assessment",false],["A matrix output is equivalent to a calibrated probability distribution",false]],"p":2,"ref":"ISO/IEC 31010:2019"},{"t":"multi","q":"When a residual risk exceeds the risk criteria, which responses are consistent with ISO 31000:2018? (Select all that apply.)","o":[["Apply further treatment to reduce the risk",true],["Make an informed decision to retain it with appropriate authority and documentation",true],["Reconsider whether the criteria themselves remain appropriate",true],["Silently delete the risk from the register",false],["Reassign the risk to an auditor to avoid treating it",false]],"p":2,"ref":"ISO 31000:2018"},{"t":"multi","q":"Which conditions favour selecting a quantitative technique such as Monte Carlo over a simple qualitative matrix? (Select all that apply.)","o":[["Sufficient, credible data on input variables is available",true],["The decision is significant enough to justify the analytical effort",true],["Understanding the distribution and tails of outcomes adds value",true],["No data exists and inputs are pure guesses",false],["The goal is only a quick first-pass screening of many risks",false]],"p":2,"ref":"ISO/IEC 31010:2019"},{"t":"multi","q":"Which statements about risk owners and accountability under ISO 31000:2018 are correct? (Select all that apply.)","o":[["Accountability for a risk remains with the risk owner even when the risk is shared",true],["A risk owner should have authority commensurate with managing the risk",true],["Treatment plans should identify who is accountable for implementation",true],["Sharing a risk transfers accountability entirely to the third party",false]],"p":2,"ref":"ISO 31000:2018"},{"t":"multi","q":"Which of the following are sound reasons to combine more than one technique in a single risk assessment? (Select all that apply.)","o":[["Different techniques suit identification, analysis and evaluation stages",true],["Cross-checking outputs increases confidence and exposes blind spots",true],["Complex problems may need both qualitative screening and quantitative depth",true],["Using more techniques always guarantees a lower risk score",false]],"p":2,"ref":"ISO/IEC 31010:2019"},{"t":"multi","q":"A bowtie analysis is being quality-reviewed. Which findings would legitimately weaken confidence in it? (Select all that apply.)","o":[["The same control is counted as both a preventive and a mitigating barrier",true],["Barriers are assumed effective without evidence of effectiveness",true],["Escalation factors that defeat barriers are not considered",true],["The diagram clearly separates the top event from its causes and consequences",false]],"p":2,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"A risk is analysed as 'high' but the only data supporting it is a single expert's opinion stated with high confidence. The most rigorous next step is to:","o":[["test the estimate using structured elicitation, additional experts, or sensitivity analysis to expose overconfidence",true],["accept it because the expert was confident",false],["downgrade it to 'low' to be safe",false],["remove the risk since the data is weak",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"Evaluating two treatment options, one reduces likelihood and one reduces consequence, both to the same residual level for the same cost. The strongest deciding factor is usually:","o":[["which option better addresses the worst-case consequence and the organisation's tolerance for severe outcomes",true],["always choosing the likelihood-reducing option by default",false],["whichever has the longer name",false],["the option that adds the most controls regardless of effect",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"A monitoring review finds that a control assumed effective in the original assessment has degraded. The correct ISO 31000-aligned action is to:","o":[["re-assess the affected risk, since changed control effectiveness alters residual risk",true],["leave the assessment unchanged because it was approved",false],["delete the control from the register",false],["wait until the next annual cycle regardless of impact",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"For a one-off, low-stakes operational decision with limited time, the most proportionate technique choice is generally:","o":[["a simple structured method such as a checklist or SWIFT, matched to the low stakes",true],["a full quantitative Monte Carlo study",false],["a multi-day HAZOP regardless of stakes",false],["no assessment at all",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"A scenario analysis only considers a single 'most likely' future. The principal weakness is that:","o":[["it ignores plausible alternative and extreme futures, undermining the purpose of scenario analysis",true],["scenario analysis should only ever use one future",false],["it is too quantitative",false],["it cannot be documented",false]],"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"single","q":"A board asks for risks ranked purely by likelihood, ignoring consequence. The best advice under ISO 31000 is that:","o":[["ranking should reflect the combination of consequence and likelihood, or high-consequence rare events may be neglected",true],["likelihood alone is the correct basis for ranking",false],["consequence should be ignored to simplify the list",false],["ranking is unnecessary if a register exists",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"single","q":"When integrating risk assessment outputs into a decision, the ISO 31000 principle most relevant to keeping the assessment useful over time is that risk management should be:","o":[["dynamic, iterative and responsive to change, with assessments updated as context changes",true],["a one-time exercise completed at project start",false],["owned solely by the risk team in isolation",false],["fixed once the register is signed",false]],"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"Two risks placed in the same risk-matrix cell are always equivalent in importance and require identical treatment.","a":false,"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"tf","q":"A P90 estimate from a Monte Carlo simulation indicates a value that is expected to be exceeded only about 10 percent of the time.","a":true,"p":1,"ref":"ISO/IEC 31010:2019"},{"t":"tf","q":"Sharing a risk through insurance fully transfers accountability for managing that risk away from the risk owner.","a":false,"p":1,"ref":"ISO 31000:2018"},{"t":"tf","q":"A degraded control discovered during monitoring may justify re-assessing the associated residual risk.","a":true,"p":1,"ref":"ISO 31000:2018"},{"t":"short","q":"An organisation reports all risks using only a 5x5 risk matrix. Critically evaluate at least three limitations of relying solely on a risk matrix for high-consequence decisions, referencing ISO/IEC 31010 thinking.","m":"Looks for: banding hides differences within a cell; ordinal scales treated as precise/arithmetic is invalid; sensitivity to boundary definitions and subjectivity; poor handling of tail/low-likelihood-high-consequence risk; recommendation to supplement with quantitative or other techniques.","p":3},{"t":"short","q":"Design a defensible risk assessment approach for a novel technology with little historical data. Identify which ISO/IEC 31010 techniques you would use across identification, analysis and evaluation, and justify how you handle the high uncertainty.","m":"Looks for: techniques mapped to stages (e.g. brainstorming/structured what-if/HAZOP for identification, scenario analysis/expert elicitation/bowtie for analysis, criteria-based evaluation); explicit handling of uncertainty (assumptions, sensitivity, ranges, multiple experts); acknowledgement of limited data and need for iteration/monitoring.","p":3},{"t":"short","q":"A risk owner wants to 'accept' a residual risk that exceeds the documented risk criteria. Explain what must happen for this acceptance to be valid and well-governed under ISO 31000:2018.","m":"Looks for: informed decision by someone with appropriate authority; documentation/justification recorded; consideration of further treatment first; possible review of whether criteria remain appropriate; ongoing monitoring of the retained risk; accountability remains with owner.","p":3},{"t":"short","q":"Compare bowtie analysis and FMEA: state the type of problem each suits best, and give one situation where bowtie is preferable and one where FMEA is preferable.","m":"Looks for: bowtie suits single major event with cause/consequence pathways and barriers (good for communicating controls/defence in depth); FMEA suits component/step-level failure modes and their effects (good for designs/processes with many parts); reasoned examples for each, not interchangeable use.","p":3},{"t":"short","q":"During monitoring and review, an organisation finds that the external context (regulation and market) has changed significantly since the last assessment. Explain how this should affect the existing risk assessment and treatments, referencing ISO 31000 principles.","m":"Looks for: risk management is dynamic/iterative; context change can introduce new risks, change likelihood/consequence, or invalidate criteria; need to re-identify, re-analyse and re-evaluate affected risks; revisit treatments and criteria; update risk owners and register; continual improvement.","p":3}]}},"Statistical Process Control":{"levels":{"1":[{"t":"single","q":"What does the acronym SPC stand for?","o":[["Statistical Process Control",true],["Standard Process Calibration",false],["Systematic Production Counting",false],["Statistical Product Comparison",false]],"p":1},{"t":"single","q":"Variation that is inherent to a process and affects every outcome is called:","o":[["Common cause variation",true],["Special cause variation",false],["Assignable variation",false],["Sporadic variation",false]],"p":1},{"t":"single","q":"Variation arising from a specific, identifiable source that is not part of the normal process is called:","o":[["Special cause variation",true],["Common cause variation",false],["Random variation",false],["Chance variation",false]],"p":1},{"t":"single","q":"A process that exhibits only common cause variation is said to be:","o":[["In statistical control",true],["Capable",false],["Out of control",false],["Centered",false]],"p":1},{"t":"single","q":"On a control chart, the center line (CL) typically represents the:","o":[["Process average (mean)",true],["Upper specification limit",false],["Target tolerance",false],["Largest observed value",false]],"p":1},{"t":"single","q":"Control limits on a Shewhart chart are conventionally placed at how many standard deviations from the center line?","o":[["3 sigma",true],["1 sigma",false],["2 sigma",false],["6 sigma",false]],"p":1},{"t":"single","q":"Which chart pair is used to monitor the central tendency and dispersion of subgrouped variable data using subgroup ranges?","o":[["X-bar and R chart",true],["p and np chart",false],["c and u chart",false],["I-MR chart",false]],"p":1},{"t":"single","q":"Which chart is appropriate for individual measurements where no rational subgroup can be formed?","o":[["I-MR (Individuals and Moving Range) chart",true],["X-bar and R chart",false],["np chart",false],["u chart",false]],"p":1},{"t":"single","q":"Which chart monitors the proportion (fraction) of defective units when subgroup size varies?","o":[["p chart",true],["np chart",false],["c chart",false],["X-bar and s chart",false]],"p":1},{"t":"single","q":"Which chart counts the number of defects per unit when sample size is constant?","o":[["c chart",true],["p chart",false],["u chart",false],["R chart",false]],"p":1},{"t":"single","q":"Specification limits are derived from:","o":[["Customer or engineering requirements",true],["The process data itself",false],["The control chart center line",false],["The subgroup range",false]],"p":1},{"t":"single","q":"Control limits are derived from:","o":[["The process data (its own variation)",true],["Customer requirements",false],["Engineering drawings",false],["The specification tolerance",false]],"p":1},{"t":"single","q":"The most basic Western Electric / Nelson rule signals an out-of-control condition when:","o":[["A single point falls beyond the 3-sigma control limits",true],["Any point falls below the mean",false],["Two consecutive points rise",false],["The range equals zero",false]],"p":1},{"t":"single","q":"A capability index of Cpk greater than or equal to 1.33 is commonly regarded as indicating a:","o":[["Capable process",true],["Out-of-control process",false],["Non-capable process",false],["Centered but incapable process",false]],"p":1},{"t":"single","q":"Which index measures potential capability assuming the process is centered, using only the spread?","o":[["Cp",true],["Cpk",false],["Ppk",false],["Pp adjusted",false]],"p":1},{"t":"tf","q":"A process can be in statistical control yet still fail to meet specification limits.","a":true,"p":1},{"t":"tf","q":"Common cause variation should be addressed by hunting down and eliminating individual data points.","a":false,"p":1},{"t":"tf","q":"Cpk accounts for both the spread of the process and how centered it is relative to the specification limits.","a":true,"p":1},{"t":"tf","q":"Attribute (count) data such as number of defectives is plotted on X-bar and R charts.","a":false,"p":1},{"t":"tf","q":"Gage R&R is a measurement system analysis technique that quantifies repeatability and reproducibility of a gage.","a":true,"p":1}],"2":[{"t":"single","q":"You collect 5 measurements every hour for a machined diameter. Which control chart pair is most appropriate?","o":[["X-bar and R chart",true],["I-MR chart",false],["p chart",false],["c chart",false]],"p":1},{"t":"single","q":"You record the number of nonconforming units in daily samples of differing size. Which chart should you use?","o":[["p chart",true],["np chart",false],["c chart",false],["X-bar and s chart",false]],"p":1},{"t":"single","q":"A chemical batch process yields one viscosity reading per batch and batches are independent. Which chart fits?","o":[["I-MR chart",true],["X-bar and R chart",false],["u chart",false],["np chart",false]],"p":1},{"t":"single","q":"Subgroups of size 12 are taken for a fill-volume process. Which variable chart pair is preferred over X-bar and R?","o":[["X-bar and s chart",true],["I-MR chart",false],["p chart",false],["np chart",false]],"p":1},{"t":"single","q":"You count surface blemishes on inspection areas of varying size (square meters of fabric). Which chart applies?","o":[["u chart",true],["c chart",false],["p chart",false],["np chart",false]],"p":1},{"t":"single","q":"A process has spec limits of 10 +/- 0.3 and sigma = 0.05, centered on target. Cp is approximately:","o":[["2.0",true],["1.0",false],["1.33",false],["0.5",false]],"p":1},{"t":"single","q":"Process mean = 50, sigma = 2, USL = 56, LSL = 44. Cpk is approximately:","o":[["1.0",true],["1.33",false],["2.0",false],["0.5",false]],"p":1},{"t":"single","q":"Eight consecutive points fall on one side of the center line. This Nelson rule indicates:","o":[["A shift in the process mean (out of control)",true],["Normal random behavior",false],["Improved capability",false],["A measurement error only",false]],"p":1},{"t":"single","q":"Six points in a row steadily increasing triggers which type of signal?","o":[["A trend",true],["A cycle",false],["Stratification",false],["A freak point",false]],"p":1},{"t":"single","q":"Rational subgrouping aims to form subgroups so that:","o":[["Variation within a subgroup reflects only common cause variation",true],["Variation within a subgroup captures all special causes",false],["Subgroups span the widest possible time range",false],["Each subgroup contains exactly one reading",false]],"p":1},{"t":"single","q":"A Gage R&R study reports %R&R of 25%. Per common AIAG guidelines this gage is:","o":[["Marginal/may be acceptable depending on application",true],["Clearly acceptable",false],["Always unacceptable for any use",false],["A measure of process capability",false]],"p":1},{"t":"single","q":"If Cp = 1.50 but Cpk = 0.80, the most likely issue is that the process is:","o":[["Off-center relative to the specification midpoint",true],["Too tightly distributed",false],["Out of statistical control by definition",false],["Using the wrong control chart",false]],"p":1},{"t":"single","q":"For an X-bar and R chart, the R chart should be assessed for control:","o":[["Before interpreting the X-bar chart",true],["Only after the X-bar chart is in control",false],["Only if Cpk is below 1.33",false],["Never; only X-bar matters",false]],"p":1},{"t":"single","q":"You inspect a fixed sample of 100 units each shift and record how many are defective. Which chart is most appropriate?","o":[["np chart",true],["p chart with varying n",false],["u chart",false],["X-bar and R chart",false]],"p":1},{"t":"single","q":"Which difference best distinguishes Cpk from Ppk?","o":[["Cpk uses within-subgroup (short-term) sigma; Ppk uses overall (long-term) sigma",true],["Cpk uses long-term sigma; Ppk uses short-term sigma",false],["Cpk applies only to attribute data",false],["They are identical and interchangeable",false]],"p":1},{"t":"tf","q":"Tightening control limits to the specification limits is a valid way to make a process appear more in control.","a":false,"p":1},{"t":"tf","q":"A point exactly on a control limit should generally be investigated as a potential out-of-control signal.","a":true,"p":1},{"t":"tf","q":"For an np chart the subgroup size must be constant.","a":true,"p":1},{"t":"tf","q":"Increasing the subgroup size narrows the X-bar chart control limits because the standard error of the mean decreases.","a":true,"p":1},{"t":"tf","q":"A high Cp value guarantees that few parts will be out of specification regardless of where the process is centered.","a":false,"p":1},{"t":"multi","q":"Which of the following are appropriate uses of attribute control charts? (Select all that apply.)","o":[["p chart for fraction defective with varying sample size",true],["c chart for defects per unit with constant area of opportunity",true],["X-bar and R chart for pass/fail attribute data",false],["I-MR chart for proportion nonconforming",false]],"p":2},{"t":"multi","q":"Which conditions favor using an I-MR chart instead of X-bar and R? (Select all that apply.)","o":[["Measurements are expensive or destructive, yielding one value per period",true],["The production rate is too low to form rational subgroups",true],["You routinely collect 5 readings per hour that can be subgrouped",false],["You are tracking the proportion of defective units",false]],"p":2},{"t":"multi","q":"Which statements about common vs special cause variation are correct? (Select all that apply.)","o":[["Special causes produce points or patterns outside the expected random behavior",true],["Reducing common cause variation usually requires changing the system itself",true],["Special causes are best handled by adjusting the chart limits wider",false],["Common cause variation is always larger than special cause variation",false]],"p":2},{"t":"multi","q":"A process is in statistical control. Which actions are appropriate? (Select all that apply.)","o":[["Assess capability against specification limits",true],["Work on the system to reduce common cause variation if capability is poor",true],["React to each individual point as if it were a special cause",false],["Recompute control limits after every single sample",false]],"p":2},{"t":"short","q":"Explain, in your own words, the practical difference between control limits and specification limits and why confusing them leads to poor decisions.","m":"Looks for: control limits come from the process's own variation (voice of the process); specification limits come from customer/engineering requirements (voice of the customer); they are computed differently and should never be plotted as the same thing; confusing them leads to reacting to in-control points or assuming an in-control process is automatically capable.","p":2},{"t":"short","q":"A team plots fraction-defective data on a p chart and finds the points hug the center line very tightly with no variation. What measurement or charting problems would you investigate?","m":"Looks for: possible inappropriate/over-large subgroups, inspection or data-recording issues, control limits computed incorrectly, stratification or rounding, or data that are too granular; mentions investigating whether the chart type or limits match the data-generating process.","p":2}],"3":[{"t":"single","q":"An X-bar chart shows 9 consecutive points below the center line while the R chart remains in control. The best interpretation is:","o":[["A sustained downward shift in the process mean from a special cause",true],["An increase in within-subgroup variation",false],["Normal common cause behavior requiring no action",false],["A gage repeatability problem only",false]],"p":1},{"t":"single","q":"A process has Cp = 1.80 and Cpk = 1.80. What does this jointly indicate?","o":[["The process is both capable and well centered",true],["The process is capable but badly off-center",false],["The process is incapable",false],["The process is out of statistical control",false]],"p":1},{"t":"single","q":"You observe a strong out-of-control signal on a chart but the gage's %R&R is 40%. The most defensible first action is:","o":[["Resolve the measurement system before trusting the SPC signals",true],["Immediately adjust the process to remove the signal",false],["Widen the control limits to absorb the variation",false],["Switch to an attribute chart",false]],"p":1},{"t":"single","q":"A capability study is run while the process is out of statistical control. The reported Cpk is:","o":[["Unreliable, because capability assumes a stable, predictable process",true],["Valid and can be reported to the customer",false],["Automatically too high",false],["Equal to Pp by definition",false]],"p":1},{"t":"single","q":"Pp = 1.20 but Cp = 1.80 for the same data. What does the gap most likely reveal?","o":[["Between-subgroup variation or drift inflates long-term sigma beyond short-term sigma",true],["The process is perfectly stable",false],["The specification limits are wrong",false],["The gage has zero variation",false]],"p":1},{"t":"single","q":"Fifteen points in a row hug the center line within +/- 1 sigma (Nelson rule 7). This typically signals:","o":[["Reduced variation, possibly from incorrect limits or stratified sampling",true],["A sudden mean shift upward",false],["A normal, healthy process",false],["An increase in the subgroup range",false]],"p":1},{"t":"single","q":"A process is centered on target with Cp = Cpk = 1.00. Approximately what nonconforming rate does this imply (normal, no shift)?","o":[["About 0.27% (2700 ppm)",true],["About 3.4 ppm",false],["Exactly 0%",false],["About 5%",false]],"p":1},{"t":"single","q":"On an X-bar and R chart, the R chart is out of control but the X-bar chart looks fine. The correct conclusion is:","o":[["The X-bar limits are untrustworthy because they depend on R; fix the dispersion first",true],["The process mean has shifted and should be re-centered",false],["Capability can be computed normally",false],["Only the X-bar chart matters, so proceed",false]],"p":1},{"t":"single","q":"A subgroup is formed by mixing output from three different machines into each subgroup. The likely SPC consequence is:","o":[["Inflated within-subgroup variation and control limits too wide to detect machine-to-machine shifts",true],["Tighter, more sensitive control limits",false],["A guaranteed out-of-control signal",false],["No effect on chart sensitivity",false]],"p":1},{"t":"single","q":"Two points out of three consecutive fall beyond 2 sigma on the same side (Nelson rule 5). This is interpreted as:","o":[["An early warning of a possible mean shift before a 3-sigma breach",true],["Conclusive proof of a special cause requiring no further data",false],["A normal random occurrence to be ignored",false],["A sign the R chart is out of control",false]],"p":1},{"t":"single","q":"A customer demands Ppk >= 1.67 but you can only report Cpk = 1.50 from a stable process. The most accurate statement is:","o":[["Short-term Cpk and long-term Ppk differ; you must demonstrate long-term performance, not just short-term capability",true],["Cpk and Ppk are interchangeable, so 1.50 satisfies the requirement",false],["The process is out of control",false],["The gage must be recalibrated to raise the index",false]],"p":1},{"t":"single","q":"A control chart shows a clear cyclical pattern repeating each shift. Before reacting, the best step is to:","o":[["Investigate an assignable cause linked to the shift cycle (people, setup, environment)",true],["Recompute limits to remove the cycle",false],["Conclude the process is in control",false],["Switch immediately to an attribute chart",false]],"p":1},{"t":"single","q":"You must monitor defects per unit where the inspection unit size changes between samples. The most appropriate chart is:","o":[["u chart",true],["c chart",false],["np chart",false],["X-bar and s chart",false]],"p":1},{"t":"single","q":"After a process improvement, control limits should be:","o":[["Recalculated using new in-control data once stability is re-established",true],["Kept exactly as before forever",false],["Set equal to the specification limits",false],["Removed entirely",false]],"p":1},{"t":"single","q":"A Cpk of 1.33 corresponds to roughly how many sigma between the process mean and the nearest spec limit?","o":[["4 sigma",true],["3 sigma",false],["1.33 sigma",false],["6 sigma",false]],"p":1},{"t":"single","q":"A p chart shows several points beyond the upper control limit clustered after a raw-material lot change. The strongest conclusion is:","o":[["The lot change is a likely assignable cause of an increased defective rate",true],["The process exhibits only common cause variation",false],["The control limits should be widened to include the points",false],["The chart type is wrong and should be a c chart",false]],"p":1},{"t":"single","q":"Process A: Cp=1.0, Cpk=1.0. Process B: Cp=2.0, Cpk=1.0. Which statement comparing them is correct?","o":[["B has more room to improve via centering since its spread is much tighter than A's",true],["A is more capable than B",false],["Both have identical spread",false],["B is off-center but A is also off-center by the same amount",false]],"p":1},{"t":"tf","q":"A process with excellent Cpk can still be out of statistical control if the capability was computed from unstable data.","a":true,"p":1},{"t":"tf","q":"If the moving range chart in an I-MR pair is out of control, the individuals chart limits may be invalid.","a":true,"p":1},{"t":"tf","q":"Applying many Western Electric / Nelson rules simultaneously increases the chance of false alarms compared with using only the 3-sigma rule.","a":true,"p":1},{"t":"tf","q":"A high Gage R&R contribution can mask a truly capable process by inflating the observed total variation used in Ppk.","a":true,"p":1},{"t":"multi","q":"Which observations would justify halting a capability study and returning to stabilize the process first? (Select all that apply.)","o":[["A 3-sigma breach on the X-bar chart during data collection",true],["A clear upward trend across the subgroups",true],["All points randomly distributed within control limits",false],["The R chart in statistical control",false]],"p":2},{"t":"multi","q":"Which factors can cause Cpk and Ppk to diverge substantially? (Select all that apply.)","o":[["Process drift or tool wear over the collection period",true],["Shift-to-shift differences between subgroups",true],["Using identical short-term and long-term sigma estimates",false],["A perfectly stable, non-drifting process",false]],"p":2},{"t":"multi","q":"Which statements correctly contrast 'in control' with 'capable'? (Select all that apply.)","o":[["In control means stable and predictable; capable means meeting specifications",true],["A process can be in control but not capable",true],["A process must be capable before it can be in control",false],["Capability indices are meaningful even for an unstable process",false]],"p":2},{"t":"multi","q":"Which are valid reasons to choose X-bar and s over X-bar and R? (Select all that apply.)","o":[["Subgroup sizes are large (e.g., 10 or more)",true],["The standard deviation is a more efficient dispersion estimator for larger subgroups",true],["The data are attribute pass/fail counts",false],["You only have one reading per period",false]],"p":2},{"t":"multi","q":"A point breaches the upper control limit. Which are appropriate investigative responses? (Select all that apply.)","o":[["Check for an assignable cause at that time (setup change, material, operator)",true],["Verify the measurement and data entry before reacting",true],["Immediately widen the control limits to include the point",false],["Conclude the process is incapable without further analysis",false]],"p":2},{"t":"multi","q":"Which conditions undermine the validity of a Gage R&R conclusion? (Select all that apply.)","o":[["Parts chosen do not span the expected process range",true],["Operators are aware which part they are measuring, biasing readings",true],["Measurements are taken in randomized, blinded order",false],["The gage resolution is far finer than the tolerance",false]],"p":2},{"t":"short","q":"A process shows Cp = 2.0 but Cpk = 1.0. Diagnose what is happening and describe the corrective priority versus a case where both equal 1.0.","m":"Looks for: Cp >> Cpk means the spread is excellent but the process is off-center; corrective priority is to re-center the mean (a relatively easy adjustment) rather than reduce variation; contrasts with Cp = Cpk = 1.0 where centering is fine but variation reduction is needed, which is usually harder; notes recentered process would approach Cpk near 2.0.","p":3},{"t":"short","q":"You see a single dramatic out-of-control point on an X-bar chart. Walk through how you would decide whether it is a real special cause or an artifact, and what you would do with the control limits.","m":"Looks for: verify measurement/data entry and gage first; look for an assignable cause at that time; check the R/s chart; if a genuine special cause is found and removed, exclude that point and recompute limits from remaining in-control data; do not delete points without an identified cause; avoid recomputing limits to simply absorb the signal.","p":3},{"t":"short","q":"Explain why declaring a process 'capable' from a capability study requires the process to first be in statistical control, and what goes wrong if you skip that check.","m":"Looks for: capability indices assume a stable, predictable distribution; if special causes are present the distribution is not stable so sigma and the predicted ppm are not trustworthy/repeatable; the reported Cpk/Ppk cannot be projected forward; you may ship a process that drifts out of spec; correct sequence is establish control, then assess capability.","p":3},{"t":"short","q":"Describe how poor rational subgrouping can hide a real process problem, using a concrete example of subgroup formation.","m":"Looks for: subgroups should capture only common cause variation within and let special causes show between subgroups; example such as mixing multiple machines/streams or spanning a shift change into one subgroup inflates within-subgroup variation, widening control limits so genuine shifts go undetected; correct approach groups homogeneous, close-in-time output.","p":3},{"t":"short","q":"A manager wants to react to every point above the center line as a problem. Explain the SPC reasoning for why this is harmful and what the correct response strategy is.","m":"Looks for: points above the mean are expected common cause variation; reacting to them is tampering/overadjustment which increases variation (Deming's funnel idea); correct strategy is to act only on statistically valid signals (beyond limits or recognized Western Electric/Nelson patterns) and otherwise work on the system to reduce common cause variation.","p":3}]}},"Technical Report Writing":{"levels":{"1":[{"t":"single","q":"What is the primary purpose of an executive summary in a technical report?","o":[["To give decision-makers the key findings, conclusions and recommendations without reading the whole report",true],["To list every reference cited in the report",false],["To describe the detailed methodology step by step",false]],"p":1},{"t":"tf","q":"The scope section of a report defines what the report does and does not cover.","a":true,"p":1},{"t":"single","q":"Which voice is generally preferred for clear, concise technical writing?","o":[["Active voice",true],["Passive voice",false],["Future conditional voice",false]],"p":1},{"t":"single","q":"In a test report, a measured value such as '12.4 mm' should always include which of the following?","o":[["The unit of measurement",true],["The author's personal opinion",false],["A marketing statement",false]],"p":1},{"t":"tf","q":"Recommendations in a technical report should logically follow from the findings and conclusions.","a":true,"p":1},{"t":"single","q":"Which statement is an example of an objective, evidence-based statement?","o":[["The sample failed at 250 N applied load",true],["The product is probably the best on the market",false],["We think the supplier did a poor job",false]],"p":1},{"t":"single","q":"What does a figure or table caption primarily provide?","o":[["A concise description identifying the content of the figure or table",true],["The full raw data set in paragraph form",false],["The author's signature",false]],"p":1},{"t":"tf","q":"A nonconformity statement in an audit report should reference the specific requirement that was not met.","a":true,"p":1},{"t":"single","q":"Audience analysis before writing a report helps you decide mainly what?","o":[["The level of technical detail and language to use",true],["The font color of the cover page",false],["The number of pages required by law",false]],"p":1},{"t":"single","q":"Which of these is a fact rather than an opinion?","o":[["The room temperature was recorded as 21 C",true],["The room felt comfortably warm",false],["The room is too cold for most people",false]],"p":1},{"t":"tf","q":"Plain language means using simple, direct wording without unnecessary jargon.","a":true,"p":1},{"t":"single","q":"Where in a report are detailed raw data, calibration certificates and supporting documents normally placed?","o":[["In the appendices",true],["In the executive summary",false],["In the title",false]],"p":1},{"t":"single","q":"Traceability in a technical report refers to the ability to do what?","o":[["Link statements and results back to their source data or evidence",true],["Trace the author's handwriting",false],["Track how many copies were printed",false]],"p":1},{"t":"tf","q":"Consistent terminology and units throughout a report reduce the risk of misunderstanding.","a":true,"p":1},{"t":"single","q":"Which section typically states the overall judgement drawn from the findings?","o":[["Conclusions",true],["Method",false],["References",false]],"p":1},{"t":"single","q":"An inspection report states a dimension as '45.0 mm'. The trailing zero communicates what?","o":[["The precision (significant figures) of the measurement",true],["That the value is an estimate",false],["That the value is irrelevant",false]],"p":1},{"t":"tf","q":"Charts are usually better than tables when the goal is to show a trend or pattern at a glance.","a":true,"p":1},{"t":"single","q":"The method section of a test report should allow a reader to do what?","o":[["Understand and, in principle, repeat what was done",true],["Skip directly to the appendices",false],["Avoid reading the findings",false]],"p":1},{"t":"single","q":"Which is the best example of concise writing?","o":[["The valve was closed.",true],["At this point in time, the valve was caused to be in a closed position.",false],["It can be said that the valve was, more or less, closed.",false]],"p":1},{"t":"tf","q":"Every claim of nonconformity should be supported by objective evidence.","a":true,"p":1}],"2":[{"t":"single","q":"You are writing an audit report for senior management who have limited time. How should you structure the opening?","o":[["Lead with an executive summary highlighting key findings and recommendations",true],["Lead with the full methodology and sampling plan",false],["Lead with the complete list of clause references",false]],"p":1},{"t":"multi","q":"Which of the following statements are objective and evidence-based as written?","o":[["Three of the ten samples exceeded the 5 mm tolerance",true],["The calibration certificate expired on 2025-03-01",true],["The technician seemed careless during testing",false],["The equipment is obviously inadequate",false]],"p":2},{"t":"single","q":"Convert this finding to active voice: 'It was observed by the auditor that records were not maintained.' Which is best?","o":[["The auditor observed that records were not maintained.",true],["Records, it was observed, had a maintenance issue by the auditor.",false],["Maintenance of records was observed to not be done.",false]],"p":1},{"t":"multi","q":"When deciding between a table and a chart to present results, which considerations apply?","o":[["Use a table when exact values must be read",true],["Use a chart when showing a trend or comparison visually",true],["Always use a chart because it looks more professional",false],["Never include both in the same report",false]],"p":2},{"t":"single","q":"A recommendation reads: 'Something should be done about the failures.' What is the main weakness?","o":[["It is vague and not actionable",true],["It uses too many significant figures",false],["It is written in active voice",false]],"p":1},{"t":"tf","q":"When reporting a calculated result, the number of significant figures should reflect the precision of the measurement, not the calculator display.","a":true,"p":1},{"t":"single","q":"A test report mixes 'mm', 'millimetres' and 'mm.' across different tables. What principle is being violated?","o":[["Consistency of units and notation",true],["Objectivity of evidence",false],["Audience analysis",false]],"p":1},{"t":"multi","q":"Which elements strengthen the traceability of a result reported in an inspection report?","o":[["Referencing the test method or standard used",true],["Citing the equipment ID and calibration status",true],["Adding the author's opinion of the supplier",false],["Removing the date of measurement to save space",false]],"p":2},{"t":"single","q":"You must report that 4 of 50 welds failed visual inspection. Which sentence is clearest and most objective?","o":[["Four of the fifty welds (8 percent) did not meet the visual acceptance criteria.",true],["Quite a few welds had problems on inspection.",false],["The welds were mostly fine but some were bad.",false]],"p":1},{"t":"single","q":"A reader asks why a conclusion was reached. A well-written report lets them do what?","o":[["Trace the conclusion back to specific findings and evidence",true],["Re-run the entire test themselves first",false],["Contact the author for an explanation each time",false]],"p":1},{"t":"multi","q":"Which of the following belong in the scope section of a report?","o":[["The boundaries of what was assessed",true],["Any exclusions or limitations",true],["The detailed numerical results",false],["The full reference list",false]],"p":2},{"t":"single","q":"Which sentence correctly separates fact from inference?","o":[["The bearing temperature was 95 C (fact); this suggests inadequate lubrication (inference).",true],["The bearing was definitely under-lubricated because it felt hot.",false],["The bearing temperature seemed high so it failed.",false]],"p":1},{"t":"tf","q":"An executive summary may be written last even though it appears first in the report.","a":true,"p":1},{"t":"single","q":"A nonconformity statement should generally contain which combination?","o":[["The requirement, the evidence of the gap, and where it was observed",true],["Only the auditor's opinion of severity",false],["Only a recommendation to fix it",false]],"p":1},{"t":"multi","q":"Which choices improve concision without losing meaning?","o":[["Replacing 'in order to' with 'to'",true],["Replacing 'at this moment in time' with 'now'",true],["Removing the units from all measurements",false],["Deleting the conclusions section",false]],"p":2},{"t":"single","q":"A chart's y-axis is unlabelled and has no units. What is the most important fix?","o":[["Label the axis with the quantity and its units",true],["Change the chart color scheme",false],["Add a decorative border",false]],"p":1},{"t":"tf","q":"Passive voice can be appropriate when the actor is unknown or unimportant, such as 'The sample was stored at 4 C.'","a":true,"p":1},{"t":"single","q":"You report 'The mean was 7.3825 mm' from values recorded to 0.1 mm. What is wrong?","o":[["Too many significant figures are reported relative to the measurement precision",true],["The mean is in active voice",false],["The unit should be omitted",false]],"p":1},{"t":"multi","q":"Which statements about captions are correct?","o":[["Tables are usually captioned above the table",true],["Figures are usually captioned below the figure",true],["Captions should be left blank for the reader to fill in",false],["Captions should repeat the entire data set",false]],"p":2},{"t":"single","q":"For a mixed audience of engineers and executives, the best approach is to do what?","o":[["Layer the report: summary for executives, detail and appendices for specialists",true],["Write only at the most technical level throughout",false],["Omit the executive summary entirely",false]],"p":1},{"t":"tf","q":"Recommendations are most useful when they are specific, prioritised and assignable to an owner.","a":true,"p":1},{"t":"single","q":"Which is the better evidence-based finding for an audit report?","o":[["Document control procedure QP-07 was not followed for 3 of 8 sampled records.",true],["Document control is generally a bit weak here.",false],["The team probably forgets to control documents.",false]],"p":1},{"t":"single","q":"You need to show how a measured quantity changed across 12 test runs and let readers spot the peak. The best presentation is what?","o":[["A line chart with labelled, captioned axes including units",true],["A dense paragraph describing each run in prose",false],["A single sentence stating only the average",false]],"p":1},{"t":"multi","q":"Which practices help a reader distinguish your data from your interpretation?","o":[["Reporting measured results separately from their interpretation",true],["Using clear signposting such as 'Findings' and 'Conclusions' sections",true],["Blending opinions into the results tables",false],["Stating inferences as if they were measured facts",false]],"p":2},{"t":"short","q":"Rewrite this weak audit finding to be objective and evidence-based: 'The lab is messy and people don't seem to care about calibration.'","m":"Looks for: removes subjective/judgemental language; states a specific observable fact; references the relevant requirement or expected condition; ties to objective evidence (e.g., number of items, location, or specific instrument out of calibration); no opinion words like 'don't care'.","p":2},{"t":"short","q":"In two or three sentences, explain how you would tailor the same test result for (a) a plant operator and (b) a regulatory reviewer.","m":"Looks for: audience analysis; operator version emphasises practical action/plain language; regulator version emphasises traceability, standards/clause references, and evidence; same underlying facts, different framing/detail level.","p":2}],"3":[{"t":"short","q":"Critique and rewrite this sentence from a test report: 'It is felt that the results were pretty good and the equipment was probably fine, which was checked by someone.' Provide an improved version.","m":"Looks for: identifies vagueness, opinion ('felt', 'pretty good', 'probably'), passive/anonymous actor ('by someone'), lack of evidence; rewrite gives a specific objective statement with quantified result, named/identified actor or equipment ID, and active voice.","p":3},{"t":"single","q":"A conclusion states an outcome that is not supported anywhere in the findings. What is the core defect?","o":[["Loss of traceability between findings and conclusions",true],["Excessive use of active voice",false],["Too many captions on tables",false]],"p":1},{"t":"multi","q":"Which revisions improve objectivity AND traceability of this line: 'The pump is bad and we should replace it'?","o":[["State the measured failure, e.g., flow rate dropped to 60 percent of spec",true],["Reference the acceptance criterion and the test that showed the shortfall",true],["Add the phrase 'in our honest opinion'",false],["Remove all numbers to keep it brief",false]],"p":2},{"t":"single","q":"You have findings A, B and C, each with evidence. What is the most logical order for a findings section?","o":[["Group and sequence findings so each leads coherently to the conclusions and recommendations",true],["Random order to keep the reader engaged",false],["Order by length of paragraph, longest first",false]],"p":1},{"t":"short","q":"Outline how you would structure a 'Findings' section for an inspection report covering 5 nonconformities of differing severity. Describe ordering and what each finding entry should contain.","m":"Looks for: a consistent entry template (requirement, objective evidence, location/sample, severity/classification); logical ordering (e.g., by severity or by process area); separation of fact from inference; traceability to evidence; consistency across entries.","p":3},{"t":"single","q":"A recommendation reads: 'Improve training somehow over time.' Which rewrite best fixes it?","o":[["Deliver documented calibration-procedure training to all 6 lab technicians by Q3, verified by a competency check.",true],["Try to make people better at their jobs eventually.",false],["Consider possibly looking into training maybe.",false]],"p":1},{"t":"multi","q":"Which statements correctly distinguish fact, inference and opinion?","o":[["'The reading was 3.2 bar' is a fact",true],["'The pressure drop indicates a leak' is an inference",true],["'The leak is unacceptable and lazy work' is a fact",false],["'The valve was at 3.2 bar' is an opinion",false]],"p":2},{"t":"single","q":"An executive summary contradicts a detail buried in the appendices. What does this most signal to a careful reviewer?","o":[["A consistency failure that undermines credibility",true],["An acceptable difference because summaries are informal",false],["A deliberate stylistic choice",false]],"p":1},{"t":"short","q":"A colleague presents a data set of 12 monthly defect counts and asks whether to use a table or a chart in the report. Explain your recommendation and the reasoning, including how to caption and label it.","m":"Looks for: chart to show the trend across months, possibly a table if exact monthly values matter; recommends axis labels with units, clear caption (figure below / table above), title; mentions significant figures/consistency; ties choice to the report's purpose and audience.","p":3},{"t":"single","q":"Which sentence best preserves objectivity when a cause is uncertain?","o":[["The seal failed at 18 bar; the cause has not been confirmed.",true],["The seal failed because the supplier is incompetent.",false],["The seal obviously failed due to sabotage.",false]],"p":1},{"t":"multi","q":"Which choices would improve the data presentation in a results table?","o":[["Reporting all values to a consistent number of significant figures",true],["Including units in the column headers",true],["Varying the units between rows to add interest",false],["Omitting the table caption to save space",false]],"p":2},{"t":"single","q":"You must report a borderline result that is technically within tolerance but trending toward failure. The most defensible approach is to do what?","o":[["State the measured value, note it is within tolerance, and flag the trend as an inference for monitoring",true],["Report it as a failure to be safe",false],["Omit it because it passed",false]],"p":1},{"t":"short","q":"Rewrite this passive, wordy conclusion into clear active plain language without changing its meaning: 'It was determined by the assessment team that a number of instances of nonconformity were able to be identified in relation to the control of documents.'","m":"Looks for: active voice ('The assessment team identified...'); concision (removes 'a number of instances', 'were able to be', 'in relation to'); preserves meaning (nonconformities in document control); ideally quantifies if data allowed but at minimum tightens wording.","p":3},{"t":"single","q":"Two tables report the same quantity with different units (kPa and bar) and different decimal places. Beyond consistency, what reader risk does this create?","o":[["Misinterpretation or calculation error from the reader",true],["Improved readability",false],["Stronger traceability",false]],"p":1},{"t":"multi","q":"Which are legitimate reasons an audit finding might be challenged as not evidence-based?","o":[["It cites no requirement that was breached",true],["It records an opinion rather than an observable fact",true],["It includes the sample size and location",false],["It references the controlling procedure number",false]],"p":2},{"t":"single","q":"A reader cannot tell whether '0.5' means a measured value or an estimate. What reporting practice would have prevented this?","o":[["Reporting with appropriate significant figures, units and uncertainty where relevant",true],["Using a larger font",false],["Adding more adjectives",false]],"p":1},{"t":"single","q":"In a recommendations section, which ordering best serves a decision-maker?","o":[["By priority or risk, with the most critical actions first",true],["Alphabetically by the first word",false],["By the order the writer thought of them",false]],"p":1},{"t":"multi","q":"Which problems are present in: 'The test was done and it failed, which is bad, so fix it ASAP.'?","o":[["No specific evidence or measured result",true],["Subjective judgement ('which is bad')",true],["Vague, non-actionable recommendation ('fix it ASAP')",false],["Excessive significant figures",false]],"p":2},{"t":"single","q":"Why is it risky to write recommendations that do not trace back to documented findings?","o":[["They appear unsupported and can be disputed or ignored",true],["They make the report shorter",false],["They improve objectivity automatically",false]],"p":1},{"t":"short","q":"Critique this executive summary opening and rewrite it for a senior management audience: 'In this report we will, after describing our extensive methodology in detail, eventually get to some findings that the reader may find of interest regarding the audit.'","m":"Looks for: identifies that it delays/buries key information, is wordy, omits the actual findings/conclusions/recommendations; rewrite leads with the key outcome (e.g., number/severity of findings and main recommendation) in plain, concise language suited to executives.","p":3},{"t":"single","q":"A finding states a percentage but the underlying sample size is not given. What is the main weakness?","o":[["Without the denominator, the result lacks context and traceability",true],["The percentage is in passive voice",false],["The percentage has too few captions",false]],"p":1},{"t":"multi","q":"Which practices best support consistency across a long technical report?","o":[["Using a defined terminology and units convention throughout",true],["Cross-checking that the summary matches the detailed findings",true],["Allowing each section author to choose their own units",false],["Re-defining key terms differently in each chapter",false]],"p":2},{"t":"single","q":"Which statement correctly handles an inference drawn from data?","o":[["Vibration increased by 30 percent (fact); this may indicate bearing wear (inference, to be verified).",true],["Vibration increased, so the bearing is worn out.",false],["The bearing is worn; vibration probably increased too.",false]],"p":1},{"t":"single","q":"An inspection report uses 'approximately', 'roughly' and 'about' before numbers that were precisely measured. What does this most undermine?","o":[["The objectivity and apparent precision of the evidence",true],["The font consistency",false],["The page count",false]],"p":1},{"t":"multi","q":"When presenting significant figures and units in a test report, which are good practices?","o":[["Match significant figures to instrument resolution",true],["State units explicitly and use them consistently",true],["Carry every digit shown by the calculator",false],["Drop units once stated in the title",false]],"p":2},{"t":"single","q":"Which is the strongest reason to keep fact and opinion clearly separated in a management-system report?","o":[["It lets readers evaluate the evidence independently of the author's judgement",true],["It makes the report longer",false],["It removes the need for a conclusions section",false]],"p":1},{"t":"single","q":"A report's method section omits the standard used and the equipment calibration status. The most serious consequence is what?","o":[["Results cannot be fully traced or independently verified",true],["The executive summary becomes too short",false],["The active voice is weakened",false]],"p":1},{"t":"single","q":"Choose the best single revision of: 'A decision was made to possibly recommend that consideration be given to recalibration.'","o":[["We recommend recalibrating the instrument.",true],["It was decided that recalibration might be considered as an option.",false],["Recalibration could perhaps be a thing to think about.",false]],"p":1},{"t":"multi","q":"Which of these belong in a well-formed nonconformity statement in an audit report?","o":[["The specific clause or requirement not met",true],["The objective evidence observed and where",true],["The auditor's personal feelings about the auditee",false],["A guarantee of the root cause without evidence",false]],"p":2},{"t":"single","q":"A conclusions section introduces brand-new data not shown in the findings. Why is this poor practice?","o":[["Conclusions should be drawn from already-presented findings, preserving traceability",true],["Conclusions are allowed to contain anything",false],["It improves concision",false]],"p":1},{"t":"tf","q":"A recommendation can be valid even if it is not linked to any reported finding, as long as it sounds reasonable.","a":false,"p":1},{"t":"single","q":"Which is the best caption for a chart of monthly nonconformities?","o":[["Figure 3. Nonconformities raised per month, Jan-Dec 2025 (count).",true],["A chart.",false],["See data.",false]],"p":1}]}},"Root cause analysis":{"levels":{"1":[{"t":"single","q":"What is a 'root cause' in the context of corrective action?","o":[["The fundamental reason a problem occurred, which if eliminated prevents recurrence",true],["The first symptom a customer notices",false],["The immediate action taken to contain the problem",false]],"p":1},{"t":"single","q":"Which of the following is a 'correction' rather than a root cause?","o":[["Re-inspecting and reworking the defective parts already produced",true],["Worn tooling that was never on a maintenance schedule",false],["A missing verification step in the process design",false]],"p":1},{"t":"tf","q":"A symptom is the observable effect of a problem, not the underlying cause.","a":true,"p":1},{"t":"single","q":"The '5 Whys' technique works primarily by:","o":[["Repeatedly asking 'why' to move from symptom toward an underlying cause",true],["Surveying five different departments for opinions",false],["Listing five corrective actions for every problem",false]],"p":1},{"t":"single","q":"An Ishikawa diagram is also commonly known as a:","o":[["Fishbone (cause-and-effect) diagram",true],["Control chart",false],["Scatter plot",false]],"p":1},{"t":"single","q":"In the classic '6M' fishbone categories for manufacturing, which is one of the six?","o":[["Machine",true],["Margin",false],["Marketing",false]],"p":1},{"t":"single","q":"Which set lists the classic 6M fishbone categories?","o":[["Man, Machine, Method, Material, Measurement, Mother Nature (Environment)",true],["Money, Market, Margin, Method, Material, Measurement",false],["Man, Machine, Money, Market, Mission, Mother Nature",false]],"p":1},{"t":"single","q":"A Pareto analysis is based on the principle that:","o":[["A small number of causes typically account for most of the problems",true],["All causes contribute equally to the problem",false],["Problems should be addressed in the order they are reported",false]],"p":1},{"t":"tf","q":"The Pareto principle is often summarized as the '80/20 rule'.","a":true,"p":1},{"t":"single","q":"In fault tree analysis (FTA), the analysis begins with:","o":[["A defined top undesired event and works downward through contributing causes",true],["A list of corrective actions ranked by cost",false],["A random sample of past defects",false]],"p":1},{"t":"single","q":"An 'is / is-not' analysis is used to:","o":[["Sharpen the problem definition by stating where the problem occurs and where it does not",true],["Decide whether a corrective action is approved or not",false],["Rank causes by frequency",false]],"p":1},{"t":"tf","q":"Stopping a 5 Whys analysis at 'the operator made a mistake' often indicates the analysis stopped too early.","a":true,"p":1},{"t":"single","q":"A 'contributing cause' is best described as:","o":[["A factor that helped the problem occur but is not the fundamental cause",true],["The only cause that must be fixed",false],["A synonym for the symptom",false]],"p":1},{"t":"single","q":"Verifying a root cause means:","o":[["Confirming with objective evidence that the suspected cause actually produces the effect",true],["Asking the team if they agree it sounds right",false],["Documenting it in the CAPA form",false]],"p":1},{"t":"tf","q":"Effective corrective action should address the root cause, not just the symptom.","a":true,"p":1},{"t":"single","q":"In ISO 9001, the clause that addresses nonconformity and corrective action is:","o":[["Clause 10.2",true],["Clause 4.1",false],["Clause 7.5",false]],"p":1,"ref":"ISO 9001:2015 §10.2"},{"t":"single","q":"A causal chain describes:","o":[["A sequence of linked cause-and-effect steps from root cause to observed problem",true],["A list of unrelated defects found in one week",false],["The approval steps for a CAPA",false]],"p":1},{"t":"tf","q":"Blaming an individual instead of examining the system is a common root cause analysis pitfall.","a":true,"p":1},{"t":"single","q":"A Pareto chart typically displays:","o":[["Bars of defect frequency ordered from most to least, often with a cumulative line",true],["A timeline of when each defect was fixed",false],["The cost of each corrective action",false]],"p":1},{"t":"tf","q":"Containment (correction) and root cause elimination are both legitimate parts of handling a nonconformity.","a":true,"p":1}],"2":[{"t":"single","q":"A line stops because a sensor fails. Replacing the sensor restores production. Which statement is correct?","o":[["Replacing the sensor is a correction; why the sensor failed may still be the root cause",true],["Replacing the sensor is the root cause action and the case can be closed",false],["The sensor failure is the symptom and replacing it eliminates recurrence",false]],"p":1},{"t":"single","q":"During 5 Whys you reach 'because there was no preventive maintenance schedule.' The next best step is:","o":[["Test whether eliminating that gap would prevent recurrence before stopping",true],["Stop, because five whys have been asked",false],["Assign blame to the maintenance technician",false]],"p":1},{"t":"multi","q":"Which of the following are valid uses of an is/is-not problem definition? (Select all that apply.)","o":[["Narrowing where and when the defect appears versus where it does not",true],["Distinguishing affected products from similar unaffected ones to find a differentiator",true],["Listing every possible corrective action",false],["Ranking corrective actions by cost",false]],"p":2},{"t":"multi","q":"Which categories belong to the 6M fishbone framework? (Select all that apply.)","o":[["Method",true],["Measurement",true],["Material",true],["Morale",false]],"p":2},{"t":"single","q":"A Pareto chart shows that 3 of 12 defect types account for 78% of all defects. The best initial focus is:","o":[["Investigating the root causes of those 3 dominant defect types first",true],["Spreading effort equally across all 12 defect types",false],["Starting with the least frequent defect for a quick win",false]],"p":2},{"t":"single","q":"In a fault tree, an AND gate beneath the top event means:","o":[["All input events must occur together for the output event to occur",true],["Any single input event alone causes the output event",false],["The events are unrelated to the top event",false]],"p":2},{"t":"single","q":"You suspect 'humidity too high' caused corrosion. The strongest verification is:","o":[["Correlating measured humidity logs with the timing and location of corrosion cases",true],["Noting that humidity 'felt high' that week",false],["Confirming the team agrees humidity is plausible",false]],"p":2},{"t":"multi","q":"Which signs suggest a 5 Whys analysis stopped too early? (Select all that apply.)","o":[["The final 'cause' is 'human error' with no system reason",true],["The final cause is not actionable or verifiable",true],["Eliminating the stated cause would clearly prevent recurrence",false],["The cause points to a missing process control",false]],"p":2},{"t":"single","q":"A corrective action says 'retrain the operator.' Why is this often weak as the sole action?","o":[["It treats a system gap as an individual failing and may not prevent recurrence",true],["Retraining is never an acceptable corrective action",false],["It addresses the symptom and that is always sufficient",false]],"p":2},{"t":"single","q":"Two causes both contributed to a leak: a missing torque check and a worn gasket. The torque check would have caught the gasket. Which is the more fundamental gap to fix?","o":[["The missing torque-check control, since it would have detected the worn gasket",true],["Only the worn gasket, ignoring the missing check",false],["Neither; replace the operator",false]],"p":2},{"t":"single","q":"When linking RCA to corrective action, the action plan should:","o":[["Map each verified root cause to a specific action that eliminates it",true],["Address only the easiest cause to fix",false],["List actions without tying them to specific causes",false]],"p":2},{"t":"multi","q":"Which are appropriate tools for organizing potential causes of a single defined problem? (Select all that apply.)","o":[["Ishikawa/fishbone diagram",true],["5 Whys causal chain",true],["Fault tree analysis",true],["A customer satisfaction survey of unrelated products",false]],"p":2},{"t":"single","q":"A Pareto analysis is most appropriate when you have:","o":[["Categorical frequency data across multiple defect or cause types",true],["A single defect with one obvious cause",false],["No data, only opinions",false]],"p":2},{"t":"single","q":"Which question best fits the 'is-not' side of a problem definition for a defect found only on the night shift?","o":[["The defect does NOT appear on the day or evening shifts",true],["The defect should be fixed by retraining",false],["The defect is the customer's fault",false]],"p":2},{"t":"single","q":"A team writes a root cause but provides no evidence it produces the effect. The risk is:","o":[["Corrective action targets an unconfirmed cause and the problem recurs",true],["The CAPA closes faster, which is always good",false],["Evidence is unnecessary once a cause is plausible",false]],"p":2},{"t":"multi","q":"Which statements about contributing vs root causes are correct? (Select all that apply.)","o":[["A root cause, if removed, prevents recurrence of the problem",true],["Contributing causes increase the likelihood or severity but are not the fundamental driver",true],["Every contributing cause is automatically the root cause",false],["Symptoms and root causes are the same thing",false]],"p":2},{"t":"single","q":"In an Ishikawa session, the 'effect' (fish head) should be:","o":[["The clearly stated problem under investigation",true],["The proposed corrective action",false],["The most likely cause",false]],"p":2},{"t":"single","q":"A defect rate spikes after a raw-material lot change. The best next analytical step is:","o":[["Compare defect data for the new lot versus prior lots (is/is-not by lot)",true],["Immediately retrain operators",false],["Close the issue as random variation",false]],"p":2},{"t":"single","q":"Which is a valid 'top event' for a fault tree analysis?","o":[["Pump fails to deliver flow during operation",true],["Operator attended training in March",false],["Five whys were asked",false]],"p":2},{"t":"tf","q":"A single problem can have more than one root cause that each independently requires corrective action.","a":true,"p":2},{"t":"single","q":"After implementing corrective action, effectiveness should be verified by:","o":[["Checking objective data showing the problem has not recurred over a defined period",true],["Confirming the form was signed",false],["Assuming success because the action was completed",false]],"p":2},{"t":"single","q":"Which best distinguishes a fishbone diagram from a fault tree?","o":[["Fishbone brainstorms many cause categories; FTA models logical combinations leading to a top event",true],["They are identical tools with different names",false],["Fishbone uses AND/OR gates; FTA uses 6M categories",false]],"p":2},{"t":"single","q":"You find three plausible causes. Before writing corrective actions you should:","o":[["Gather evidence to confirm which cause(s) actually drive the effect",true],["Pick the cheapest cause to fix and proceed",false],["Write an action for each plausible cause without verification",false]],"p":2},{"t":"tf","q":"A well-formed problem statement (what, where, when, extent) makes downstream root cause analysis more reliable.","a":true,"p":2},{"t":"short","q":"A customer returns assemblies with loose fasteners. The team's first 5 Whys ends at 'the operator forgot to torque them.' Explain why this is likely too shallow and give the next 'why' you would ask.","m":"Looks for: recognizing 'operator forgot' as human-error stopping point/symptom; pushing to a system cause (no torque verification, no error-proofing, no work instruction, missing in-process check); proposing a deeper 'why' such as why the process allowed an untorqued unit to pass.","p":3},{"t":"short","q":"Given defect data with 9 categories where the top 2 cause 81% of rejects, describe how you would use a Pareto analysis to prioritize root cause work, and one limitation to keep in mind.","m":"Looks for: ordering categories by frequency, focusing RCA on the vital few (top 2), cumulative percentage idea; limitation such as frequency != severity/cost, or that a rare defect could still be safety-critical, or data categorization quality.","p":3}],"3":[{"t":"single","q":"A CAPA closed last quarter after 'operator retraining' is now recurring. The most likely RCA failure is:","o":[["The true system root cause was never identified or verified; a symptom-level action was taken",true],["Retraining was done incorrectly and must simply be repeated",false],["The problem is inherently unfixable",false]],"p":1},{"t":"multi","q":"Which conditions should be met before declaring a root cause 'verified'? (Select all that apply.)","o":[["Objective evidence links the cause to the effect",true],["Removing or controlling the cause is expected to prevent recurrence",true],["The cause is plausible and the team agrees, even without data",false],["The cause is the cheapest to fix",false]],"p":2},{"t":"single","q":"In a fault tree, the top event occurs only when (Gate A AND Gate B). Gate B is a redundant safety interlock that almost never fails. The practical implication is:","o":[["The interlock failure is a key contributing condition; its reliability strongly affects top-event probability",true],["Gate B can be ignored because it rarely fails",false],["Only Gate A matters since it is more common",false]],"p":2},{"t":"single","q":"A team's fishbone lists 30 possible causes but never converges. The best corrective step for the RCA process itself is:","o":[["Use data (is/is-not, Pareto, testing) to eliminate causes and confirm the actual driver",true],["Pick the cause with the most sticky notes",false],["Implement actions for all 30 causes",false]],"p":2},{"t":"single","q":"Evidence shows a defect occurs only with supplier B's material, only on machine 4, only after a recipe change. The strongest interpretation is:","o":[["The interaction of those specific conditions points to a localized, testable root cause",true],["Each factor independently causes the defect regardless of the others",false],["The pattern is coincidence and needs no investigation",false]],"p":2},{"t":"single","q":"Which best illustrates confusing a contributing cause with the root cause?","o":[["Fixing high humidity (which accelerated corrosion) while ignoring the absent protective coating step that should prevent corrosion entirely",true],["Identifying and removing the missing coating step",false],["Verifying the coating step prevents recurrence with test data",false]],"p":2},{"t":"multi","q":"A corrective action plan is strong when it: (Select all that apply.)","o":[["Ties each action to a specific verified root cause",true],["Includes a method to verify effectiveness after implementation",true],["Considers whether the same cause affects other products or lines (extent-of-condition)",true],["Closes immediately upon action completion without measuring recurrence",false]],"p":2},{"t":"single","q":"You complete 5 Whys and the final cause is 'the procedure did not require a final check.' To confirm this is a root cause and not just a contributing cause, you should:","o":[["Test whether adding the check would have detected and prevented the specific failures observed",true],["Stop, because the answer sounds systemic",false],["Assume it is root because it is the last 'why'",false]],"p":2},{"t":"single","q":"A Pareto chart of downtime causes is dominated by 'miscellaneous/other' (35%). The most appropriate response is:","o":[["Improve the data categorization so the 'other' bucket can be analyzed meaningfully",true],["Conclude that downtime is random",false],["Fix whatever is second-largest and ignore 'other'",false]],"p":2},{"t":"single","q":"Two independent root causes are confirmed for one nonconformity. The correct CAPA approach is:","o":[["Define corrective action for each verified root cause and verify effectiveness of both",true],["Fix only the more frequent one to save effort",false],["Pick one and record the other as 'no action needed'",false]],"p":2},{"t":"multi","q":"Which are common RCA pitfalls that lead to recurrence? (Select all that apply.)","o":[["Stopping the analysis at the first plausible cause",true],["Blaming people rather than examining the system that allowed the error",true],["Skipping verification of the root cause with evidence",true],["Mapping each verified cause to a specific action",false]],"p":2},{"t":"single","q":"A causal chain reads: missing spec -> wrong setting selected -> out-of-tolerance part -> customer complaint. The most leveraged corrective action targets:","o":[["The missing spec (and how settings are controlled), the earliest controllable system cause",true],["The customer complaint handling process only",false],["The out-of-tolerance part by rework only",false]],"p":2},{"t":"single","q":"During FTA you find a single basic event under an OR gate that alone triggers the top event and has high probability. This event is best described as:","o":[["A critical single point of failure warranting priority corrective action",true],["A negligible contributor because it is only one event",false],["A symptom, not a cause",false]],"p":2},{"t":"single","q":"A team claims 'human error' as root cause for a mislabeled batch. The most rigorous challenge is:","o":[["Ask why the system permitted a mislabeled batch to be released undetected",true],["Accept it and add a warning memo",false],["Ask the operator to be more careful",false]],"p":2},{"t":"multi","q":"Which questions strengthen an is/is-not analysis? (Select all that apply.)","o":[["What is different about the situations where the defect appears versus where it does not?",true],["When did the problem start, and what changed around that time?",true],["Which corrective action is cheapest?",false],["What objects show the defect and which similar ones do not?",true]],"p":2},{"t":"single","q":"Effectiveness verification of a corrective action one month later shows the defect rate dropped but did not reach zero. The best conclusion is:","o":[["A contributing cause may remain; investigate residual causes rather than closing as fully effective",true],["The action failed completely and should be reversed",false],["Zero is impossible, so close as effective",false]],"p":2},{"t":"single","q":"Why can stopping RCA at a correction (e.g., 'we sorted and scrapped the bad parts') be dangerous?","o":[["It removes the immediate effect but leaves the cause active, so the problem recurs",true],["Sorting and scrapping always eliminates the root cause",false],["Corrections are never appropriate in any situation",false]],"p":2},{"t":"single","q":"A fishbone under 'Measurement' surfaces that the gauge was out of calibration. To confirm this as root cause you would:","o":[["Show that recalibrating/using a valid gauge changes the measured outcome and the defect disappears",true],["Note that calibration is generally important",false],["Move it to the 'Man' category instead",false]],"p":2},{"t":"multi","q":"Which statements correctly contrast symptom, correction, and root cause? (Select all that apply.)","o":[["A symptom is the observable effect of the problem",true],["A correction addresses the immediate effect or output",true],["A root cause, when eliminated, prevents recurrence",true],["A correction always eliminates the root cause",false]],"p":2},{"t":"single","q":"Extent-of-condition review during RCA asks primarily:","o":[["Where else could this same root cause have caused or could cause similar problems?",true],["How much did the corrective action cost?",false],["Who is responsible for the error?",false]],"p":2},{"t":"single","q":"A 5 Whys and a fishbone point to two different causes. The best resolution is:","o":[["Use evidence/testing to determine which cause(s) actually drive the effect; both may be valid",true],["Always trust the 5 Whys over the fishbone",false],["Discard both and start over with opinions",false]],"p":2},{"t":"single","q":"Which corrective action most directly addresses a verified root cause of 'no error-proofing on a reversible connector'?","o":[["Add a physical poka-yoke so the connector cannot be installed backward",true],["Post a sign reminding operators to check orientation",false],["Add a final-inspection rework loop",false]],"p":2},{"t":"single","q":"A problem statement reads 'quality is bad on line 3.' The main weakness for RCA is:","o":[["It is too vague (what defect, where, when, how much) to drive a focused analysis",true],["It names a specific line, which is too narrow",false],["It already states the root cause",false]],"p":2},{"t":"tf","q":"In fault tree analysis, an OR gate means any one of the input events is sufficient to cause the output event.","a":true,"p":2,"ref":"IEC 61025 (FTA)"},{"t":"tf","q":"Demonstrating that a defect can be turned on and off by introducing and removing the suspected cause is strong evidence of root cause.","a":true,"p":2},{"t":"single","q":"A Pareto chart is rebuilt by cost-of-defect instead of frequency, and the ranking changes substantially. The best takeaway for RCA prioritization is:","o":[["Prioritize using the metric that reflects the true impact (e.g., cost or risk), since frequency alone can mislead",true],["Always prioritize by raw frequency regardless of cost",false],["Discard Pareto analysis because the two charts disagree",false]],"p":1},{"t":"single","q":"Which is the best evidence that an RCA was effective, per a corrective-action standard?","o":[["Sustained absence of recurrence verified by data over a defined monitoring period",true],["The CAPA was closed on time",false],["Management approved the action",false]],"p":1,"ref":"ISO 9001:2015 §10.2"},{"t":"short","q":"A pharmaceutical batch fails a dissolution test. Walk through how you would combine an Ishikawa diagram and an is/is-not analysis to narrow toward a verifiable root cause, and state how you would verify it.","m":"Looks for: using 6M (or relevant) categories to enumerate candidate causes; using is/is-not to find differentiators (which batches/equipment/lots/operators are affected vs not, what changed); converging on a small set; verifying with data/experiment (e.g., reproduce with suspected condition, correlate logs) rather than assertion.","p":3},{"t":"short","q":"Explain the difference between a contributing cause and a root cause using a worked example, and describe one risk of fixing only the contributing cause.","m":"Looks for: clear definitions (root removes recurrence; contributing raises likelihood/severity); a concrete example with both; risk that the problem recurs because the fundamental driver remains, or false confidence/closed CAPA reopening.","p":3},{"t":"short","q":"Your investigation lists 'operator did not follow the SOP' as the root cause. Critique this conclusion and rewrite it as a system-level root cause with a matching corrective action.","m":"Looks for: identifying person-blaming pitfall; probing why deviation was possible/likely (SOP unclear, not accessible, conflicting targets, no verification, inadequate training system); restating root cause at the system level; corrective action that changes the system (error-proofing, control, SOP redesign) plus effectiveness check.","p":3},{"t":"short","q":"Describe how you would link a verified root cause to a corrective action and to effectiveness verification, referencing the intent of ISO 9001 clause 10.2.","m":"Looks for: map each verified cause to a specific action that eliminates/controls it; consider extent-of-condition; define how/when effectiveness is measured (recurrence data over a period); update documentation/risks; ties to 10.2 intent of correcting, controlling, evaluating need to eliminate cause, and reviewing effectiveness.","p":3,"ref":"ISO 9001:2015 §10.2"},{"t":"short","q":"A 5 Whys ends after only two whys at a cause that is not testable. Explain two specific weaknesses of this analysis and how you would strengthen it.","m":"Looks for: stopping too early / insufficient depth; cause not verifiable or actionable; possible single-path tunnel vision (5 Whys ignores branching causes); strengthening via continuing to a system cause, cross-checking with fishbone/FTA for multiple branches, and gathering evidence to test each candidate cause.","p":3}]}},"ISO 9001 interpretation":{"levels":{"1":[{"t":"single","q":"In ISO 9001:2015, which clause establishes the requirement to determine external and internal issues relevant to the organization's purpose?","o":[["4.1 Understanding the organization and its context",true],["4.2 Understanding the needs of interested parties",false],["5.1 Leadership and commitment",false],["6.1 Actions to address risks and opportunities",false]],"p":1,"ref":"ISO 9001:2015 §4.1"},{"t":"single","q":"What does the abbreviation QMS stand for in ISO 9001:2015?","o":[["Quality Management System",true],["Quality Measurement Standard",false],["Quality Monitoring Scheme",false],["Quality Manual Specification",false]],"p":1,"ref":"ISO 9001:2015 §3"},{"t":"single","q":"Which methodology underpins the structure of ISO 9001:2015, enabling continual improvement?","o":[["Plan-Do-Check-Act (PDCA)",true],["Define-Measure-Analyze-Improve-Control (DMAIC)",false],["First-In-First-Out (FIFO)",false],["Strengths-Weaknesses-Opportunities-Threats (SWOT)",false]],"p":1,"ref":"ISO 9001:2015 §0.3"},{"t":"single","q":"Which clause requires top management to establish a quality policy?","o":[["5.2 Policy",true],["5.3 Organizational roles, responsibilities and authorities",false],["6.2 Quality objectives and planning to achieve them",false],["4.4 Quality management system and its processes",false]],"p":1,"ref":"ISO 9001:2015 §5.2"},{"t":"single","q":"In ISO 9001:2015, the term replacing 'documents' and 'records' from the 2008 edition is:","o":[["Documented information",true],["Quality manual",false],["Procedures",false],["Work instructions",false]],"p":1,"ref":"ISO 9001:2015 §7.5"},{"t":"single","q":"Which clause addresses the control of externally provided processes, products and services?","o":[["8.4 Control of externally provided processes, products and services",true],["8.5 Production and service provision",false],["8.6 Release of products and services",false],["8.7 Control of nonconforming outputs",false]],"p":1,"ref":"ISO 9001:2015 §8.4"},{"t":"single","q":"How many clauses does ISO 9001:2015 contain in total, including the introductory clauses?","o":[["10",true],["8",false],["7",false],["12",false]],"p":1,"ref":"ISO 9001:2015"},{"t":"single","q":"Which clause covers internal audit requirements?","o":[["9.2 Internal audit",true],["9.1 Monitoring, measurement, analysis and evaluation",false],["9.3 Management review",false],["10.2 Nonconformity and corrective action",false]],"p":1,"ref":"ISO 9001:2015 §9.2"},{"t":"single","q":"In ISO 9001:2015, the concept that replaced 'preventive action' from the previous edition is:","o":[["Risk-based thinking",true],["Continual improvement",false],["Management review",false],["Customer satisfaction",false]],"p":1,"ref":"ISO 9001:2015 §0.3.3"},{"t":"single","q":"Which clause requires the organization to determine and provide the resources needed for the QMS?","o":[["7.1 Resources",true],["7.2 Competence",false],["7.3 Awareness",false],["7.4 Communication",false]],"p":1,"ref":"ISO 9001:2015 §7.1"},{"t":"single","q":"Clause 8.3 of ISO 9001:2015 addresses which activity?","o":[["Design and development of products and services",true],["Control of nonconforming outputs",false],["Release of products and services",false],["Identification and traceability",false]],"p":1,"ref":"ISO 9001:2015 §8.3"},{"t":"single","q":"Which of the following is one of the seven quality management principles in ISO 9001:2015?","o":[["Customer focus",true],["Zero defects",false],["Lean manufacturing",false],["Statistical process control",false]],"p":1,"ref":"ISO 9001:2015 §0.2"},{"t":"single","q":"Which clause deals with nonconformity and corrective action?","o":[["10.2 Nonconformity and corrective action",true],["10.1 General (improvement)",false],["10.3 Continual improvement",false],["9.3 Management review",false]],"p":1,"ref":"ISO 9001:2015 §10.2"},{"t":"single","q":"Competence requirements in ISO 9001:2015 are specified in which clause?","o":[["7.2 Competence",true],["7.3 Awareness",false],["7.1.6 Organizational knowledge",false],["5.3 Organizational roles, responsibilities and authorities",false]],"p":1,"ref":"ISO 9001:2015 §7.2"},{"t":"tf","q":"ISO 9001:2015 requires the organization to maintain a documented quality manual.","a":false,"p":1,"ref":"ISO 9001:2015 §7.5"},{"t":"tf","q":"Under ISO 9001:2015, top management must demonstrate leadership and commitment with respect to the quality management system.","a":true,"p":1,"ref":"ISO 9001:2015 §5.1"},{"t":"tf","q":"In ISO 9001:2015, the management representative role is a mandatory appointment.","a":false,"p":1,"ref":"ISO 9001:2015 §5.3"},{"t":"tf","q":"Clause 6.1 of ISO 9001:2015 requires the organization to address both risks and opportunities.","a":true,"p":1,"ref":"ISO 9001:2015 §6.1"},{"t":"tf","q":"ISO 9001:2015 requires the organization to retain documented information as evidence of the results of management reviews.","a":true,"p":1,"ref":"ISO 9001:2015 §9.3.3"},{"t":"tf","q":"Quality objectives under ISO 9001:2015 must be consistent with the quality policy and be measurable where practicable.","a":true,"p":1,"ref":"ISO 9001:2015 §6.2"},{"t":"tf","q":"ISO 9001:2015 prescribes a single mandatory method for conducting corrective action.","a":false,"p":1,"ref":"ISO 9001:2015 §10.2"},{"t":"tf","q":"The scope of the quality management system must be available and maintained as documented information.","a":true,"p":1,"ref":"ISO 9001:2015 §4.3"}],"2":[{"t":"single","q":"An organization markets a custom-engineering service. When deciding whether design and development controls (8.3) apply, the most appropriate interpretation is:","o":[["8.3 applies because the organization is responsible for translating requirements into product/service characteristics through a design activity",true],["8.3 never applies to services, only to physical products",false],["8.3 can always be excluded for service organizations",false],["8.3 applies only if the customer requests a design review",false]],"p":2,"ref":"ISO 9001:2015 §8.3"},{"t":"single","q":"A company outsources its heat-treatment process. Which interpretation of clause 8.4 is correct?","o":[["The organization must determine and apply controls to the outsourced process proportionate to its impact on conformity",true],["Outsourced processes are exempt from the QMS because a supplier performs them",false],["The organization only needs the supplier's ISO 9001 certificate to satisfy 8.4",false],["8.4 applies only to purchased raw materials, not outsourced processes",false]],"p":1,"ref":"ISO 9001:2015 §8.4"},{"t":"single","q":"During planning of changes to the QMS, clause 6.3 requires that changes be carried out:","o":[["In a planned manner, considering purpose, consequences, integrity of the QMS, resources, and responsibilities",true],["Only after a full external audit",false],["Without documented information, to keep the process agile",false],["Solely at the discretion of the quality manager",false]],"p":1,"ref":"ISO 9001:2015 §6.3"},{"t":"single","q":"A nonconforming batch is discovered after delivery. Under clause 8.7, the organization must:","o":[["Take action appropriate to the effects of the nonconformity, including action regarding products already delivered",true],["Do nothing because the product has left the facility",false],["Automatically recall and scrap all production regardless of effect",false],["Wait for the customer to complain before acting",false]],"p":1,"ref":"ISO 9001:2015 §8.7"},{"t":"single","q":"To satisfy clause 7.1.5 (monitoring and measuring resources), measuring equipment that must provide valid results should be:","o":[["Calibrated or verified against measurement standards traceable to international or national standards, with documented information retained",true],["Replaced annually regardless of condition",false],["Calibrated only when a customer audit is scheduled",false],["Exempt if the operator is experienced",false]],"p":1,"ref":"ISO 9001:2015 §7.1.5"},{"t":"single","q":"An auditor finds the organization defined interested parties but never determined their relevant requirements. The most accurate finding relative to clause 4.2 is:","o":[["A nonconformity, because 4.2 requires determining the requirements of relevant interested parties, not merely listing them",true],["Acceptable, because only listing interested parties is required",false],["An opportunity for improvement only, with no requirement breached",false],["Outside the scope of ISO 9001:2015",false]],"p":1,"ref":"ISO 9001:2015 §4.2"},{"t":"single","q":"Clause 8.5.1 (control of production and service provision) requires controlled conditions. Which item is a required controlled condition?","o":[["Availability of documented information defining the characteristics of products and results to be achieved",true],["A signed contract from every customer",false],["A documented quality manual approved by top management",false],["Annual revision of the quality policy",false]],"p":1,"ref":"ISO 9001:2015 §8.5.1"},{"t":"single","q":"A customer supplies tooling to be used in production. Under clause 8.5.3 (property belonging to customers or external providers), the organization must:","o":[["Identify, verify, protect and safeguard the property, and report any loss or damage to the owner",true],["Treat the tooling as its own asset with no further obligation",false],["Discard the tooling once production is complete without notice",false],["Exclude the tooling from the QMS because it is owned externally",false]],"p":1,"ref":"ISO 9001:2015 §8.5.3"},{"t":"single","q":"When determining the scope of the QMS (4.3), an organization claims a clause is not applicable. This is acceptable only if:","o":[["The non-applicable requirement does not affect the organization's ability or responsibility to ensure conformity of products/services and enhancement of customer satisfaction",true],["Top management simply decides to exclude it",false],["The clause is difficult to implement",false],["The exclusion is taken from clauses 4 through 7 only",false]],"p":1,"ref":"ISO 9001:2015 §4.3"},{"t":"single","q":"Clause 8.2.1 (customer communication) requires the organization to communicate with customers regarding which of the following?","o":[["Handling or controlling customer property",true],["The salaries of customer-facing staff",false],["The organization's internal audit schedule",false],["The competence records of all employees",false]],"p":1,"ref":"ISO 9001:2015 §8.2.1"},{"t":"single","q":"An organization sets a quality objective 'improve customer satisfaction' with no metric or timeline. Relative to clause 6.2 this is:","o":[["Deficient, because objectives must be measurable where practicable and have planning for what, resources, who, when and how results are evaluated",true],["Fully compliant, because intent is stated",false],["Acceptable since satisfaction cannot be measured",false],["Only relevant to clause 9.1.2",false]],"p":1,"ref":"ISO 9001:2015 §6.2"},{"t":"single","q":"For verification of externally provided products, the appropriate interpretation of clause 8.4.2/8.6 is that the organization must:","o":[["Ensure externally provided processes, products and services do not adversely affect its ability to consistently deliver conforming products, applying verification or other activities",true],["Accept all supplier deliveries without inspection if a PO exists",false],["Inspect only the first delivery from each supplier",false],["Rely solely on the supplier's certificate of conformity in all cases",false]],"p":1,"ref":"ISO 9001:2015 §8.4.2"},{"t":"single","q":"During internal audit planning under 9.2.2, audit frequency should be determined considering:","o":[["The importance of processes concerned, changes affecting the organization, and the results of previous audits",true],["A fixed monthly schedule for every process equally",false],["Only the availability of the audit team",false],["The certification body's preferences alone",false]],"p":1,"ref":"ISO 9001:2015 §9.2.2"},{"t":"single","q":"Clause 7.1.6 (organizational knowledge) requires the organization to:","o":[["Determine the knowledge necessary for operation of its processes and to achieve conformity, maintaining it and making it available",true],["Publish all internal knowledge to the public",false],["Patent every piece of process knowledge",false],["Restrict knowledge to top management only",false]],"p":1,"ref":"ISO 9001:2015 §7.1.6"},{"t":"single","q":"An organization treats a customer complaint solely by replacing the product. Under clause 10.2, the most complete interpretation requires also:","o":[["Evaluating the need for action to eliminate the cause so the nonconformity does not recur",true],["Closing the complaint immediately once the product is replaced",false],["Escalating every complaint to top management automatically",false],["Reporting the complaint to the certification body",false]],"p":1,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"Clause 9.1.2 (customer satisfaction) requires the organization to:","o":[["Monitor customers' perceptions of the degree to which their needs and expectations have been fulfilled",true],["Survey only customers who file complaints",false],["Achieve a fixed satisfaction score of 100%",false],["Measure satisfaction only at contract signing",false]],"p":1,"ref":"ISO 9001:2015 §9.1.2"},{"t":"multi","q":"Which of the following must be retained as documented information (records) under ISO 9001:2015? Select all that apply.","o":[["Results of management review (9.3.3)",true],["Evidence of competence (7.2)",true],["Results of internal audits (9.2.2)",true],["A documented quality manual",false],["A documented preventive action procedure",false]],"p":2,"ref":"ISO 9001:2015 §7.5/9.2/9.3"},{"t":"multi","q":"Under clause 6.1, planning to address risks and opportunities should be integrated with which of the following? Select all that apply.","o":[["The QMS processes (4.4)",true],["Actions proportionate to potential impact on conformity of products and services",true],["The organization's strategic context (4.1) and interested parties (4.2)",true],["A separate, mandatory risk register format prescribed by ISO",false],["Quantitative probability scoring required for every risk",false]],"p":2,"ref":"ISO 9001:2015 §6.1"},{"t":"multi","q":"Which inputs are required for management review under clause 9.3.2? Select all that apply.","o":[["Status of actions from previous management reviews",true],["Customer satisfaction and feedback from interested parties",true],["Performance of external providers",true],["Approval of individual employee bonuses",false],["The personal opinions of the certification auditor",false]],"p":2,"ref":"ISO 9001:2015 §9.3.2"},{"t":"multi","q":"Which of the following are controlled conditions required by clause 8.5.1 for production and service provision? Select all that apply.","o":[["Use of suitable monitoring and measuring resources",true],["Implementation of actions to prevent human error",true],["Appointment of competent persons, including required qualification",true],["Mandatory daily management review meetings",false],["Public disclosure of all process parameters",false]],"p":2,"ref":"ISO 9001:2015 §8.5.1"},{"t":"multi","q":"When evaluating external providers under clause 8.4.1, the organization should determine and apply criteria for which activities? Select all that apply.","o":[["Evaluation of external providers",true],["Selection of external providers",true],["Monitoring of external provider performance",true],["Setting the external provider's internal salary structure",false],["Auditing the external provider's tax records",false]],"p":2,"ref":"ISO 9001:2015 §8.4.1"},{"t":"single","q":"A trainee operator is competent but unaware of how their work affects product quality. Under clause 7.3, the appropriate action is to ensure the person is aware of:","o":[["The quality policy, relevant objectives, their contribution to QMS effectiveness, and implications of not conforming",true],["Only the contents of their job description",false],["The organization's full financial statements",false],["The certification body's audit schedule",false]],"p":1,"ref":"ISO 9001:2015 §7.3"},{"t":"single","q":"Determining the information for external providers (8.4.3), the organization must communicate which of the following before purchase?","o":[["Requirements for the processes, products, services, approval, competence, and control to be applied",true],["The organization's profit margin on the finished product",false],["The names of all internal auditors",false],["The customer's confidential contract value",false]],"p":1,"ref":"ISO 9001:2015 §8.4.3"},{"t":"single","q":"An organization keeps design records but no documented information on design changes. Against clause 8.3.6 the gap is that the organization must:","o":[["Retain documented information on design and development changes, the results of reviews, authorization, and actions to prevent adverse impacts",true],["Re-run the entire design from scratch for any change",false],["Treat all design changes as nonconforming output",false],["Avoid documenting changes to remain flexible",false]],"p":1,"ref":"ISO 9001:2015 §8.3.6"},{"t":"multi","q":"Under clause 7.5.3, controlling documented information includes addressing which of the following activities? Select all that apply.","o":[["Distribution, access, retrieval and use",true],["Storage and preservation, including legibility",true],["Control of changes and version control, and retention/disposition",true],["Mandatory paper-only storage of all documents",false],["Public publication of all internal procedures",false]],"p":2,"ref":"ISO 9001:2015 §7.5.3"},{"t":"short","q":"Explain, in interpretation terms, the difference between 'correction' and 'corrective action' as used in clause 10.2, and give a brief example of each.","m":"Looks for: correction = action to eliminate the detected nonconformity itself (e.g., rework/scrap/replace the defective item); corrective action = action to eliminate the cause to prevent recurrence (e.g., fix the root-cause process). Example pair and recognition that both may be needed.","p":2},{"t":"short","q":"An organization wants to exclude clause 8.3 (design and development). Describe how you would interpret clause 4.3 to judge whether this exclusion is justified.","m":"Looks for: exclusion allowed only if the requirement is not applicable to the scope; organization is not responsible for design (e.g., builds to customer-provided designs); exclusion must not affect ability/responsibility to ensure conformity and enhance customer satisfaction; must be documented in QMS scope with justification.","p":2}],"3":[{"t":"single","q":"An organization defines its context (4.1) and interested parties (4.2) but its risk assessment (6.1) makes no reference to either. The best evaluative interpretation is:","o":[["A weakness in QMS integration: 6.1 risks/opportunities should be determined considering the issues of 4.1 and requirements of 4.2",true],["Acceptable, because 6.1 is independent of 4.1 and 4.2",false],["A finding only if the customer complains",false],["Outside the standard's intent because linkage is optional",false]],"p":1,"ref":"ISO 9001:2015 §6.1"},{"t":"single","q":"A process owner argues that because the supplier is ISO 9001 certified, no incoming verification is needed (8.4/8.6). The most defensible interpretation is:","o":[["Certification informs the type and extent of control but does not by itself discharge the organization's duty to ensure provided items meet requirements",true],["Certification fully removes any verification obligation",false],["Verification is required for every item regardless of risk",false],["8.4 does not apply when suppliers are certified",false]],"p":1,"ref":"ISO 9001:2015 §8.4.2"},{"t":"single","q":"An auditee shows a colourful risk register but cannot show any resulting actions or how effectiveness is evaluated. Relative to 6.1.2, the strongest conclusion is:","o":[["Nonconformity: 6.1.2 requires planning actions to address risks AND evaluating the effectiveness of those actions",true],["Conformity, because a register exists",false],["Opportunity for improvement only",false],["Not auditable because risk methods are not prescribed",false]],"p":1,"ref":"ISO 9001:2015 §6.1.2"},{"t":"single","q":"A manager closes every corrective action by retraining the operator. Evaluating this pattern against 10.2, the best interpretation is:","o":[["Likely inadequate root-cause analysis: repeatedly defaulting to retraining may not address the true cause of recurring nonconformities",true],["Fully effective because training always fixes problems",false],["Compliant because 10.2 mandates retraining",false],["Irrelevant to 10.2 since training is a 7.2 matter only",false]],"p":1,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"Design verification and design validation (8.3.4) are best distinguished as:","o":[["Verification confirms outputs meet input requirements; validation confirms the resulting product/service meets the requirements for the specified application or intended use",true],["Verification and validation are synonyms with no practical difference",false],["Validation precedes verification in all cases",false],["Verification is for services and validation is for products",false]],"p":1,"ref":"ISO 9001:2015 §8.3.4"},{"t":"single","q":"An organization's quality policy is a generic statement copied from a template with no link to its context. Evaluating against 5.2.1, the key deficiency is:","o":[["The policy must be appropriate to the purpose and context of the organization and support its strategic direction",true],["Policies may never be derived from templates under any circumstance",false],["The policy must list every quality objective verbatim",false],["The policy must be signed by all employees",false]],"p":1,"ref":"ISO 9001:2015 §5.2.1"},{"t":"single","q":"During an audit you find that nonconforming output is segregated but no documented information describes the authority deciding on disposition. Against 8.7.2 this is:","o":[["A nonconformity: 8.7.2 requires retained documented information describing the nonconformity, actions taken, concessions, and the authority deciding the action",true],["Acceptable as long as the parts are physically separated",false],["Only an opportunity for improvement",false],["Out of scope because disposition is operational, not documented",false]],"p":1,"ref":"ISO 9001:2015 §8.7.2"},{"t":"single","q":"A company measures many KPIs but never analyzes them to evaluate QMS performance and effectiveness. Evaluating against 9.1.3, the conclusion is:","o":[["Nonconformity: 9.1.3 requires analyzing and evaluating data from monitoring and measurement, not merely collecting it",true],["Compliant, because data is being collected",false],["Relevant only to clause 6.2",false],["A management decision outside ISO 9001",false]],"p":1,"ref":"ISO 9001:2015 §9.1.3"},{"t":"single","q":"An organization applies the process approach (4.4). The strongest indicator that the approach is genuinely implemented is:","o":[["Process inputs, outputs, sequence, interactions, criteria, resources, responsibilities, and risks are determined and managed as an interacting system",true],["A flowchart exists on the wall",false],["Each department works independently to optimize its own output",false],["The quality manager owns all processes personally",false]],"p":1,"ref":"ISO 9001:2015 §4.4"},{"t":"single","q":"Top management delegates all QMS responsibility to a quality manager and is otherwise uninvolved. Against clause 5.1.1 this is best evaluated as:","o":[["A leadership nonconformity: top management must take accountability for the effectiveness of the QMS, not merely delegate it",true],["Acceptable because a competent manager is appointed",false],["Acceptable because ISO 9001 allows full delegation",false],["Relevant only to clause 5.3 organizational roles",false]],"p":1,"ref":"ISO 9001:2015 §5.1.1"},{"t":"single","q":"An organization's documented information is up to date but uncontrolled copies circulate uncontrolled on shared drives. Against 7.5.3 the issue is:","o":[["Control of distribution, access, retrieval, use, and prevention of unintended use of obsolete documents is inadequate",true],["No issue, because the master copy is current",false],["Only a security concern outside ISO 9001",false],["Acceptable because the standard does not address distribution",false]],"p":1,"ref":"ISO 9001:2015 §7.5.3"},{"t":"single","q":"A change in production method was made without assessing its consequences and integrity to the QMS. Evaluating against 6.3 and 8.5.6, the conclusion is:","o":[["Nonconformity: changes must be reviewed and controlled to ensure continuing conformity, retaining documented information of the review, the persons authorizing the change, and any necessary actions",true],["Acceptable because the change improved throughput",false],["Only relevant to design changes under 8.3.6",false],["Out of scope because operators implemented it",false]],"p":1,"ref":"ISO 9001:2015 §8.5.6"},{"t":"single","q":"An organization claims continual improvement (10.3) is satisfied by holding annual management reviews. The best evaluation is:","o":[["Management review is an input/enabler, but continual improvement requires considering analysis/evaluation outputs and review results to identify needs or opportunities to be addressed",true],["Fully satisfied, since reviews are held annually",false],["Continual improvement is optional and need not be demonstrated",false],["Continual improvement equals corrective action only",false]],"p":1,"ref":"ISO 9001:2015 §10.3"},{"t":"single","q":"Awareness (7.3) versus competence (7.2) is best distinguished as:","o":[["Competence is the ability to apply knowledge and skills to achieve results; awareness is persons understanding the policy, objectives, their contribution, and implications of nonconformity",true],["They are identical requirements stated twice",false],["Awareness applies only to managers and competence only to operators",false],["Competence is about attitude and awareness is about training certificates",false]],"p":1,"ref":"ISO 9001:2015 §7.3"},{"t":"single","q":"An organization determines requirements for products and services (8.2.2) but accepts an order it cannot meet on delivery date. Against 8.2.3 (review of requirements), the deficiency is:","o":[["The organization failed to ensure it has the ability to meet the requirements before committing to supply",true],["No deficiency, since the customer placed the order",false],["Relevant only to 8.4 external providers",false],["Acceptable because delivery dates are not requirements",false]],"p":1,"ref":"ISO 9001:2015 §8.2.3"},{"t":"single","q":"A certification auditor and an internal auditor disagree on whether 'documented procedure' is required for corrective action. The correct interpretation under ISO 9001:2015 is:","o":[["No specific documented procedure is mandated; the organization retains documented information as evidence of the nature of nonconformities and actions taken",true],["A documented corrective action procedure is always mandatory",false],["No documented information of any kind is needed",false],["The certification body decides the requirement",false]],"p":1,"ref":"ISO 9001:2015 §10.2.2"},{"t":"multi","q":"Evaluating whether an organization's risk-based thinking is mature (clauses 4.1, 4.2, 6.1), which of the following are valid evidence? Select all that apply.","o":[["Risks/opportunities are traceable to context issues and interested-party requirements",true],["Planned actions are integrated into QMS processes and proportionate to impact",true],["Effectiveness of actions taken is evaluated and feeds improvement",true],["A static risk register created once and never revisited",false],["A requirement to use a specific FMEA template mandated by ISO 9001",false]],"p":2,"ref":"ISO 9001:2015 §6.1"},{"t":"multi","q":"Which findings would correctly be classified as nonconformities against clause 9.2 (internal audit)? Select all that apply.","o":[["Audit programme does not consider importance of processes or results of previous audits",true],["Auditors audit their own work, compromising objectivity and impartiality",true],["No documented information of audit results is retained",true],["Audits are scheduled risk-based rather than at fixed equal intervals",false],["The organization uses an external party to conduct internal audits",false]],"p":2,"ref":"ISO 9001:2015 §9.2"},{"t":"multi","q":"Which of the following are required outputs/decisions from management review under clause 9.3.3? Select all that apply.","o":[["Decisions related to continual improvement opportunities",true],["Decisions on any need for changes to the QMS",true],["Decisions related to resource needs",true],["A mandatory increase in the audit budget each year",false],["A ranked list of employees for promotion",false]],"p":2,"ref":"ISO 9001:2015 §9.3.3"},{"t":"multi","q":"In interpreting clause 8.3.3 (design and development inputs), which inputs should be considered? Select all that apply.","o":[["Functional and performance requirements",true],["Applicable statutory and regulatory requirements",true],["Standards or codes of practice the organization has committed to implement",true],["The organization's annual marketing budget",false],["The personal preferences of the design team unrelated to requirements",false]],"p":2,"ref":"ISO 9001:2015 §8.3.3"},{"t":"multi","q":"When evaluating control of nonconforming outputs (8.7), which response options are explicitly permitted by the standard? Select all that apply.","o":[["Correction (e.g., rework or repair)",true],["Segregation, containment, return, or suspension of provision",true],["Obtaining authorization for acceptance under concession",true],["Automatically informing the certification body of every nonconformity",false],["Ignoring nonconformities that occur after delivery",false]],"p":2,"ref":"ISO 9001:2015 §8.7.1"},{"t":"multi","q":"Which of the following correctly describe how PDCA maps onto ISO 9001:2015 clauses? Select all that apply.","o":[["Plan corresponds broadly to clauses 4, 5, 6 and 7",true],["Do corresponds broadly to clause 8 (operation)",true],["Check corresponds broadly to clause 9 (performance evaluation)",true],["Act corresponds only to clause 5 (leadership)",false],["PDCA applies solely at the level of the whole QMS and not to individual processes",false]],"p":2,"ref":"ISO 9001:2015 §0.3.2"},{"t":"single","q":"An organization retains 'documented information to be maintained' versus 'to be retained'. The correct interpretation of this distinction is:","o":[["'Maintained' refers to documents kept current (e.g., procedures/scope); 'retained' refers to records providing evidence of results",true],["Both phrases mean the same and require records only",false],["'Maintained' means archived and 'retained' means deleted",false],["The distinction is editorial with no practical effect",false]],"p":1,"ref":"ISO 9001:2015 §7.5"},{"t":"single","q":"A service company excludes 7.1.5.2 (measurement traceability) claiming it does no measurement. Evaluating this, the correct approach is:","o":[["Exclusion of traceability is acceptable only where measurement traceability is not a requirement; the organization must justify that valid results do not depend on traceable measurement",true],["No exclusion is ever permitted in clause 7",false],["Any service company may exclude all of clause 7.1.5 automatically",false],["Traceability applies only to laboratories and never to others",false]],"p":1,"ref":"ISO 9001:2015 §7.1.5.2"},{"t":"single","q":"Two auditors classify the same issue differently: one as a 4.4 process-approach finding, the other as an 8.5.1 operational-control finding. The best evaluative stance is:","o":[["Determine which clause's specific requirement is unmet by the evidence; 4.4 concerns the system of processes, 8.5.1 concerns controlled conditions during production/service provision",true],["Always classify under the latest-numbered clause",false],["Classification is arbitrary and need not be justified",false],["Both classifications are invalid because overlap is not allowed",false]],"p":1,"ref":"ISO 9001:2015 §4.4"},{"t":"single","q":"An organization plans changes to its QMS (6.3) by email approvals without considering integrity of the QMS or resource availability. Evaluating this:","o":[["It is deficient because 6.3 requires considering purpose and potential consequences, integrity of the QMS, availability of resources, and allocation of responsibilities and authorities",true],["It is compliant because approvals exist",false],["6.3 applies only to product changes",false],["Email approvals are prohibited by ISO 9001",false]],"p":1,"ref":"ISO 9001:2015 §6.3"},{"t":"tf","q":"Under ISO 9001:2015, an organization may determine that a requirement of clauses 4 to 10 is not applicable, provided this does not affect its ability or responsibility to ensure product/service conformity and enhance customer satisfaction.","a":true,"p":1,"ref":"ISO 9001:2015 §4.3"},{"t":"tf","q":"Risk-based thinking in ISO 9001:2015 requires every organization to maintain a formal documented risk-management process equivalent to ISO 31000.","a":false,"p":1,"ref":"ISO 9001:2015 §0.3.3"},{"t":"short","q":"A recurring nonconformity keeps reappearing despite repeated corrective actions. Using clause 10.2, describe how you would evaluate the adequacy of the organization's root-cause analysis and corrective-action effectiveness.","m":"Looks for: review the nonconformity and its causes (10.2.1 b); determine if true root cause was identified vs symptom; check whether similar nonconformities exist/could occur; assess effectiveness review of actions taken (10.2.1 e); evidence of updating risks/opportunities and QMS changes; conclude that recurrence signals ineffective corrective action / inadequate root-cause analysis.","p":3},{"t":"short","q":"Interpret how clauses 4.1, 4.2, 6.1 and 9.3 form a closed loop in ISO 9001:2015, and explain why breaking any link weakens the QMS.","m":"Looks for: 4.1/4.2 establish context and interested-party requirements -> 6.1 determines risks/opportunities and plans actions -> implemented in QMS processes -> 9.3 management review revisits context, interested parties, risks/opportunities and effectiveness -> feeds changes/improvement back into planning. Breaking a link means risks not grounded in context, actions not reviewed, or context not refreshed; loss of continual improvement and relevance.","p":3},{"t":"short","q":"An organization wants to exclude clause 8.4 (externally provided processes) because 'we make everything in-house'. Evaluate whether this exclusion is interpretable as valid and what evidence you would seek.","m":"Looks for: 8.4 applies to externally provided products/services AND outsourced processes; recognize that even in-house manufacturers usually buy materials, calibration, software, transport, contract labor; seek evidence of any external provision; exclusion rarely valid; if some sub-clauses truly not applicable, must justify under 4.3 without affecting conformity.","p":3},{"t":"short","q":"Distinguish, in interpretation terms, between clause 9.1.3 (analysis and evaluation) and clause 10.3 (continual improvement), and explain how outputs of one feed the other.","m":"Looks for: 9.1.3 analyzes/evaluates data on conformity, satisfaction, QMS performance, process performance, suppliers, risk/opportunity effectiveness; 10.3 uses those results plus analysis/evaluation and management review outputs to determine needs/opportunities for improvement to be addressed; analysis is the evidence base, improvement is the action loop; without 9.1.3 improvement lacks data, without 10.3 analysis produces no action.","p":3},{"t":"short","q":"A top-management team treats the quality policy as a wall poster unrelated to objectives or daily decisions. Using clauses 5.1, 5.2 and 6.2, evaluate the leadership deficiencies and what 'good' would look like.","m":"Looks for: 5.1 accountability for QMS effectiveness, integration into business processes, promoting customer focus and improvement; 5.2 policy appropriate to context, framework for objectives, communicated and applied; 6.2 objectives consistent with policy, measurable, planned and monitored; 'good' = policy drives measurable objectives cascaded into processes, leaders engaged and resourcing, evidence of alignment; deficiency = disconnect between stated policy and actual management system.","p":3}]}},"ISO 14001 interpretation":{"levels":{"1":[{"t":"single","q":"In ISO 14001:2015, what does 'EMS' stand for?","o":[["Environmental Management System",true],["Emergency Management Standard",false],["Ecological Monitoring Scheme",false]],"p":1,"ref":"ISO 14001:2015 §3.1.2"},{"t":"single","q":"Which high-level structure does ISO 14001:2015 follow?","o":[["Annex SL (Plan-Do-Check-Act aligned)",true],["The Deming-only nine-step model",false],["The ISO 9000:1994 element structure",false]],"p":1,"ref":"ISO 14001:2015 Introduction"},{"t":"single","q":"An 'environmental aspect' is defined as:","o":[["An element of an organization's activities, products or services that can interact with the environment",true],["A change to the environment resulting from an activity",false],["A legal requirement an organization must meet",false]],"p":1,"ref":"ISO 14001:2015 §3.2.2"},{"t":"single","q":"An 'environmental impact' is defined as:","o":[["A change to the environment, whether adverse or beneficial, resulting wholly or partially from environmental aspects",true],["An element of activities that can interact with the environment",false],["A documented objective set by top management",false]],"p":1,"ref":"ISO 14001:2015 §3.2.4"},{"t":"tf","q":"In ISO 14001:2015, an environmental aspect is the cause and an environmental impact is the effect.","a":true,"p":1,"ref":"ISO 14001:2015 §3.2.2, §3.2.4"},{"t":"single","q":"Which clause of ISO 14001:2015 addresses environmental aspects?","o":[["Clause 6.1.2",true],["Clause 4.1",false],["Clause 9.1.1",false]],"p":1,"ref":"ISO 14001:2015 §6.1.2"},{"t":"single","q":"What term does ISO 14001:2015 use for the legal requirements and other requirements an organization must or chooses to comply with?","o":[["Compliance obligations",true],["Significant aspects",false],["Environmental targets",false]],"p":1,"ref":"ISO 14001:2015 §3.2.9"},{"t":"single","q":"Which clause requires the organization to determine its environmental objectives?","o":[["Clause 6.2",true],["Clause 5.2",false],["Clause 7.4",false]],"p":1,"ref":"ISO 14001:2015 §6.2"},{"t":"tf","q":"ISO 14001:2015 requires an organization to consider a life cycle perspective when determining its environmental aspects.","a":true,"p":1,"ref":"ISO 14001:2015 §6.1.2"},{"t":"single","q":"Which clause covers emergency preparedness and response?","o":[["Clause 8.2",true],["Clause 6.1.1",false],["Clause 9.3",false]],"p":1,"ref":"ISO 14001:2015 §8.2"},{"t":"single","q":"The 'environmental policy' must be established by:","o":[["Top management",true],["The internal audit team",false],["Any interested party",false]],"p":1,"ref":"ISO 14001:2015 §5.2"},{"t":"tf","q":"Under ISO 14001:2015, the environmental policy must include a commitment to the protection of the environment, including prevention of pollution.","a":true,"p":1,"ref":"ISO 14001:2015 §5.2"},{"t":"single","q":"Which clause requires determination of external and internal issues relevant to the organization's purpose (its context)?","o":[["Clause 4.1",true],["Clause 6.2",false],["Clause 8.1",false]],"p":1,"ref":"ISO 14001:2015 §4.1"},{"t":"single","q":"Which clause addresses the needs and expectations of interested parties?","o":[["Clause 4.2",true],["Clause 4.3",false],["Clause 7.2",false]],"p":1,"ref":"ISO 14001:2015 §4.2"},{"t":"tf","q":"The environmental policy must include a commitment to fulfil the organization's compliance obligations.","a":true,"p":1,"ref":"ISO 14001:2015 §5.2"},{"t":"single","q":"Which clause covers monitoring, measurement, analysis and evaluation?","o":[["Clause 9.1.1",true],["Clause 8.2",false],["Clause 6.1.3",false]],"p":1,"ref":"ISO 14001:2015 §9.1.1"},{"t":"single","q":"Which clause specifically requires evaluation of compliance?","o":[["Clause 9.1.2",true],["Clause 9.1.1",false],["Clause 10.2",false]],"p":1,"ref":"ISO 14001:2015 §9.1.2"},{"t":"tf","q":"ISO 14001:2015 requires the organization to maintain documented information as evidence of its compliance evaluation results.","a":true,"p":1,"ref":"ISO 14001:2015 §9.1.2"},{"t":"single","q":"Which clause covers nonconformity and corrective action?","o":[["Clause 10.2",true],["Clause 10.1",false],["Clause 9.2",false]],"p":1,"ref":"ISO 14001:2015 §10.2"},{"t":"single","q":"Which clause covers operational planning and control?","o":[["Clause 8.1",true],["Clause 8.2",false],["Clause 7.1",false]],"p":1,"ref":"ISO 14001:2015 §8.1"},{"t":"single","q":"Which PDCA stage does internal audit (clause 9.2) belong to?","o":[["Check",true],["Plan",false],["Act",false]],"p":1,"ref":"ISO 14001:2015 Introduction (PDCA)"},{"t":"tf","q":"In ISO 14001:2015 the term 'documented information' replaces the older terms 'documents' and 'records'.","a":true,"p":1,"ref":"ISO 14001:2015 §3.3.2"}],"2":[{"t":"single","q":"A printing company uses solvent-based inks that evaporate during drying. Which is the aspect and which is the impact?","o":[["Aspect: emission of VOCs; Impact: air pollution / atmospheric degradation",true],["Aspect: air pollution; Impact: use of solvent inks",false],["Aspect: drying process; Impact: ink purchase cost",false]],"p":1,"ref":"ISO 14001:2015 §6.1.2"},{"t":"single","q":"When determining which environmental aspects are significant, the organization must:","o":[["Establish and apply criteria to determine significance",true],["Treat every aspect as significant by default",false],["Defer the decision to the certification body",false]],"p":1,"ref":"ISO 14001:2015 §6.1.2"},{"t":"single","q":"A facility discharges treated wastewater to a river under a permit. The permit limit is an example of:","o":[["A compliance obligation",true],["A significant environmental impact",false],["An emergency situation",false]],"p":1,"ref":"ISO 14001:2015 §3.2.9, §6.1.3"},{"t":"single","q":"Applying a life cycle perspective when determining aspects means the organization should consider:","o":[["Stages it can control or influence, e.g. raw material acquisition, design, use, end-of-life",true],["Only the emissions from its own production line",false],["Only the disposal stage of the product",false]],"p":1,"ref":"ISO 14001:2015 §6.1.2, A.6.1.2"},{"t":"single","q":"An objective states: 'Reduce water consumption by 15% within two years.' This best demonstrates that objectives should be:","o":[["Measurable (where practicable) and monitored",true],["Always financial in nature",false],["Set only by the certification auditor",false]],"p":1,"ref":"ISO 14001:2015 §6.2.1"},{"t":"multi","q":"Which of the following are required characteristics of environmental objectives under clause 6.2.1?","o":[["Consistent with the environmental policy",true],["Monitored",true],["Communicated and updated as appropriate",true],["Expressed only in monetary units",false]],"p":2},{"t":"multi","q":"When planning actions to achieve environmental objectives (clause 6.2.2), the organization must determine:","o":[["What will be done",true],["What resources will be required",true],["Who will be responsible",true],["The exact salary of each responsible person",false]],"p":2},{"t":"single","q":"A maintenance procedure controlling how solvent is handled to prevent spills is an example of:","o":[["Operational control (clause 8.1)",true],["Compliance evaluation (clause 9.1.2)",false],["Management review (clause 9.3)",false]],"p":1,"ref":"ISO 14001:2015 §8.1"},{"t":"single","q":"For an outsourced process that affects the EMS, clause 8.1 requires the organization to:","o":[["Ensure the process is controlled or influenced and define the type and extent of control",true],["Ignore it because it is performed by a third party",false],["Transfer all compliance obligations to the supplier permanently",false]],"p":1,"ref":"ISO 14001:2015 §8.1"},{"t":"single","q":"A chemical storage tank could rupture during an earthquake. Clause 8.2 requires the organization to:","o":[["Establish processes to prepare for and respond to potential emergency situations",true],["Only report the risk to management review once a year",false],["Treat it solely as a compliance obligation",false]],"p":1,"ref":"ISO 14001:2015 §8.2"},{"t":"multi","q":"Under clause 8.2, emergency preparedness and response processes should include:","o":[["Planning actions to prevent or mitigate adverse environmental impacts",true],["Periodically testing the planned response actions where practicable",true],["Reviewing and revising processes after tests or actual emergencies",true],["Eliminating all monitoring during normal operations",false]],"p":2},{"t":"single","q":"Monitoring stack emissions monthly against a regulatory limit primarily supports which clauses?","o":[["9.1.1 monitoring/measurement and 9.1.2 evaluation of compliance",true],["6.2 objectives only",false],["5.1 leadership only",false]],"p":1,"ref":"ISO 14001:2015 §9.1.1, §9.1.2"},{"t":"multi","q":"Which inputs are relevant when determining the scope of the EMS (clause 4.3)?","o":[["External and internal issues (4.1)",true],["Compliance obligations (4.2 / 6.1.3)",true],["Its organizational units, functions and physical boundaries",true],["The auditor's personal preference",false]],"p":2},{"t":"single","q":"Interested parties relevant to an EMS could include neighbours complaining about odour. Clause 4.2 requires the organization to determine:","o":[["Which of their needs and expectations become compliance obligations",true],["That all expectations automatically become legal requirements",false],["That such parties be excluded from consideration",false]],"p":1,"ref":"ISO 14001:2015 §4.2"},{"t":"single","q":"Top management demonstrating leadership (clause 5.1) includes:","o":[["Ensuring the EMS achieves its intended outcomes and integrating EMS requirements into business processes",true],["Personally performing every monitoring task",false],["Delegating all accountability to the EMS coordinator",false]],"p":1,"ref":"ISO 14001:2015 §5.1"},{"t":"single","q":"A noise complaint from a nearby school is logged. Treating noise emission as the aspect, the impact is best described as:","o":[["Disturbance / degradation of the local acoustic environment and amenity",true],["The complaint letter itself",false],["The corrective action taken",false]],"p":1,"ref":"ISO 14001:2015 §3.2.4, §6.1.2"},{"t":"single","q":"During abnormal start-up conditions a boiler emits more particulates than normal. Clause 6.1.2 requires aspects to be determined considering:","o":[["Normal, abnormal conditions and reasonably foreseeable emergency situations",true],["Normal operating conditions only",false],["Only conditions specified by the customer",false]],"p":1,"ref":"ISO 14001:2015 §6.1.2"},{"t":"multi","q":"Which of the following are legitimate sources of an organization's compliance obligations under clause 6.1.3?","o":[["Mandatory legal requirements such as permits and regulations",true],["Voluntary commitments such as industry codes the organization adopts",true],["Agreements with community groups the organization signs",true],["Internal preferences that have not been adopted as commitments",false]],"p":2},{"t":"single","q":"A company sets a target to cut landfill waste. To know if it is succeeding, clause 9.1.1 requires it to:","o":[["Determine what needs to be monitored and measured and the methods to ensure valid results",true],["Wait for the certification audit to measure it",false],["Rely solely on the policy statement",false]],"p":1,"ref":"ISO 14001:2015 §9.1.1"},{"t":"single","q":"Continual improvement under ISO 14001:2015 is primarily aimed at:","o":[["Enhancing environmental performance",true],["Increasing the number of documents only",false],["Reducing the number of interested parties",false]],"p":1,"ref":"ISO 14001:2015 §10.3"},{"t":"single","q":"A nonconformity is found where a spill kit was missing at a fuel point. Clause 10.2 first requires the organization to:","o":[["React to the nonconformity and take action to control and correct it",true],["Immediately revise the environmental policy",false],["Schedule the next management review only",false]],"p":1,"ref":"ISO 14001:2015 §10.2"},{"t":"single","q":"Determining the 'context of the organization' (clause 4.1) supports the EMS by:","o":[["Identifying issues that affect the ability to achieve intended outcomes",true],["Listing only the products sold last year",false],["Replacing the need for objectives",false]],"p":1,"ref":"ISO 14001:2015 §4.1"},{"t":"single","q":"A risk-and-opportunity action (clause 6.1.1) related to a planned new production line should be:","o":[["Integrated and implemented into EMS processes and evaluated for effectiveness",true],["Documented but never acted upon",false],["Considered only after certification",false]],"p":1,"ref":"ISO 14001:2015 §6.1.1, §6.1.4"},{"t":"single","q":"Which best distinguishes an objective from a compliance obligation?","o":[["An objective is a result the organization sets to achieve; a compliance obligation is a requirement it must or chooses to meet",true],["They are identical terms in ISO 14001:2015",false],["An objective is always externally imposed while a compliance obligation is voluntary",false]],"p":1,"ref":"ISO 14001:2015 §3.2.5, §3.2.9"},{"t":"single","q":"A logistics firm wants to reduce fuel use across its fleet. Applying a life cycle perspective, an influence-stage action would be:","o":[["Specifying fuel-efficiency criteria when procuring vehicles and selecting carriers",true],["Ignoring procurement because vehicles are bought externally",false],["Only measuring tailpipe emissions of owned trucks",false]],"p":1,"ref":"ISO 14001:2015 §6.1.2, §8.1"},{"t":"short","q":"In your own words, explain the difference between an environmental aspect and an environmental impact, and give one paired example.","m":"Looks for: aspect = element of activity/product/service that interacts with the environment (cause); impact = the resulting change to the environment (effect); a valid cause-effect pair, e.g. aspect 'discharge of effluent' -> impact 'water pollution'.","p":2},{"t":"short","q":"Describe how an organization would use criteria to determine the significance of its environmental aspects (clause 6.1.2).","m":"Looks for: organization sets/applies defined significance criteria (e.g. severity/magnitude of impact, frequency/likelihood, legal/compliance relevance, interested-party concerns); applies them consistently to rank aspects; outputs significant aspects that feed objectives, controls and risks.","p":2}],"3":[{"t":"single","q":"An auditor finds the organization listed 'water pollution' as an environmental aspect on its register. The most accurate finding is:","o":[["The entry confuses impact with aspect; 'water pollution' is an impact, the aspect would be e.g. 'discharge of process effluent'",true],["The entry is correct because pollution is always an aspect",false],["Aspect and impact are interchangeable, so no issue exists",false]],"p":1,"ref":"ISO 14001:2015 §3.2.2, §3.2.4, §6.1.2"},{"t":"single","q":"A company claims it need not consider upstream raw-material extraction because it does not own those operations. Evaluate against clause 6.1.2:","o":[["Incorrect; life cycle perspective requires considering stages it can control AND those it can influence, even if not owned",true],["Correct; only owned operations are within scope",false],["Correct; life cycle perspective applies only to disposal",false]],"p":1,"ref":"ISO 14001:2015 §6.1.2, A.6.1.2"},{"t":"single","q":"An organization treats every aspect as 'significant' to be safe. The most defensible critique is:","o":[["Without applied criteria the determination is not meaningful and dilutes focus on truly significant aspects and controls",true],["This fully satisfies clause 6.1.2 because nothing is missed",false],["Significance criteria are prohibited by ISO 14001:2015",false]],"p":1,"ref":"ISO 14001:2015 §6.1.2"},{"t":"multi","q":"An auditor evaluates a compliance-evaluation process (clause 9.1.2). Which findings would indicate a conforming process?","o":[["The organization maintains and retains documented information of compliance results",true],["The organization determines the frequency at which compliance is evaluated",true],["The organization maintains knowledge and understanding of its compliance status",true],["The organization evaluates compliance only when a regulator visits",false]],"p":2},{"t":"single","q":"A firm's policy commits to 'prevention of pollution' but its only objective is cost reduction with no environmental performance link. The gap is:","o":[["Objectives are not consistent with the environmental policy as required by clause 6.2.1",true],["No gap; objectives may be unrelated to the policy",false],["The policy must be deleted",false]],"p":1,"ref":"ISO 14001:2015 §5.2, §6.2.1"},{"t":"single","q":"During a flood, contaminated runoff escaped offsite. The EMS had identified the flood scenario but never tested the response. The strongest nonconformity is against:","o":[["Clause 8.2, which requires periodic testing of planned response actions where practicable",true],["Clause 5.2 environmental policy",false],["Clause 7.4 communication",false]],"p":1,"ref":"ISO 14001:2015 §8.2"},{"t":"multi","q":"Which scenarios correctly pair an aspect with its impact?","o":[["Aspect: energy consumption from grid electricity; Impact: depletion of fossil resources and associated emissions",true],["Aspect: discharge of cooling water at elevated temperature; Impact: thermal alteration of receiving water ecosystem",true],["Aspect: generation of hazardous waste; Impact: land and groundwater contamination if mismanaged",true],["Aspect: groundwater contamination; Impact: solvent use",false]],"p":2},{"t":"single","q":"An organization's scope (clause 4.3) excludes a leased warehouse where significant aspects occur, purely to reduce audit effort. Assess this:","o":[["Not acceptable; the EMS must not exclude activities, products and services that have significant environmental aspects within its control or influence",true],["Acceptable; scope is entirely at the organization's discretion regardless of significant aspects",false],["Acceptable; leased sites are always out of scope",false]],"p":1,"ref":"ISO 14001:2015 §4.3"},{"t":"single","q":"A monitoring result shows a discharge consistently near but below its permit limit, with no margin. The best EMS response under clause 9.1.1/6.1.1 is:","o":[["Treat the trend as a risk/opportunity and act before a nonconformity or noncompliance occurs",true],["Take no action because no limit was exceeded",false],["Remove the parameter from monitoring to simplify reporting",false]],"p":1,"ref":"ISO 14001:2015 §9.1.1, §6.1.1"},{"t":"multi","q":"When evaluating leadership commitment (clause 5.1), which evidence would support conformity?","o":[["Top management ensures the environmental policy and objectives are compatible with strategic direction",true],["Top management ensures resources for the EMS are available",true],["Top management promotes continual improvement and supports other relevant roles to demonstrate leadership",true],["Top management delegates all accountability for EMS effectiveness to the consultant",false]],"p":2},{"t":"single","q":"A company adopted a voluntary industry charter publicly but treats it as optional internally. Under clause 6.1.3 this charter should be:","o":[["Treated as a compliance obligation it has chosen to adopt, and managed accordingly",true],["Ignored because it is not law",false],["Counted only as an objective, never an obligation",false]],"p":1,"ref":"ISO 14001:2015 §6.1.3"},{"t":"single","q":"An auditor sees objectives set but no plan defining responsibilities, resources, timeframe, or how results will be evaluated. The nonconformity is against:","o":[["Clause 6.2.2, planning actions to achieve environmental objectives",true],["Clause 4.1 context",false],["Clause 10.3 continual improvement",false]],"p":1,"ref":"ISO 14001:2015 §6.2.2"},{"t":"multi","q":"Which of the following are valid life cycle perspective considerations for a product manufacturer (clause 6.1.2 / A.6.1.2)?","o":[["Design choices that reduce material use and improve recyclability",true],["Specifying environmental criteria for procured components",true],["Providing information on environmentally sound end-of-life handling",true],["Considering only emissions during the manufacturing shift",false]],"p":2},{"t":"single","q":"After a corrective action for a recurring oil leak, the EMS closed the issue but the leak recurred. The deficiency is most likely:","o":[["Root cause was not adequately determined, so corrective action did not eliminate the cause (clause 10.2)",true],["The leak should be reclassified as an objective",false],["Corrective action is not required for environmental issues",false]],"p":1,"ref":"ISO 14001:2015 §10.2"},{"t":"single","q":"An organization measures emissions with an uncalibrated instrument and reports compliance. Under clause 9.1.1 the core problem is:","o":[["The methods do not ensure valid results, undermining both monitoring and the compliance evaluation that relies on it",true],["Calibration is irrelevant to environmental monitoring",false],["Only the documentation format is wrong",false]],"p":1,"ref":"ISO 14001:2015 §9.1.1"},{"t":"single","q":"A new regulation tightens an emission limit next year. The most proactive EMS treatment is to handle it through:","o":[["Compliance obligations (6.1.3), risks and opportunities (6.1.1), and possibly an objective (6.2) with planned actions",true],["Internal audit scheduling only",false],["The communication plan only, with no operational change",false]],"p":1,"ref":"ISO 14001:2015 §6.1.1, §6.1.3, §6.2"},{"t":"multi","q":"An emergency response process (clause 8.2) is being reviewed. Which elements indicate maturity?","o":[["Documented procedures linked to identified emergency aspects/scenarios",true],["Periodic drills with recorded outcomes and follow-up actions",true],["Revision of the process after an actual incident",true],["Reliance on memory of staff with no documented information",false]],"p":2},{"t":"single","q":"A site lists 'use of natural gas' as an aspect and 'climate change' as the impact. The most precise critique is:","o":[["The pairing is reasonable but the impact is better stated as 'contribution to greenhouse gas emissions / climate change'; the cause-effect logic is sound",true],["The pairing reverses cause and effect",false],["Energy use can never be an environmental aspect",false]],"p":1,"ref":"ISO 14001:2015 §3.2.2, §3.2.4"},{"t":"single","q":"Two facilities share a permit limit; only one is monitored. For evaluation of compliance (clause 9.1.2) this is problematic because:","o":[["Compliance status cannot be reliably determined for the unmonitored facility, so the evaluation is incomplete",true],["Monitoring one facility is always sufficient for any permit",false],["Clause 9.1.2 does not require knowledge of compliance status",false]],"p":1,"ref":"ISO 14001:2015 §9.1.2"},{"t":"single","q":"A management review (clause 9.3) considers audit results and policy but omits compliance-obligation status and performance trends. The gap is:","o":[["Required inputs to management review are incomplete, e.g. fulfilment of compliance obligations and environmental performance information",true],["Management review inputs are entirely optional",false],["Only the meeting minutes format is wrong",false]],"p":1,"ref":"ISO 14001:2015 §9.3"},{"t":"single","q":"An organization wants to demonstrate continual improvement (clause 10.3). The strongest evidence is:","o":[["Demonstrated enhancement of environmental performance over time, traceable to actions and objectives",true],["An increase only in the number of procedures issued",false],["A larger interested-parties list",false]],"p":1,"ref":"ISO 14001:2015 §10.3"},{"t":"single","q":"A significant aspect feeds nothing downstream: no objective, no control, no monitoring. The integration gap is best framed as failure to:","o":[["Use the significant aspect as an input to operational controls (8.1), objectives (6.2) and monitoring (9.1) as appropriate",true],["Delete the aspect from the register",false],["Reclassify it as an interested party",false]],"p":1,"ref":"ISO 14001:2015 §6.1.2, §8.1, §6.2, §9.1.1"},{"t":"multi","q":"Which would be appropriate criteria for determining the significance of environmental aspects?","o":[["Severity and scale of the potential impact",true],["Likelihood/frequency of occurrence",true],["Relevance to compliance obligations and interested-party concerns",true],["The aspect's alphabetical position in the register",false]],"p":2},{"t":"single","q":"A contractor performs onsite degreasing using the client's solvents. Regarding operational control (clause 8.1), the client should:","o":[["Define the type and extent of control over the contractor's process consistent with EMS needs",true],["Assume no responsibility because a contractor performs the work",false],["Transfer all EMS obligations permanently to the contractor",false]],"p":1,"ref":"ISO 14001:2015 §8.1"},{"t":"single","q":"An organization argues that interested parties' expectations never affect it. Evaluate under clause 4.2:","o":[["It must still determine relevant interested parties and their relevant needs/expectations, and which become compliance obligations",true],["It may ignore interested parties entirely if it chooses",false],["All interested-party expectations automatically become legal requirements",false]],"p":1,"ref":"ISO 14001:2015 §4.2, §6.1.3"},{"t":"single","q":"A company documents its context (4.1) once at certification and never revisits it despite a major change in operations. The weakness is:","o":[["Context, issues, risks and aspects should be reviewed and updated when changes occur, supporting the ongoing suitability of the EMS",true],["Context only ever needs to be determined a single time",false],["Changes in operations are irrelevant to the EMS",false]],"p":1,"ref":"ISO 14001:2015 §4.1, §6.1.1"},{"t":"multi","q":"Which would be valid 'risks and opportunities' (clause 6.1.1) for an EMS to address?","o":[["A regulatory change that could create a noncompliance risk",true],["An opportunity to reduce energy cost and emissions via process redesign",true],["A potential emergency situation with adverse environmental consequences",true],["The colour scheme of the EMS manual cover",false]],"p":2},{"t":"single","q":"An organization sets an objective but cannot show how progress is tracked or who owns it. Beyond 6.2.2, the auditor should also question conformity with:","o":[["Clause 9.1.1, since the organization has not determined what to monitor/measure to evaluate environmental performance",true],["Clause 8.2 emergency preparedness",false],["Clause 5.2 environmental policy wording only",false]],"p":1,"ref":"ISO 14001:2015 §6.2.2, §9.1.1"},{"t":"single","q":"A supplier's poor waste handling causes reputational and compliance exposure for the buying organization. The most complete EMS treatment links:","o":[["Life cycle perspective (6.1.2), operational control/influence over the outsourced/supplier process (8.1), and risks and opportunities (6.1.1)",true],["Internal audit scheduling (9.2) alone",false],["The communication clause (7.4) alone",false]],"p":1,"ref":"ISO 14001:2015 §6.1.2, §8.1, §6.1.1"},{"t":"short","q":"A factory's aspect register lists impacts in the 'aspect' column and vice versa, and applies no significance criteria. Outline the nonconformities and how you would correct the register.","m":"Looks for: identifies confusion of aspect (cause) vs impact (effect) and the need to re-map cause-effect pairs; notes absence of applied significance criteria as a 6.1.2 gap; correction includes defining/applying criteria, deriving significant aspects, and linking them to controls/objectives/monitoring.","p":3},{"t":"short","q":"Explain how the life cycle perspective in clause 6.1.2 changes the way an organization identifies and manages aspects compared with a 'gate-to-gate' (own-site only) view.","m":"Looks for: life cycle perspective extends consideration beyond own operations to stages the organization can control or influence (raw material acquisition, design, procurement, transport, use, end-of-life); not a full LCA; influences procurement criteria, design, and information to users; broadens aspects and controls vs own-site-only view.","p":3},{"t":"short","q":"Describe the relationship between clauses 9.1.1 (monitoring/measurement) and 9.1.2 (evaluation of compliance), and why valid measurement methods matter for both.","m":"Looks for: 9.1.1 determines what/how to monitor and ensures methods give valid results; 9.1.2 uses results (and other evidence) to determine and maintain knowledge of compliance status and retain documented information; invalid/uncalibrated methods undermine reliability of compliance conclusions; both feed corrective action and management review.","p":3},{"t":"short","q":"An emergency scenario (chemical spill reaching a storm drain) was identified but never planned for or tested. Walk through the clause 8.2 requirements the organization failed to meet and the actions needed to conform.","m":"Looks for: 8.2 requires processes to prepare for and respond to emergencies; plan actions to prevent/mitigate adverse impacts; respond to actual emergencies; periodically test response where practicable; review/revise after tests or incidents; provide information/training to relevant parties; corrective actions: develop and document response procedures, run drills, record and improve.","p":3},{"t":"short","q":"Top management states the EMS is the coordinator's responsibility and is not integrated into business processes. Critique this against clause 5.1 leadership requirements and recommend improvements.","m":"Looks for: 5.1 requires top management to take accountability for EMS effectiveness, ensure policy/objectives align with strategic direction, integrate EMS requirements into business processes, ensure resources, communicate importance, ensure intended outcomes, support and direct persons, promote continual improvement; cannot fully delegate accountability; recommendations include leadership engagement, integration into planning/operations, resourcing, and performance review.","p":3}]}},"ISO 45001 interpretation":{"levels":{"1":[{"t":"single","q":"What does the abbreviation OH&S stand for in ISO 45001:2018?","o":[["Occupational Health and Safety",true],["Operational Hazard and Safety",false],["Organizational Health and Standards",false]],"p":1,"ref":"ISO 45001:2018"},{"t":"single","q":"ISO 45001:2018 is structured according to which framework common to modern ISO management system standards?","o":[["The High Level Structure (Annex SL)",true],["The Deming-only structure",false],["A standard unique to OH&S with no shared structure",false]],"p":1,"ref":"ISO 45001:2018"},{"t":"single","q":"Which sequence correctly orders the hierarchy of controls from most to least effective?","o":[["Elimination, substitution, engineering controls, administrative controls, PPE",true],["PPE, administrative controls, engineering controls, substitution, elimination",false],["Engineering controls, elimination, PPE, substitution, administrative controls",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"In the hierarchy of controls, which option is considered the most effective?","o":[["Elimination of the hazard",true],["Provision of personal protective equipment",false],["Administrative controls such as procedures",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"Which control measure sits at the lowest (least preferred) level of the hierarchy of controls?","o":[["Personal protective equipment (PPE)",true],["Substitution",false],["Engineering controls",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"tf","q":"ISO 45001:2018 requires top management to demonstrate leadership and commitment with respect to the OH&S management system.","a":true,"p":1,"ref":"ISO 45001:2018 §5.1"},{"t":"tf","q":"Under ISO 45001:2018, worker participation and consultation are optional and may be omitted at the organization's discretion.","a":false,"p":1,"ref":"ISO 45001:2018 §5.4"},{"t":"single","q":"Which clause of ISO 45001:2018 addresses hazard identification and assessment of risks and opportunities?","o":[["Clause 6.1.2",true],["Clause 9.2",false],["Clause 7.2",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2"},{"t":"single","q":"In ISO 45001:2018, a 'worker' is defined as a person who:","o":[["Performs work or work-related activities that are under the control of the organization",true],["Is only a permanent full-time employee on payroll",false],["Holds a management position exclusively",false]],"p":1,"ref":"ISO 45001:2018 §3.3"},{"t":"tf","q":"ISO 45001:2018 applies only to manufacturing organizations and not to service organizations.","a":false,"p":1,"ref":"ISO 45001:2018 §1"},{"t":"single","q":"Which clause requires the organization to determine and have access to applicable legal requirements and other requirements?","o":[["Clause 6.1.3",true],["Clause 8.2",false],["Clause 5.2",false]],"p":1,"ref":"ISO 45001:2018 §6.1.3"},{"t":"single","q":"Establishing, implementing and maintaining processes for emergency preparedness and response is required by which clause?","o":[["Clause 8.2",true],["Clause 6.2",false],["Clause 9.3",false]],"p":1,"ref":"ISO 45001:2018 §8.2"},{"t":"tf","q":"The OH&S policy must include a commitment to the prevention of injury and ill health.","a":true,"p":1,"ref":"ISO 45001:2018 §5.2"},{"t":"single","q":"Which clause of ISO 45001:2018 deals with incident investigation, nonconformity and corrective action?","o":[["Clause 10.2",true],["Clause 7.4",false],["Clause 6.2",false]],"p":1,"ref":"ISO 45001:2018 §10.2"},{"t":"single","q":"OH&S objectives, according to ISO 45001:2018, should be:","o":[["Consistent with the OH&S policy and, where practicable, measurable",true],["Set only by external auditors",false],["Kept confidential from workers",false]],"p":1,"ref":"ISO 45001:2018 §6.2.1"},{"t":"tf","q":"Substitution in the hierarchy of controls means replacing the hazard with something less hazardous.","a":true,"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"Which clause requires the organization to establish processes for consultation and participation of workers?","o":[["Clause 5.4",true],["Clause 9.1",false],["Clause 7.1",false]],"p":1,"ref":"ISO 45001:2018 §5.4"},{"t":"tf","q":"Internal audit and management review are part of the 'Check' stage of the Plan-Do-Check-Act cycle in ISO 45001:2018.","a":true,"p":1,"ref":"ISO 45001:2018 §9"},{"t":"single","q":"Personal protective equipment (PPE) is best described in ISO 45001:2018's hierarchy of controls as a control that:","o":[["Protects the worker but does not remove the hazard",true],["Eliminates the hazard at its source",false],["Is the preferred first line of defense",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"Which clause addresses operational planning and control within ISO 45001:2018?","o":[["Clause 8.1",true],["Clause 6.1",false],["Clause 9.2",false]],"p":1,"ref":"ISO 45001:2018 §8.1"},{"t":"tf","q":"Engineering controls (e.g., machine guarding, ventilation) rank above administrative controls in the hierarchy of controls.","a":true,"p":1,"ref":"ISO 45001:2018 §8.1.2"}],"2":[{"t":"single","q":"When determining controls or considering changes to existing controls, ISO 45001:2018 requires the organization to do so in accordance with which principle?","o":[["The hierarchy of controls",true],["The lowest-cost-first principle",false],["The PPE-first principle",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"Which of the following is an example of an administrative control rather than an engineering control?","o":[["Job rotation to limit exposure duration",true],["Installation of local exhaust ventilation",false],["Enclosing a noisy machine in an acoustic booth",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"multi","q":"Which of the following must the organization consider when establishing processes for hazard identification (Clause 6.1.2.1)?","o":[["Routine and non-routine activities and situations",true],["Past relevant incidents and their causes",true],["Human factors and how work is organized",true],["Only the preferences of senior managers",false]],"p":2,"ref":"ISO 45001:2018 §6.1.2.1"},{"t":"multi","q":"Under worker participation and consultation (Clause 5.4), which matters require consultation with non-managerial workers?","o":[["Determining the controls for hazards and OH&S risks",true],["Determining the needs and expectations of interested parties",true],["Establishing the OH&S policy and objectives",false],["Investigating incidents and nonconformities",false]],"p":2,"ref":"ISO 45001:2018 §5.4"},{"t":"single","q":"ISO 45001:2018 distinguishes between consultation and participation of workers. Consultation primarily refers to:","o":[["Seeking views before making a decision",true],["Final sign-off authority by workers on all decisions",false],["Mandatory voting on every operational matter",false]],"p":1,"ref":"ISO 45001:2018 §3.5, §5.4"},{"t":"multi","q":"Which of the following are 'other requirements' (as distinct from legal requirements) that an organization may need to address under Clause 6.1.3?","o":[["Voluntary commitments to standards or codes of practice",true],["Contractual obligations and agreements with workers",true],["A government statute that imposes a permissible exposure limit",false],["A criminal penalty defined in national OH&S law",false]],"p":2,"ref":"ISO 45001:2018 §6.1.3"},{"t":"single","q":"Management of change (Clause 8.1.3) requires the organization to establish processes for the implementation and control of:","o":[["Planned changes that affect OH&S performance",true],["Only emergency changes after an incident occurs",false],["Changes to financial accounting systems",false]],"p":1,"ref":"ISO 45001:2018 §8.1.3"},{"t":"single","q":"Regarding procurement (Clause 8.1.4.1), the organization must establish processes to control the procurement of products and services in order to:","o":[["Ensure conformity to its OH&S management system",true],["Maximize purchasing discounts only",false],["Avoid documenting supplier information",false]],"p":1,"ref":"ISO 45001:2018 §8.1.4.1"},{"t":"single","q":"For contractors (Clause 8.1.4.2), the organization is required to coordinate its procurement processes with contractors to identify hazards and:","o":[["Assess and control the OH&S risks arising from the contractors' activities and operations",true],["Transfer all OH&S liability entirely to the contractor",false],["Exclude contractor workers from the OH&S management system",false]],"p":1,"ref":"ISO 45001:2018 §8.1.4.2"},{"t":"multi","q":"Which elements are required of the emergency preparedness and response process under Clause 8.2?","o":[["Establishing a planned response to emergency situations",true],["Periodically testing and exercising the planned response capability",true],["Communicating relevant information to workers on their duties",true],["Eliminating the need for any first-aid provision",false]],"p":2,"ref":"ISO 45001:2018 §8.2"},{"t":"single","q":"When an incident or nonconformity occurs, Clause 10.2 requires the organization to react and, as applicable, take action to control and correct it and to:","o":[["Evaluate the need for action to eliminate the root cause(s) so it does not recur",true],["Immediately discipline the worker involved",false],["Close the case without analysis to save time",false]],"p":1,"ref":"ISO 45001:2018 §10.2"},{"t":"single","q":"Which of the following best reflects the intent of 'opportunities for OH&S improvement' in Clause 6.1.2.3?","o":[["Improving how work is organized, the work environment, and adapting work to workers",true],["Increasing production output regardless of OH&S impact",false],["Reducing the number of consultation meetings with workers",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2.3"},{"t":"multi","q":"Which of the following are barriers to worker participation that ISO 45001:2018 (Clause 5.4) expects the organization to identify and remove or minimize?","o":[["Failure to respond to worker inputs",true],["Language or literacy barriers",true],["Reprisals or threats of reprisal",true],["Providing training on OH&S matters",false]],"p":2,"ref":"ISO 45001:2018 §5.4"},{"t":"tf","q":"Under ISO 45001:2018, the assessment of OH&S risks (Clause 6.1.2.2) must use a methodology and criteria that are defined with respect to scope, nature and timing to ensure it is proactive rather than reactive.","a":true,"p":1,"ref":"ISO 45001:2018 §6.1.2.2"},{"t":"single","q":"Which clause requires the organization to plan actions to address risks and opportunities, legal and other requirements, and emergency situations, and to integrate them into its processes?","o":[["Clause 6.1.4",true],["Clause 7.5",false],["Clause 9.3",false]],"p":1,"ref":"ISO 45001:2018 §6.1.4"},{"t":"single","q":"An organization plans to introduce a new automated press into an existing line. Under ISO 45001:2018, this is most directly an application of which clause?","o":[["Management of change (8.1.3)",true],["Management review (9.3)",false],["Documented information (7.5)",false]],"p":1,"ref":"ISO 45001:2018 §8.1.3"},{"t":"single","q":"Which statement correctly distinguishes a 'hazard' from an 'OH&S risk' under ISO 45001:2018?","o":[["A hazard is a source with potential to cause harm; OH&S risk combines likelihood of exposure and severity of harm",true],["A hazard and an OH&S risk are identical terms",false],["A hazard is always quantitative while OH&S risk is always qualitative",false]],"p":1,"ref":"ISO 45001:2018 §3.19, §3.21"},{"t":"multi","q":"When establishing OH&S objectives (Clause 6.2.1), the organization should take into account which of the following?","o":[["Applicable requirements and the results of risk and opportunity assessment",true],["The results of consultation with workers",true],["The OH&S policy",true],["The salary expectations of senior executives",false]],"p":2,"ref":"ISO 45001:2018 §6.2.1"},{"t":"single","q":"In planning to achieve OH&S objectives (Clause 6.2.2), the organization must determine all of the following EXCEPT:","o":[["The market price of competitors' products",true],["What will be done and what resources will be required",false],["Who will be responsible and when it will be completed",false]],"p":1,"ref":"ISO 45001:2018 §6.2.2"},{"t":"single","q":"A noisy grinding operation cannot be eliminated. Following the hierarchy of controls, which option should be evaluated BEFORE issuing hearing protection?","o":[["Engineering controls such as enclosure or damping",true],["Posting a 'wear hearing protection' sign",false],["Recording the exposure and taking no further action",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"tf","q":"Outsourcing a function (Clause 8.1.4.3) relieves the organization of responsibility for ensuring outsourced functions and processes are controlled.","a":false,"p":1,"ref":"ISO 45001:2018 §8.1.4.3"},{"t":"tf","q":"Top management is required to take overall responsibility and accountability for the prevention of work-related injury and ill health.","a":true,"p":1,"ref":"ISO 45001:2018 §5.1"},{"t":"short","q":"Explain why ISO 45001:2018 requires participation of workers (not just consultation) and give one example matter for which participation of non-managerial workers is specifically emphasized.","m":"Looks for: participation = involvement in decision-making; emphasis on empowering workers in matters such as determining mechanisms for participation, hazard identification, determining controls, investigating incidents, or establishing the participation process (Clause 5.4).","p":2},{"t":"short","q":"Describe how the 'legal and other requirements' process (6.1.3) connects to operational planning and control (8.1) within an OH&S management system.","m":"Looks for: requirements must be determined, kept up to date, communicated, and taken into account when establishing/implementing/maintaining the OHSMS; operational controls and criteria in 8.1 must ensure compliance with those requirements and be integrated into processes.","p":2},{"t":"single","q":"Evaluation of compliance with legal and other requirements (9.1.2) requires the organization to:","o":[["Determine the frequency and methods of evaluation, evaluate compliance, and maintain knowledge of its compliance status",true],["Rely solely on the absence of regulator visits as proof of compliance",false],["Evaluate compliance only after a serious incident",false]],"p":1,"ref":"ISO 45001:2018 §9.1.2"},{"t":"single","q":"Which of the following is the best example of applying 'engineering controls' to a chemical inhalation hazard?","o":[["Installing local exhaust ventilation at the point of generation",true],["Rotating workers to limit individual exposure time",false],["Issuing half-mask respirators to exposed workers",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"multi","q":"Which of the following are required of the OH&S policy under Clause 5.2?","o":[["A commitment to fulfil legal requirements and other requirements",true],["A commitment to the elimination of hazards and reduction of OH&S risks",true],["A commitment to consultation and participation of workers",true],["A commitment to maximize shareholder returns",false]],"p":2,"ref":"ISO 45001:2018 §5.2"}],"3":[{"t":"single","q":"A facility eliminates a solvent-based degreasing process and replaces it entirely with a mechanical cleaning method that uses no chemicals. In hierarchy-of-controls terms, this change is BEST classified as:","o":[["Elimination of the chemical hazard",true],["Substitution of one chemical for a less hazardous one",false],["An engineering control on the existing chemical process",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"A company replaces a high-toxicity solvent with a lower-toxicity solvent that performs the same function. This is an example of:","o":[["Substitution",true],["Elimination",false],["Administrative control",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"multi","q":"During hazard identification (6.1.2.1), an organization must take into account which of the following situations?","o":[["Emergency situations",true],["Situations not under the organization's control occurring near the workplace that could cause injury",true],["Actual or proposed changes in organization, operations, processes and activities",true],["Only hazards that have already caused a recordable incident",false]],"p":2,"ref":"ISO 45001:2018 §6.1.2.1"},{"t":"single","q":"An auditor finds that an organization assesses OH&S risks only after incidents are reported. Which ISO 45001:2018 requirement is MOST directly not being met?","o":[["The requirement for proactive hazard identification and risk assessment (6.1.2)",true],["The requirement for management review inputs (9.3)",false],["The requirement for control of documented information (7.5.3)",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2"},{"t":"multi","q":"An organization is onboarding a maintenance contractor to work alongside its own staff. Which ISO 45001:2018 obligations apply?","o":[["Coordinate procurement processes to identify and control OH&S risks from the contractor's activities (8.1.4.2)",true],["Ensure contractors and their workers meet the organization's OH&S requirements (8.1.4.2)",true],["Consider hazards the contractor's operations create for the organization's workers and vice versa (8.1.4.2)",true],["Exclude contractor activities from the organization's OH&S management system scope",false]],"p":2,"ref":"ISO 45001:2018 §8.1.4.2"},{"t":"single","q":"A change in shift pattern increases the number of consecutive night shifts. Under ISO 45001:2018, the human-factors and fatigue implications should be evaluated through which process?","o":[["Management of change (8.1.3), drawing on hazard identification (6.1.2.1)",true],["Control of documented information (7.5)",false],["Internal audit (9.2) only after implementation",false]],"p":1,"ref":"ISO 45001:2018 §8.1.3"},{"t":"single","q":"After a near-miss involving a forklift and a pedestrian, the organization installs physical barriers separating pedestrian walkways from forklift routes. Where does this control sit in the hierarchy, and why is it preferred over a 'pedestrians keep clear' rule?","o":[["Engineering control; it reduces reliance on individual behavior and is more effective than an administrative rule",true],["Administrative control; it is equivalent in effectiveness to signage",false],["PPE; it protects the individual pedestrian directly",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"multi","q":"Which of the following are valid inputs to the incident investigation and corrective action process (10.2) that help determine whether similar nonconformities exist or could occur?","o":[["Reviewing and analyzing the incident or nonconformity",true],["Determining the causes, including system or management-system causes",true],["Determining if similar incidents have occurred or could occur elsewhere",true],["Limiting analysis strictly to the individual worker's error",false]],"p":2,"ref":"ISO 45001:2018 §10.2"},{"t":"single","q":"An organization's OH&S policy commits to 'comply with applicable laws.' During an audit it cannot demonstrate how it evaluates compliance. Which clause is implicated?","o":[["Evaluation of compliance (9.1.2)",true],["Communication (7.4)",false],["Competence (7.2)",false]],"p":1,"ref":"ISO 45001:2018 §9.1.2"},{"t":"single","q":"Which scenario best demonstrates the difference between 'correction' and 'corrective action' under Clause 10.2?","o":[["Cleaning up a chemical spill is a correction; redesigning the transfer system to prevent spills is corrective action",true],["Both terms mean cleaning up the spill",false],["Correction eliminates the root cause while corrective action only contains the immediate effect",false]],"p":1,"ref":"ISO 45001:2018 §10.2"},{"t":"multi","q":"Top management leadership and commitment (5.1) is demonstrated by which of the following actions?","o":[["Ensuring the OH&S policy and objectives are compatible with the strategic direction",true],["Ensuring integration of OHSMS requirements into business processes",true],["Developing, leading and promoting a culture that supports the OHSMS",true],["Delegating all OH&S accountability to a single safety officer with no management involvement",false]],"p":2,"ref":"ISO 45001:2018 §5.1"},{"t":"single","q":"A risk-assessment methodology that ranks hazards purely by how many incidents occurred last year would MOST likely fail which ISO 45001:2018 expectation?","o":[["That the methodology be proactive rather than primarily reactive (6.1.2.2)",true],["That objectives be measurable (6.2.1)",false],["That documented information be version-controlled (7.5.3)",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2.2"},{"t":"single","q":"An organization purchases a new chemical without checking whether a safer alternative exists or whether handling controls are feasible. Which combined ISO 45001:2018 requirements are most directly weakened?","o":[["Procurement (8.1.4.1) together with the hierarchy of controls (8.1.2)",true],["Management review (9.3) together with internal audit (9.2)",false],["Documented information (7.5) together with communication (7.4)",false]],"p":1,"ref":"ISO 45001:2018 §8.1.4.1, §8.1.2"},{"t":"multi","q":"Which of the following are required outputs/considerations of the management review (9.3) relevant to OH&S?","o":[["Status of actions from previous management reviews",true],["Extent to which OH&S objectives have been met",true],["Adequacy of resources for maintaining an effective OHSMS",true],["Personal performance appraisals of every individual worker",false]],"p":2,"ref":"ISO 45001:2018 §9.3"},{"t":"single","q":"Workers report that they fear reporting hazards because previous reporters were reassigned to undesirable tasks. Which ISO 45001:2018 requirement is most directly compromised?","o":[["Protecting workers from reprisals to enable participation (5.4)",true],["Calibration of monitoring equipment (9.1.1)",false],["Control of externally provided processes (8.1.4.3)",false]],"p":1,"ref":"ISO 45001:2018 §5.4"},{"t":"single","q":"During emergency response testing, the organization discovers evacuation routes are obstructed. Under ISO 45001:2018, the correct response is to:","o":[["Revise the planned response and, where appropriate, update related processes after testing (8.2)",true],["Stop testing emergency plans to avoid finding further problems",false],["Treat this only as a documentation issue under 7.5",false]],"p":1,"ref":"ISO 45001:2018 §8.2"},{"t":"multi","q":"Which actions are consistent with applying the hierarchy of controls correctly when a manual-handling injury risk is identified?","o":[["First consider redesigning the task to eliminate the lift",true],["Consider mechanical aids (engineering) before relying on training",true],["Use safe-lifting training and supervision as administrative controls when higher controls are insufficient",true],["Issue back belts (PPE) as the first and only measure",false]],"p":2,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"An organization integrates OH&S risk acceptance criteria into its enterprise risk register but never consults non-managerial workers on how controls are determined. Which requirement is unmet?","o":[["Consultation and participation of workers on determining controls (5.4)",true],["Resources (7.1)",false],["Organizational knowledge (not part of ISO 45001)",false]],"p":1,"ref":"ISO 45001:2018 §5.4"},{"t":"single","q":"A contractor's worker is injured on site. The organization argues ISO 45001 does not apply because the worker is not its employee. Why is this interpretation incorrect?","o":[["The definition of 'worker' includes persons performing work under the organization's control, which can include contractors",true],["ISO 45001 only covers visitors, not contractors",false],["Contractors are covered by a separate certificate and never by the organization's OHSMS",false]],"p":1,"ref":"ISO 45001:2018 §3.3"},{"t":"multi","q":"Which of the following correctly describe the relationship between risks, opportunities, legal/other requirements, and planning in Clause 6.1?","o":[["The organization determines risks and opportunities that need to be addressed (6.1.1)",true],["It plans actions to address them and integrates those actions into OHSMS processes (6.1.4)",true],["Legal and other requirements are determined and taken into account (6.1.3)",true],["Opportunities need not be evaluated once risks are assessed",false]],"p":2,"ref":"ISO 45001:2018 §6.1"},{"t":"tf","q":"Under ISO 45001:2018, when planned changes are introduced (8.1.3), the organization should also review the consequences of unintended changes and take action to mitigate any adverse effects.","a":true,"p":1,"ref":"ISO 45001:2018 §8.1.3"},{"t":"tf","q":"An organization may exclude its highest-risk activity from the scope of its OH&S management system simply because it is difficult to control.","a":false,"p":1,"ref":"ISO 45001:2018 §4.3"},{"t":"single","q":"Which best illustrates an OH&S 'opportunity' as intended by Clause 6.1.2.3, rather than merely a risk control?","o":[["Adapting work, work organization and the work environment to workers to improve OH&S performance",true],["Adding another warning sign to an existing hazard",false],["Recording an injury in the incident log",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2.3"},{"t":"single","q":"A site's risk assessment ranks all controls as 'PPE required' regardless of hazard. An auditor should raise this as a finding primarily because it:","o":[["Fails to apply the hierarchy of controls, defaulting to the least effective measure (8.1.2)",true],["Violates documented information requirements (7.5)",false],["Breaches the communication clause (7.4)",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"For consultation and participation to be effective (5.4), ISO 45001:2018 expects the organization to provide workers with which of the following in a timely manner?","o":[["Access to clear, understandable and relevant information about the OHSMS",true],["Only the final certified copy of the OH&S manual once per year",false],["Information limited to managers and excluded from the workforce",false]],"p":1,"ref":"ISO 45001:2018 §5.4"},{"t":"short","q":"A welding workshop has high fume exposure. Walk through how you would apply the full hierarchy of controls (6.1.2 / 8.1.2) to this hazard, giving at least one concrete measure at each level you reach.","m":"Looks for: elimination (change process/product to avoid welding), substitution (lower-fume consumables/process), engineering (local exhaust ventilation, fume extraction), administrative (job rotation, procedures, training, exposure limits), PPE (respirators) as last resort; recognition that higher levels are preferred and PPE supplements rather than replaces them.","p":3},{"t":"short","q":"Explain how management of change (8.1.3), hazard identification (6.1.2), and worker consultation (5.4) should interact when an organization introduces a new production technology.","m":"Looks for: MoC triggers a hazard identification/risk assessment of the new technology before implementation; controls determined per hierarchy; non-managerial workers consulted on hazard identification and determining controls; consequences of unintended changes reviewed; legal/other requirements re-checked; documented and communicated.","p":3},{"t":"short","q":"An incident investigation concludes only that 'the worker was careless.' Critique this conclusion against the requirements of Clause 10.2 and describe what a conforming investigation would add.","m":"Looks for: 10.2 requires determining underlying/system causes (management-system causes), not just individual blame; evaluate need to eliminate root cause so it does not recur; check whether similar incidents occurred/could occur elsewhere; consider whether existing controls and the hierarchy were adequate; involve workers; drive corrective action and update risks/controls.","p":3},{"t":"short","q":"Describe how an organization should demonstrate compliance with legal and other requirements, linking Clauses 6.1.3 and 9.1.2, and explain why simply having a policy commitment to comply is insufficient.","m":"Looks for: 6.1.3 determine, have access to, keep up to date and communicate applicable legal/other requirements; 9.1.2 evaluate compliance at planned intervals, take action if needed, maintain knowledge and understanding of compliance status, retain documented information of results; a policy statement alone does not show ongoing evaluation or evidence.","p":3},{"t":"short","q":"Top management states it is 'committed to safety' but is not personally involved in the OHSMS, delegating everything to a safety officer. Evaluate this against Clause 5.1 and identify at least three specific leadership obligations being missed.","m":"Looks for: 5.1 requires top management to take overall responsibility/accountability for preventing injury and ill health; ensure policy/objectives align with strategic direction; integrate OHSMS into business processes; ensure resources; communicate importance; ensure OHSMS achieves intended outcomes; develop a supportive culture; protect workers from reprisals; support participation. Delegation does not satisfy these accountability duties.","p":3},{"t":"multi","q":"Which of the following would represent valid OH&S objectives consistent with Clause 6.2.1 (measurable where practicable, consistent with policy, monitored)?","o":[["Reduce manual-handling injuries by 30% within 12 months",true],["Complete ergonomic risk assessments for all workstations by Q3",true],["Increase quarterly profit margins",false],["Keep OH&S objectives undefined to retain flexibility",false]],"p":2,"ref":"ISO 45001:2018 §6.2.1"},{"t":"single","q":"An organization outsources its waste-handling operation. Under Clause 8.1.4.3, which statement reflects a conforming approach?","o":[["The organization ensures outsourced functions and processes are controlled and consistent with legal/other requirements and intended outcomes",true],["Outsourcing transfers all OH&S responsibility and removes the need for any control",false],["Outsourced functions are outside the OHSMS and need no consideration",false]],"p":1,"ref":"ISO 45001:2018 §8.1.4.3"},{"t":"single","q":"A risk assessment lists a hazard but its corresponding control is 'remind workers to be careful.' From an interpretation standpoint, the most significant deficiency is that the control:","o":[["Relies on the least effective level of the hierarchy without considering higher-order controls",true],["Is not documented in the correct template",false],["Was not approved by an external certification body",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"}]}},"ISO/IEC 27001 interpretation":{"levels":{"1":[{"t":"single","q":"What does the abbreviation ISMS stand for in ISO/IEC 27001:2022?","o":[["Information Security Management System",true],["Internal Security Monitoring Standard",false],["Information Systems Maintenance Schedule",false]],"p":1,"ref":"ISO/IEC 27001:2022 §3"},{"t":"single","q":"Which three properties form the classic 'CIA triad' that information security aims to preserve?","o":[["Confidentiality, Integrity, Availability",true],["Compliance, Integrity, Authorization",false],["Confidentiality, Identity, Accountability",false]],"p":1,"ref":"ISO/IEC 27001:2022 §3"},{"t":"tf","q":"ISO/IEC 27001:2022 is the standard that specifies requirements for establishing, implementing, maintaining and continually improving an ISMS.","a":true,"p":1,"ref":"ISO/IEC 27001:2022 §1"},{"t":"single","q":"In which clause of ISO/IEC 27001:2022 are the requirements for understanding the organization and its context found?","o":[["Clause 4 (Context of the organization)",true],["Clause 7 (Support)",false],["Clause 9 (Performance evaluation)",false]],"p":1,"ref":"ISO/IEC 27001:2022 §4.1"},{"t":"single","q":"How many themes are used to group the controls in Annex A of ISO/IEC 27001:2022?","o":[["4 themes",true],["14 clauses",false],["11 domains",false]],"p":1,"ref":"ISO/IEC 27001:2022 Annex A"},{"t":"single","q":"Which of the following is one of the four control themes in Annex A of ISO/IEC 27001:2022?","o":[["Organizational controls",false],["People controls",false],["All of the above are themes",true]],"p":1,"ref":"ISO/IEC 27001:2022 Annex A"},{"t":"tf","q":"The four Annex A control themes in ISO/IEC 27001:2022 are Organizational, People, Physical and Technological.","a":true,"p":1,"ref":"ISO/IEC 27001:2022 Annex A"},{"t":"single","q":"What document lists the necessary controls and justifies their inclusion or exclusion in an ISMS?","o":[["Statement of Applicability (SoA)",true],["Risk treatment plan",false],["Scope statement",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 d)"},{"t":"single","q":"Which clause of ISO/IEC 27001:2022 addresses leadership and commitment?","o":[["Clause 5 (Leadership)",true],["Clause 6 (Planning)",false],["Clause 10 (Improvement)",false]],"p":1,"ref":"ISO/IEC 27001:2022 §5.1"},{"t":"tf","q":"Top management must establish an information security policy as required by ISO/IEC 27001:2022.","a":true,"p":1,"ref":"ISO/IEC 27001:2022 §5.2"},{"t":"single","q":"How many controls are contained in Annex A of ISO/IEC 27001:2022?","o":[["93 controls",true],["114 controls",false],["35 controls",false]],"p":1,"ref":"ISO/IEC 27001:2022 Annex A"},{"t":"single","q":"Which clause of ISO/IEC 27001:2022 covers internal audit?","o":[["Clause 9.2 (Internal audit)",true],["Clause 8.1 (Operational planning)",false],["Clause 7.5 (Documented information)",false]],"p":1,"ref":"ISO/IEC 27001:2022 §9.2"},{"t":"tf","q":"In ISO/IEC 27001:2022, the term 'documented information' replaces the older terms 'documents' and 'records'.","a":true,"p":1,"ref":"ISO/IEC 27001:2022 §7.5"},{"t":"single","q":"Which clause requires the organization to conduct management reviews of the ISMS at planned intervals?","o":[["Clause 9.3 (Management review)",true],["Clause 6.2 (Information security objectives)",false],["Clause 4.3 (Determining the scope)",false]],"p":1,"ref":"ISO/IEC 27001:2022 §9.3"},{"t":"single","q":"In ISO/IEC 27001:2022, which clause addresses nonconformity and corrective action?","o":[["Clause 10.2 (Nonconformity and corrective action)",true],["Clause 8.3 (Risk treatment)",false],["Clause 5.3 (Roles and responsibilities)",false]],"p":1,"ref":"ISO/IEC 27001:2022 §10.2"},{"t":"tf","q":"ISO/IEC 27002 provides implementation guidance for the controls referenced in Annex A of ISO/IEC 27001.","a":true,"p":1,"ref":"ISO/IEC 27002:2022"},{"t":"single","q":"Which clause of ISO/IEC 27001:2022 deals with competence, awareness and communication as part of support?","o":[["Clause 7 (Support)",true],["Clause 8 (Operation)",false],["Clause 4 (Context)",false]],"p":1,"ref":"ISO/IEC 27001:2022 §7"},{"t":"single","q":"What is the role of a 'risk owner' in ISO/IEC 27001:2022?","o":[["A person with accountability and authority to manage a particular information security risk",true],["The external auditor who signs off the risk register",false],["The supplier responsible for the asset",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 f)"},{"t":"tf","q":"Conformance with ISO/IEC 27001:2022 requires that an organization adopt all 93 Annex A controls without exception.","a":false,"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3"},{"t":"single","q":"Which clause requires the organization to determine the scope of the ISMS?","o":[["Clause 4.3 (Determining the scope of the ISMS)",true],["Clause 6.1 (Actions to address risks and opportunities)",false],["Clause 9.1 (Monitoring and measurement)",false]],"p":1,"ref":"ISO/IEC 27001:2022 §4.3"},{"t":"single","q":"Continual improvement of the ISMS is the subject of which clause?","o":[["Clause 10.1 (Continual improvement)",true],["Clause 8.2 (Risk assessment)",false],["Clause 7.4 (Communication)",false]],"p":1,"ref":"ISO/IEC 27001:2022 §10.1"},{"t":"tf","q":"Interested parties whose requirements are relevant to the ISMS must be determined under Clause 4.2 of ISO/IEC 27001:2022.","a":true,"p":1,"ref":"ISO/IEC 27001:2022 §4.2"}],"2":[{"t":"single","q":"According to ISO/IEC 27001:2022, the information security risk assessment process (6.1.2) must produce results that are:","o":[["Consistent, valid and comparable",true],["Quantitative and expressed in monetary value only",false],["Approved by an external certification body",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.2 b)"},{"t":"single","q":"Under ISO/IEC 27001:2022, who must approve the risk treatment plan and accept the residual information security risks?","o":[["The risk owners",true],["The internal audit team",false],["The ISO certification auditor",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 f)"},{"t":"single","q":"Which of the following is NOT one of the steps required by the risk treatment process in Clause 6.1.3?","o":[["Eliminating all identified risks to zero",true],["Selecting appropriate risk treatment options",false],["Determining the controls necessary to implement the chosen options",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3"},{"t":"multi","q":"Which of the following are valid risk treatment options recognized in ISO/IEC 27001 / ISO/IEC 27005 risk management?","o":[["Modifying (reducing) the risk by applying controls",true],["Avoiding the risk",true],["Sharing/transferring the risk",true],["Ignoring the risk and removing it from the register without justification",false]],"p":2},{"t":"single","q":"In Clause 6.1.3, what must the organization compare the controls determined for risk treatment against?","o":[["The controls in Annex A, to verify no necessary controls are omitted",true],["The controls implemented by competitors",false],["A list provided by the certification body",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 c)"},{"t":"single","q":"What is the primary purpose of the Statement of Applicability?","o":[["To document the necessary controls, justify their inclusion, and explain exclusions of Annex A controls",true],["To list every asset owned by the organization",false],["To record the outcomes of internal audits",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 d)"},{"t":"multi","q":"Which of the following must be retained as documented information under ISO/IEC 27001:2022?","o":[["The information security risk assessment process and its results",true],["The Statement of Applicability",true],["The information security policy",true],["A copy of ISO/IEC 27002 distributed to every employee",false]],"p":2},{"t":"single","q":"Annex A control A.5.7 'Threat intelligence' belongs to which control theme?","o":[["Organizational controls",true],["Technological controls",false],["Physical controls",false]],"p":1,"ref":"ISO/IEC 27001:2022 Annex A A.5.7"},{"t":"single","q":"Which Annex A theme would contain a control on 'Physical security monitoring'?","o":[["Physical controls (A.7)",true],["People controls (A.6)",false],["Organizational controls (A.5)",false]],"p":1,"ref":"ISO/IEC 27001:2022 Annex A A.7.4"},{"t":"single","q":"The control 'Information security awareness, education and training' falls under which Annex A theme?","o":[["People controls (A.6)",true],["Organizational controls (A.5)",false],["Technological controls (A.8)",false]],"p":1,"ref":"ISO/IEC 27001:2022 Annex A A.6.3"},{"t":"single","q":"Which of these is a new control introduced in the 2022 revision of Annex A?","o":[["A.8.23 Web filtering",true],["A.5.1 Policies for information security",false],["A.6.2 Terms and conditions of employment",false]],"p":1,"ref":"ISO/IEC 27001:2022 Annex A A.8.23"},{"t":"multi","q":"Which of the following are among the new controls added in ISO/IEC 27001:2022 Annex A?","o":[["Information security for use of cloud services (A.5.23)",true],["Data masking (A.8.11)",true],["ICT readiness for business continuity (A.5.30)",true],["Mobile device policy as the only mobile control (A.6.2)",false]],"p":2},{"t":"single","q":"How does ISO/IEC 27001:2022 require the organization to handle Annex A controls that are not relevant?","o":[["Exclude them in the SoA with a documented justification for exclusion",true],["Implement them anyway to be safe",false],["Delete the control from Annex A entirely",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 d)"},{"t":"single","q":"When a nonconformity is identified, what does Clause 10.2 require the organization to do first?","o":[["Take action to control and correct it, and deal with the consequences",true],["Immediately revise the entire ISMS scope",false],["Notify the certification body within 24 hours",false]],"p":1,"ref":"ISO/IEC 27001:2022 §10.2 a)"},{"t":"single","q":"Why must corrective action under Clause 10.2 evaluate the need to eliminate the causes of a nonconformity?","o":[["To prevent recurrence or occurrence elsewhere",true],["To assign blame to a responsible individual",false],["To satisfy a documentation page-count requirement",false]],"p":1,"ref":"ISO/IEC 27001:2022 §10.2 b)"},{"t":"tf","q":"Under Clause 9.2, internal audits of the ISMS must be conducted at planned intervals to determine whether the ISMS conforms to the organization's own requirements and to ISO/IEC 27001.","a":true,"p":1,"ref":"ISO/IEC 27001:2022 §9.2"},{"t":"single","q":"Which input is explicitly required to be considered in the management review under Clause 9.3?","o":[["The status of actions from previous management reviews",true],["The personal performance appraisals of all staff",false],["The marketing strategy of the organization",false]],"p":1,"ref":"ISO/IEC 27001:2022 §9.3.2"},{"t":"tf","q":"ISO/IEC 27001:2022 requires that information security objectives be consistent with the information security policy and, where practicable, be measurable.","a":true,"p":1,"ref":"ISO/IEC 27001:2022 §6.2"},{"t":"single","q":"What is the relationship between ISO/IEC 27001 and ISO/IEC 27002 regarding Annex A controls?","o":[["27001 Annex A states the controls; 27002 gives detailed implementation guidance for them",true],["27002 is mandatory for certification while 27001 is advisory",false],["They are identical documents with different numbers",false]],"p":1,"ref":"ISO/IEC 27002:2022"},{"t":"multi","q":"Which of the following are requirements relating to documented information control under Clause 7.5.3?","o":[["It is available and suitable for use where and when needed",true],["It is adequately protected from loss of confidentiality and integrity",true],["Distribution, access, retrieval and use are controlled",true],["All documents must be printed and stored only on paper",false]],"p":2},{"t":"short","q":"Briefly explain the difference between a 'correction' and a 'corrective action' as used in ISO/IEC 27001:2022 Clause 10.2.","m":"Looks for: correction = immediate action to fix/contain the nonconformity itself; corrective action = action to eliminate the root cause so it does not recur; recognition that corrective action follows analysis of the cause.","p":2},{"t":"short","q":"In your own words, describe the purpose of determining the 'context of the organization' (Clause 4) before designing the ISMS.","m":"Looks for: identifying internal/external issues (4.1), needs and expectations of interested parties (4.2), and using these to define an appropriate scope (4.3) so the ISMS is relevant to the organization's objectives and risks.","p":2},{"t":"single","q":"Which Annex A theme contains technological controls such as A.8.5 'Secure authentication'?","o":[["Technological controls (A.8)",true],["Organizational controls (A.5)",false],["People controls (A.6)",false]],"p":1,"ref":"ISO/IEC 27001:2022 Annex A A.8.5"},{"t":"single","q":"What must the organization define before performing the information security risk assessment, per Clause 6.1.2?","o":[["Risk acceptance criteria and criteria for performing assessments",true],["The annual training budget",false],["The certification body's audit schedule",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.2 a)"},{"t":"tf","q":"The Statement of Applicability must be retained as documented information.","a":true,"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 d)"},{"t":"single","q":"Under Clause 8.2, how often must the organization perform information security risk assessments?","o":[["At planned intervals and when significant changes are proposed or occur",true],["Only once, at initial certification",false],["Every time an employee leaves the organization",false]],"p":1,"ref":"ISO/IEC 27001:2022 §8.2"}],"3":[{"t":"single","q":"An auditor finds that an organization's SoA marks control A.8.12 'Data leakage prevention' as 'not applicable' but provides no reason. Which clause requirement is breached?","o":[["6.1.3 d) requires justification for exclusions in the SoA",true],["9.2 requires the audit to be independent",false],["7.2 requires staff to be competent",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 d)"},{"t":"single","q":"A company applies controls to reduce a risk but the residual risk still exceeds its acceptance criteria. According to Clause 6.1.3, what is the correct next step?","o":[["The relevant risk owner must formally accept the residual risk, or further treatment must be applied",true],["The risk must be deleted from the register because controls are already in place",false],["Certification is automatically void",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 f)"},{"t":"single","q":"During an audit, management cannot show any record of the information security risk assessment results. Which type of finding is most appropriate?","o":[["A nonconformity against Clause 8.2 / 6.1.2 (documented information of results not retained)",true],["An opportunity for improvement only, with no nonconformity",false],["A finding against Annex A control A.5.1 only",false]],"p":1,"ref":"ISO/IEC 27001:2022 §8.2"},{"t":"single","q":"An organization's scope statement excludes a data center that processes in-scope customer data, purely to reduce audit effort. How should this be interpreted under Clause 4.3?","o":[["Improper scoping; the scope must consider interfaces/dependencies and cannot exclude activities that affect the ISMS's ability to meet requirements",true],["Acceptable, because the organization may scope however it wishes",false],["Required, because data centers are always out of scope",false]],"p":1,"ref":"ISO/IEC 27001:2022 §4.3"},{"t":"single","q":"A risk owner has accepted a residual risk, but the acceptance is undocumented and verbal. From an interpretation standpoint, what is the issue?","o":[["Acceptance of residual risks must be documented (retained as documented information per 6.1.3)",true],["Verbal acceptance is fully sufficient under 27001",false],["Only the CEO may accept any residual risk",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 f)"},{"t":"single","q":"An organization implements an Annex A control not because of risk treatment but because a legal regulation demands it. Is this consistent with ISO/IEC 27001:2022?","o":[["Yes; controls may be determined from any source including legal, contractual and business requirements, not only risk treatment",true],["No; only risk-driven controls are permitted",false],["No; legal requirements are outside the ISMS scope",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 b)"},{"t":"multi","q":"An auditor evaluates whether internal audit (Clause 9.2) is effective. Which of the following would be valid concerns?","o":[["Auditors audited their own work, compromising objectivity",true],["No audit programme exists defining frequency, methods and responsibilities",true],["Audit results were not reported to relevant management",true],["The audit was performed by qualified internal staff rather than an external body",false]],"p":2},{"t":"multi","q":"Which of the following correctly describe required management review outputs/inputs under Clause 9.3?","o":[["Inputs include results of risk assessment and status of the risk treatment plan",true],["Inputs include feedback from interested parties and audit results",true],["Outputs include decisions related to continual improvement opportunities and any needed changes to the ISMS",true],["Outputs must include the dismissal of any staff who caused incidents",false]],"p":2},{"t":"multi","q":"An organization is mapping its controls to Annex A 2022 themes. Which mappings are correct?","o":[["A.5 Information security policies -> Organizational controls",true],["A.7 Physical entry controls -> Physical controls",true],["A.8 Logging -> Technological controls",true],["A.6 Equipment maintenance -> People controls",false]],"p":2},{"t":"single","q":"A control marked 'applicable' in the SoA is not actually implemented, and there is no plan to implement it. How should this be interpreted?","o":[["A nonconformity: applicable controls in the SoA must be implemented (or have an implementation status reflected), supporting 6.1.3 / 8.1",true],["Acceptable, because the SoA is only a planning document",false],["Acceptable, because Annex A is informative",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3"},{"t":"single","q":"An organization claims its ISMS is certifiable but has never set information security objectives. Which clause is violated?","o":[["Clause 6.2 requires establishing information security objectives at relevant functions and levels",true],["Clause 7.4 requires marketing communication",false],["Clause 5.2 requires an asset register",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.2"},{"t":"single","q":"Top management delegates ALL ISMS responsibility and shows no involvement in setting policy or direction. From an interpretation view, what is the concern?","o":[["Clause 5.1 requires top management to demonstrate leadership and commitment; delegation does not remove their accountability",true],["This is fully acceptable as long as someone owns the ISMS",false],["Only the information security manager's commitment matters",false]],"p":1,"ref":"ISO/IEC 27001:2022 §5.1"},{"t":"single","q":"An organization treats ISO/IEC 27002 as a mandatory checklist and tries to implement every guidance item verbatim. What is the correct interpretation of 27002's role?","o":[["27002 is a guidance document; its recommendations are applied as appropriate to the organization's determined controls, not as mandatory requirements",true],["27002 is mandatory for certification and overrides 27001",false],["27002 controls replace Annex A entirely",false]],"p":1,"ref":"ISO/IEC 27002:2022"},{"t":"single","q":"After a security incident, the organization fixes the affected server but takes no steps to understand why it happened. Under Clause 10.2 this is deficient because:","o":[["Corrective action requires reviewing the nonconformity and determining its causes to prevent recurrence; a correction alone is insufficient",true],["Incidents never require corrective action",false],["Only Annex A controls, not Clause 10, apply to incidents",false]],"p":1,"ref":"ISO/IEC 27001:2022 §10.2"},{"t":"single","q":"An organization performs a risk assessment using a different method each year, producing results that cannot be compared over time. Which requirement is not met?","o":[["6.1.2 b) ensures the process produces consistent, valid and comparable results",true],["9.1 requires marketing measurement",false],["4.1 requires a SWOT analysis specifically",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.2 b)"},{"t":"single","q":"Which statement best captures the relationship between Clause 6.1.3 controls and Annex A?","o":[["Annex A is a reference list used to verify no necessary control has been overlooked; controls may also be designed or sourced elsewhere",true],["Annex A is an exhaustive mandatory set; no control outside Annex A may be used",false],["Annex A controls are optional examples with no role in the SoA",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 c)"},{"t":"single","q":"An organization documents a risk but assigns no risk owner. Why is this a nonconformity?","o":[["6.1.2 c) and 6.1.3 require identifying risk owners who are accountable for the risks and for approving treatment",true],["Risk owners are optional unless the risk is high",false],["Risk owners are only needed for Annex A physical controls",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.2 c)"},{"t":"single","q":"A certification scope says 'all information assets' but excludes the cloud service that hosts the core application, with no justification of interfaces and dependencies. What is the interpretation under 4.3?","o":[["The scope is inadequate; 4.3 requires considering interfaces and dependencies with external/other parties' activities",true],["Acceptable, cloud is always a supplier responsibility and out of scope",false],["Acceptable, the words 'all information assets' are sufficient",false]],"p":1,"ref":"ISO/IEC 27001:2022 §4.3 c)"},{"t":"multi","q":"Which of the following are legitimate sources for determining the controls necessary in Clause 6.1.3 b)?","o":[["The results of risk treatment",true],["Legal, statutory, regulatory and contractual requirements",true],["Business and operational requirements relevant to information security",true],["The personal preference of the IT manager with no documented basis",false]],"p":2},{"t":"multi","q":"An interpretation question on documented information: which statements are TRUE under ISO/IEC 27001:2022?","o":[["The extent of documented information can differ between organizations due to size and complexity",true],["Documented information required by the standard and by the organization must both be controlled",true],["When creating/updating, appropriate identification, format and review/approval must be ensured",true],["Only documents demanded explicitly by clauses need be retained; the organization may not add its own",false]],"p":2},{"t":"single","q":"An organization measures the effectiveness of its information security controls but never evaluates the ISMS performance overall. Which clause addresses this gap?","o":[["Clause 9.1 requires monitoring, measurement, analysis and evaluation of both information security performance and ISMS effectiveness",true],["Clause 8.3 requires only control testing",false],["Clause 7.5 requires only document control",false]],"p":1,"ref":"ISO/IEC 27001:2022 §9.1"},{"t":"single","q":"Which best describes a correct interpretation of 'risk acceptance criteria' (6.1.2 a)?","o":[["Predefined criteria, set by the organization, against which risk levels are judged acceptable or requiring treatment",true],["The auditor's personal threshold for passing the audit",false],["A fixed numeric value mandated by ISO for all organizations",false]],"p":1,"ref":"ISO/IEC 27001:2022 §6.1.2 a)"},{"t":"tf","q":"Under ISO/IEC 27001:2022, an organization may add controls that are not in Annex A if its risk treatment or other requirements call for them.","a":true,"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 b)"},{"t":"tf","q":"It is acceptable under ISO/IEC 27001:2022 for the same individual to plan, conduct and report an internal audit of their own area of responsibility.","a":false,"p":1,"ref":"ISO/IEC 27001:2022 §9.2.2"},{"t":"single","q":"An organization's information security policy exists but is never communicated to staff and is not available to interested parties. Which clause requirements are unmet?","o":[["5.2 requires the policy to be communicated within the organization and available to interested parties as appropriate",true],["10.1 requires the policy to be archived",false],["8.2 requires the policy to be risk-assessed annually",false]],"p":1,"ref":"ISO/IEC 27001:2022 §5.2"},{"t":"short","q":"A scenario: An organization marks 90 of 93 Annex A controls as applicable but cannot link several of them to any risk or requirement. Explain how Clause 6.1.3 should drive which controls appear in the SoA and what justification each entry needs.","m":"Looks for: controls determined from risk treatment plus other requirements (6.1.3 b); Annex A used as a check against omissions (6.1.3 c); SoA states necessary controls, justification for inclusion, and justification for any exclusions (6.1.3 d); applicability should be traceable to risk/requirements, not arbitrary.","p":3},{"t":"short","q":"Explain, with reference to specific clauses, the full chain an organization must follow from identifying an information security risk through to accepting any residual risk.","m":"Looks for: risk assessment process and criteria (6.1.2), identify/analyze/evaluate risks and risk owners (6.1.2 c/d/e), select treatment options (6.1.3 a), determine controls (6.1.3 b), compare with Annex A (6.1.3 c), produce SoA (6.1.3 d), formulate risk treatment plan (6.1.3 e), obtain risk owners' approval of plan and acceptance of residual risks (6.1.3 f).","p":3},{"t":"short","q":"Distinguish the roles of 'internal audit' (9.2) and 'management review' (9.3) in evaluating the ISMS, and explain why both are required.","m":"Looks for: internal audit provides objective evidence of conformity and effective implementation/maintenance against the standard and the organization's own requirements; management review is top management's periodic evaluation of suitability, adequacy and effectiveness using defined inputs and producing decisions/outputs; the two are complementary (evidence-gathering vs strategic steering).","p":3},{"t":"short","q":"An organization wants to claim conformity to ISO/IEC 27001:2022 while excluding the entire 'People controls' theme. Critique this from an interpretation standpoint.","m":"Looks for: exclusions are at the level of individual Annex A controls with justification, not whole themes by default; people-related risks (awareness, screening, terms of employment, disciplinary process) typically apply; blanket exclusion of a theme is unlikely to be justifiable; SoA must justify each exclusion against risk/requirements (6.1.3 d).","p":3},{"t":"short","q":"Explain how ISO/IEC 27002:2022 supports an organization implementing ISO/IEC 27001:2022, and the danger of confusing the two standards' status.","m":"Looks for: 27001 is the requirements/certification standard (mandatory clauses 4-10 + Annex A control set); 27002 is a code of practice giving implementation guidance, purpose and attributes for controls; 27002 is not certifiable and its guidance is applied as appropriate; danger = treating 27002 guidance as mandatory or ignoring 27001's actual requirements.","p":3},{"t":"single","q":"A multinational claims a single risk assessment performed five years ago is still valid and has never been revisited despite a major cloud migration. Which requirement does this most directly violate?","o":[["8.2 requires reassessment at planned intervals and when significant changes occur",true],["7.3 requires awareness training only",false],["10.1 prohibits any change to the ISMS",false]],"p":1,"ref":"ISO/IEC 27001:2022 §8.2"},{"t":"single","q":"Which interpretation of 'continual improvement' (10.1) is correct?","o":[["The organization must continually improve the suitability, adequacy and effectiveness of the ISMS",true],["The organization must achieve perfection and zero incidents",false],["Continual improvement applies only to Annex A technological controls",false]],"p":1,"ref":"ISO/IEC 27001:2022 §10.1"},{"t":"multi","q":"An organization's SoA is under review. Which of the following are mandatory elements of a compliant SoA per 6.1.3 d)?","o":[["The necessary controls and the reasons for their inclusion",true],["Whether the necessary controls are implemented or not",true],["Justification for exclusions of Annex A controls",true],["The names of all employees who use each control",false]],"p":2},{"t":"tf","q":"Under ISO/IEC 27001:2022, the results of the information security risk treatment must be documented and the risk treatment plan approved by the relevant risk owners.","a":true,"p":1,"ref":"ISO/IEC 27001:2022 §6.1.3 f)"}]}},"Document control":{"levels":{"1":[{"t":"single","q":"In ISO 9001:2015, which term covers both documents and records?","o":[["Documented information",true],["Quality manual",false],["Work instruction",false]],"p":1,"ref":"ISO 9001:2015 §7.5"},{"t":"tf","q":"A 'record' is documented information that provides evidence of results achieved or activities performed.","a":true,"p":1},{"t":"single","q":"What must happen to a newly created document before it is released for use?","o":[["It must be reviewed and approved for suitability and adequacy",true],["It must be printed on controlled paper only",false],["It must be archived immediately",false]],"p":1,"ref":"ISO 9001:2015 §7.5.2"},{"t":"tf","q":"Documents typically are updated and revised over time, while records are generally not changed once created.","a":true,"p":1},{"t":"single","q":"Which element is part of identifying and describing documented information?","o":[["A title, date, author or reference number",true],["The colour of the printer toner used",false],["The supplier's bank account",false]],"p":1,"ref":"ISO 9001:2015 §7.5.2"},{"t":"single","q":"A version or revision number on a document primarily helps users to:","o":[["Confirm they are using the current, correct version",true],["Calculate how many copies to print",false],["Estimate the document's word count",false]],"p":1},{"t":"tf","q":"Controlling access to documented information can include defining who may view, change, or delete it.","a":true,"p":1},{"t":"single","q":"What is the main purpose of controlling distribution of documents?","o":[["Ensuring relevant versions are available where needed",true],["Increasing the number of printed copies",false],["Reducing the file size of documents",false]],"p":1,"ref":"ISO 9001:2015 §7.5.3"},{"t":"single","q":"Why must documented information remain legible?","o":[["So it can be read and understood when used",true],["So it uses less storage space",false],["So it can be deleted faster",false]],"p":1},{"t":"tf","q":"A document of external origin is one created outside the organization, such as a customer specification or a regulation.","a":true,"p":1},{"t":"single","q":"When a document becomes obsolete, the organization should:","o":[["Prevent its unintended use",true],["Always destroy every copy immediately",false],["Leave it in circulation without marking",false]],"p":1,"ref":"ISO 9001:2015 §7.5.3"},{"t":"single","q":"Which of these is an example of a record rather than a document?","o":[["A completed inspection report showing results",true],["A blank inspection form template",false],["A procedure describing the inspection process",false]],"p":1},{"t":"tf","q":"Storage and preservation controls aim to protect documented information from loss of integrity, including damage and deterioration.","a":true,"p":1},{"t":"single","q":"Retention period of a record refers to:","o":[["How long it must be kept before disposition",true],["How many people approved it",false],["The font size used in it",false]],"p":1},{"t":"single","q":"Which activity is 'retrieval' of documented information?","o":[["Finding and accessing a stored document when needed",true],["Creating a new document from scratch",false],["Approving a document for release",false]],"p":1,"ref":"ISO 9001:2015 §7.5.3"},{"t":"tf","q":"Documented information required by the quality management system must be controlled.","a":true,"p":1},{"t":"single","q":"Disposition of records at end of retention may include:","o":[["Destruction or archiving",true],["Mandatory immediate publication",false],["Converting them into procedures",false]],"p":1},{"t":"single","q":"Who is normally responsible for approving a controlled document before issue?","o":[["A person with appropriate authority for that document",true],["Any employee who happens to read it",false],["An external auditor only",false]],"p":1,"ref":"ISO 9001:2015 §7.5.2"},{"t":"tf","q":"Confidential documented information may require controls such as access restrictions and protection from unauthorized disclosure.","a":true,"p":1},{"t":"single","q":"What does 'control of changes' to documents primarily ensure?","o":[["Changes are reviewed and approved before taking effect",true],["No document is ever changed again",false],["Changes happen without any record",false]],"p":1,"ref":"ISO 9001:2015 §7.5.3"}],"2":[{"t":"single","q":"According to ISO 9001:2015 §7.5.2, when creating and updating documented information, the organization must ensure appropriate:","o":[["Identification, format, review and approval",true],["Marketing and branding sign-off",false],["Financial budgeting approval",false]],"p":1,"ref":"ISO 9001:2015 §7.5.2"},{"t":"multi","q":"Which controls does §7.5.3 require to be addressed for documented information, as applicable?","o":[["Distribution, access, retrieval and use",true],["Storage and preservation, including legibility",false],["Control of changes such as version control",true],["Retention and disposition",true],["Choice of corporate logo",false]],"p":2,"ref":"ISO 9001:2015 §7.5.3"},{"t":"single","q":"A controlled document register (master list) is mainly used to:","o":[["Track current versions, status and location of documents",true],["Record customer complaints",false],["Schedule production runs",false]],"p":1},{"t":"tf","q":"Allowing 'view only' access while restricting 'change' rights is a valid form of access control under §7.5.3.","a":true,"p":1,"ref":"ISO 9001:2015 §7.5.3"},{"t":"single","q":"Documents of external origin that are necessary for the QMS must be:","o":[["Identified and their distribution controlled",true],["Rewritten into internal procedures before use",false],["Excluded from the document control system",false]],"p":1,"ref":"ISO 9001:2015 §7.5.3"},{"t":"single","q":"A 'review and update' cycle for documents is best triggered by:","o":[["Process changes, audit findings, or scheduled review dates",true],["The end of each working day",false],["Every time the document is printed",false]],"p":1},{"t":"multi","q":"Which are valid methods to control obsolete documents?","o":[["Mark them 'obsolete' or 'superseded'",true],["Remove them from points of use",true],["Move them to a clearly identified archive",true],["Leave them mixed with current copies",false]],"p":2},{"t":"single","q":"In version control, a 'minor revision' usually denotes:","o":[["A small change not altering the document's intent significantly",true],["A complete rewrite changing the document's purpose",false],["Deletion of the document",false]],"p":1},{"t":"tf","q":"Records (documented information retained as evidence) should be protected from unintended alterations.","a":true,"p":1},{"t":"single","q":"Preservation of electronic documented information may require:","o":[["Backups and format/media migration over time",true],["Printing every file to paper monthly",false],["Deleting old backups weekly",false]],"p":1},{"t":"single","q":"Which statement best distinguishes documents from records?","o":[["Documents state what should be done; records show what was done",true],["Documents are always electronic; records are always paper",false],["Documents need no approval; records need approval",false]],"p":2},{"t":"multi","q":"Which items are typically considered 'documents' (not records) in a QMS?","o":[["Procedures and work instructions",true],["Quality policy and objectives statements",true],["Forms and templates (blank)",true],["A completed and signed audit report",false]],"p":2},{"t":"single","q":"A change to a controlled document takes effect only after:","o":[["Review and approval by authorized personnel",true],["The author informally edits it",false],["It is emailed to one colleague",false]],"p":1,"ref":"ISO 9001:2015 §7.5.3"},{"t":"tf","q":"Identification of documented information can include metadata such as document number, revision, and effective date.","a":true,"p":1,"ref":"ISO 9001:2015 §7.5.2"},{"t":"single","q":"What is the main risk if obsolete documents are not controlled?","o":[["People may unintentionally use outdated information",true],["The archive will be too small",false],["New documents cannot be created",false]],"p":1},{"t":"single","q":"For confidential records, integrity protection focuses on ensuring the information is:","o":[["Not altered, lost, or accessed without authorization",true],["Printed in colour",false],["Always publicly available",false]],"p":1},{"t":"multi","q":"Which are appropriate access/retrieval controls in an electronic document management system (EDMS)?","o":[["Role-based permissions",true],["Search and indexing for retrieval",true],["Audit trail of changes",true],["Disabling all backups to save space",false]],"p":2},{"t":"single","q":"A document marked 'uncontrolled copy' means:","o":[["It is not maintained or updated when revisions occur",true],["It is the only official master version",false],["It must be approved again daily",false]],"p":1},{"t":"tf","q":"The extent of documented information for a QMS can differ between organizations based on size, processes, and competence of people.","a":true,"p":1,"ref":"ISO 9001:2015 §7.5.1"},{"t":"single","q":"When a regulation (external document) is updated, document control should ensure:","o":[["The current version is identified and obsolete versions are withdrawn from use",true],["The old version stays in active use",false],["The regulation is ignored until the next audit",false]],"p":1,"ref":"ISO 9001:2015 §7.5.3"},{"t":"single","q":"Legibility of records over a long retention period is best ensured by:","o":[["Suitable media, storage conditions, and periodic checks",true],["Using disappearing ink",false],["Storing them in direct sunlight",false]],"p":1},{"t":"single","q":"Which is a sound disposition practice for expired confidential records?","o":[["Secure destruction (e.g., shredding or secure deletion)",true],["Leaving them in a public bin",false],["Forwarding them to all staff",false]],"p":1},{"t":"multi","q":"Which practices support reliable version/revision control?","o":[["A unique revision identifier on each issue",true],["A revision history or change log",true],["Removing superseded versions from use",true],["Reusing the same revision number for every change",false]],"p":2},{"t":"tf","q":"A blank form is a document, but once filled in with results it becomes a record.","a":true,"p":1},{"t":"short","q":"Explain the practical difference between controlling a 'document' and controlling a 'record' in a QMS, giving one control unique to each.","m":"Looks for: documents are living/revised and need version/approval control; records are evidence, retained unchanged, need retention/protection from alteration; one distinct control each (e.g., revision control for documents, retention/disposition for records).","p":2},{"t":"short","q":"Describe how you would handle an external-origin standard (e.g., a customer specification) within document control.","m":"Looks for: identify it, register it, control distribution/access, ensure current version available, withdraw/control obsolete versions, monitor for updates.","p":2}],"3":[{"t":"single","q":"Per §7.5.3, control of documented information must address its protection from:","o":[["Loss of confidentiality, improper use, or loss of integrity",true],["Loss of marketing appeal",false],["Loss of printer toner",false]],"p":1,"ref":"ISO 9001:2015 §7.5.3"},{"t":"multi","q":"In a regulated environment, which attributes make an electronic record 'trustworthy' (integrity-protected)?","o":[["Attributable to its author",true],["Legible and contemporaneous",true],["Original and accurate",true],["Easily editable without trace",false]],"p":2},{"t":"single","q":"A document control procedure should define 'effective date' primarily to:","o":[["Establish when a revision becomes mandatory for use",true],["Record when the document was first drafted only",false],["Indicate when to delete the document",false]],"p":1},{"t":"single","q":"Which approach best prevents use of superseded engineering drawings on the shop floor?","o":[["Point-of-use control with current-version verification and removal of old prints",true],["Trusting operators to remember the latest revision",false],["Keeping all revisions stacked together at the workstation",false]],"p":1},{"t":"multi","q":"Which are valid reasons to retain a record beyond the minimum required period?","o":[["Legal or contractual obligations",true],["Ongoing warranty or liability exposure",true],["Traceability needs for product still in service",true],["To avoid ever doing disposition",false]],"p":2},{"t":"single","q":"In an EDMS, an immutable audit trail of who changed what and when chiefly supports:","o":[["Integrity and accountability of documented information",true],["Faster printing",false],["Smaller storage footprint",false]],"p":1},{"t":"tf","q":"ISO 9001:2015 does not prescribe a single mandatory format or medium for documented information; it can be paper, electronic, photo, or sample.","a":true,"p":1,"ref":"ISO 9001:2015 §7.5"},{"t":"single","q":"A 'controlled distribution list' for a procedure is most useful when:","o":[["Revisions must reach all known holders so old copies are replaced",true],["The procedure never changes",false],["Only one person ever reads the procedure",false]],"p":1},{"t":"multi","q":"Which failures would an auditor likely cite as document control nonconformities?","o":[["An obsolete work instruction in active use at a station",true],["No approval evidence for an issued procedure",true],["External standards in use without controlled identification",true],["A neatly maintained, current master list",false]],"p":2},{"t":"single","q":"For long-term electronic record preservation, the key obsolescence risk to manage is:","o":[["Software/hardware/format becoming unreadable over time",true],["Files being too well organized",false],["Too many backups existing",false]],"p":1},{"t":"single","q":"A change request (DCR) workflow for documents typically ensures:","o":[["Proposed changes are assessed, approved, implemented, and communicated",true],["Changes are made silently by anyone",false],["Changes bypass review when urgent, with no record",false]],"p":1,"ref":"ISO 9001:2015 §7.5.3"},{"t":"tf","q":"Maintaining (keeping current) applies primarily to documents, while retaining (preserving evidence) applies primarily to records.","a":true,"p":1,"ref":"ISO 9001:2015 §7.5"},{"t":"single","q":"Which control most directly protects confidentiality of documented information?","o":[["Access restrictions based on need-to-know with authentication",true],["Publishing it on the public website",false],["Removing all version numbers",false]],"p":1},{"t":"multi","q":"Which are sound practices when superseding a document with a new revision?","o":[["Increment the revision identifier",true],["Update the revision history with reason for change",true],["Withdraw or mark prior copies obsolete",true],["Keep the same effective date as the prior revision",false]],"p":2},{"t":"single","q":"In hybrid (paper + electronic) systems, the 'master' should be defined to avoid:","o":[["Ambiguity over which copy is authoritative",true],["Having any backups",false],["Using version numbers",false]],"p":1},{"t":"single","q":"A record's 'attributability' means it can be linked to:","o":[["The person and time of its creation/entry",true],["The size of the file only",false],["The printer model only",false]],"p":1},{"t":"tf","q":"Reissuing an entire document at a new revision is acceptable even when only one clause changed, provided change control and history are maintained.","a":true,"p":1},{"t":"multi","q":"Which measures help ensure retrievability of records years later?","o":[["Consistent indexing and naming conventions",true],["Defined storage location and format standards",true],["Periodic media/format migration",true],["Storing files with random unlabeled names",false]],"p":2},{"t":"single","q":"Scenario: An operator downloads a procedure PDF to their desktop and works from it for months. The chief document-control risk is:","o":[["Working from an uncontrolled copy that misses later revisions",true],["The PDF being too large",false],["The desktop running out of icons",false]],"p":1},{"t":"single","q":"Scenario: During an audit, two different revisions of the same form are found in use across departments. The best corrective action is to:","o":[["Identify the current revision, withdraw the obsolete one, and reinforce distribution control",true],["Let both revisions remain to give people choice",false],["Delete the form entirely without replacement",false]],"p":1},{"t":"single","q":"Scenario: A customer specification (external document) is revised by the customer. The document-control system should:","o":[["Capture the new revision, control its distribution, and withdraw the prior version from use",true],["Continue using the previous revision until the next contract",false],["Treat it as an internal record requiring no update",false]],"p":1,"ref":"ISO 9001:2015 §7.5.3"},{"t":"multi","q":"Which are legitimate justifications for restricting 'change' access to a controlled document?","o":[["Preventing unauthorized or unreviewed edits",true],["Maintaining integrity and approval trail",true],["Ensuring only competent authority revises content",true],["Making the document impossible to ever update",false]],"p":2},{"t":"single","q":"The difference between 'archiving' and 'destruction' in disposition is that archiving:","o":[["Preserves records (often offline) while removing them from active use",true],["Permanently erases the records",false],["Publishes the records widely",false]],"p":1},{"t":"tf","q":"Confidentiality, integrity, and availability are all relevant when controlling sensitive documented information.","a":true,"p":1},{"t":"single","q":"Scenario: A signed quality record is later found edited with no audit trail. The primary integrity failure is:","o":[["Loss of evidence reliability because changes were not controlled/traceable",true],["The record being slightly too long",false],["The record using the wrong font",false]],"p":1},{"t":"single","q":"Which best describes 'format' control under §7.5.2 (e.g., language, software version, graphics)?","o":[["Ensuring documented information is presented suitably and consistently for use",true],["Mandating a single global font for legal reasons",false],["Forbidding any electronic formats",false]],"p":1,"ref":"ISO 9001:2015 §7.5.2"},{"t":"multi","q":"Which controls help protect documented information from 'improper use'?","o":[["Marking confidentiality/classification levels",true],["Access controls and need-to-know permissions",true],["Watermarking or copy/print restrictions where appropriate",true],["Distributing all documents to everyone by default",false]],"p":2},{"t":"short","q":"Design a version-control scheme for a procedure that may have both minor editorial and major content changes, and explain how each is identified and approved.","m":"Looks for: numbering convention (e.g., major.minor), criteria distinguishing minor vs major, review/approval authority per change type, revision history/change log, effective date, withdrawal of superseded versions.","p":3},{"t":"short","q":"Outline a retention and disposition schedule approach for QMS records, including how legal, contractual, and operational drivers are reconciled.","m":"Looks for: record categories, defined retention periods, basis (legal/contractual/operational), responsible owners, secure disposition method, review of schedule, evidence of disposition.","p":3},{"t":"short","q":"Explain how you would control documents of external origin end-to-end (identification through obsolescence) and why each step matters.","m":"Looks for: identify/register external docs, assign owner, control distribution/access, monitor for updates, ensure current version at point of use, withdraw/mark obsolete, traceability/audit.","p":3},{"t":"short","q":"A confidential record must be shared with an external auditor but not altered. Describe the controls you would apply to preserve confidentiality and integrity.","m":"Looks for: access on need-to-know, read-only/non-editable copy, controlled transfer (NDA, encryption), watermarking, audit trail/log of access, no uncontrolled redistribution, integrity verification.","p":3},{"t":"short","q":"Compare 'maintaining documented information' with 'retaining documented information' and give a concrete example of each control in practice.","m":"Looks for: maintaining = keeping documents current (version/approval/review), retaining = preserving records as evidence (protection, retention, disposition); concrete example of each; tie to §7.5 documents vs records distinction.","p":3}]}},"Nonconformity writing":{"levels":{"1":[{"t":"single","q":"A sound nonconformity statement is built from three core parts. Which of the following is one of them?","o":[["The objective evidence observed during the audit",true],["The auditor's personal opinion of the auditee",false],["A proposed corrective action for the auditee",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Which element identifies the audit criterion against which a nonconformity is raised?","o":[["The requirement (clause or specified requirement)",true],["The root cause of the problem",false],["The name of the auditor",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"In a nonconformity statement, what does the 'statement of nonconformity' (the aspect of the requirement not met) describe?","o":[["Why the evidence fails to meet the requirement",true],["How the auditee should fix the issue",false],["The qualifications of the audit team",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"A nonconformity is defined as the non-fulfilment of a requirement.","a":true,"p":1,"ref":"ISO 9000:2015"},{"t":"tf","q":"A nonconformity statement should include the auditor's recommended solution.","a":false,"p":1},{"t":"single","q":"Which of these best describes 'objective evidence' in a nonconformity?","o":[["Data supporting the existence of something, verifiable and factual",true],["The auditor's gut feeling about a process",false],["A generic statement that 'records were poor'",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"A good nonconformity statement should be traceable so that another person could verify it.","a":true,"p":1},{"t":"single","q":"How many distinct issues should a single nonconformity statement address?","o":[["Exactly one issue",true],["As many as the auditor finds in that area",false],["At least three to justify the finding",false]],"p":1},{"t":"tf","q":"A nonconformity must always be linked to a specific requirement or clause of the audit criteria.","a":true,"p":1,"ref":"ISO 19011:2018"},{"t":"single","q":"Which word would be inappropriate (subjective) to use in a factual nonconformity statement?","o":[["'Sloppy'",true],["'Records'",false],["'Procedure'",false]],"p":1},{"t":"tf","q":"Conformity means the fulfilment of a requirement.","a":true,"p":1,"ref":"ISO 9000:2015"},{"t":"single","q":"An 'opportunity for improvement' (OFI) differs from a nonconformity because it:","o":[["Does not represent a breach of a requirement",true],["Is a more serious version of a major nonconformity",false],["Always requires a corrective action",false]],"p":1},{"t":"tf","q":"An observation that does not breach any requirement should be recorded as a nonconformity.","a":false,"p":1},{"t":"single","q":"Which is the best example of a clear, specific evidence reference?","o":[["Purchase order PO-4471 dated 12 March 2026 had no approval signature",true],["Some purchase orders were not handled correctly",false],["Purchasing is generally weak",false]],"p":1},{"t":"tf","q":"A nonconformity statement should assign blame to a specific employee.","a":false,"p":1},{"t":"single","q":"What is the main purpose of stating the requirement in a nonconformity?","o":[["To show what standard or rule was not met",true],["To make the statement longer",false],["To list the auditor's credentials",false]],"p":1,"ref":"ISO 19011:2018"},{"t":"tf","q":"Vague language such as 'inadequate' without supporting facts weakens a nonconformity.","a":true,"p":1},{"t":"single","q":"A nonconformity that is one of several lapses indicating a total breakdown of part of the system is typically classified as:","o":[["A major nonconformity",true],["An opportunity for improvement",false],["A conformity",false]],"p":1,"ref":"ISO 17021-1:2015"},{"t":"tf","q":"A minor nonconformity is an isolated lapse that does not represent a systemic failure.","a":true,"p":1,"ref":"ISO 17021-1:2015"},{"t":"single","q":"Which best states the role of the 'why' element of a nonconformity?","o":[["It explains which part of the requirement is not satisfied by the evidence",true],["It records the audit start and end dates",false],["It documents the auditee's response",false]],"p":1}],"2":[{"t":"single","q":"An auditor writes: 'The records were poor.' Why is this a weak nonconformity statement?","o":[["It lacks objective evidence and a linked requirement",true],["It correctly cites a clause",false],["It includes a corrective action",false]],"p":1},{"t":"multi","q":"Which of the following belong in a well-formed nonconformity statement?","o":[["The requirement or clause not met",true],["The objective evidence observed",true],["The statement of which aspect of the requirement was not met",true],["A suggested fix and the responsible person to blame",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"single","q":"During an audit, calibration certificate for gauge G-22 expired on 1 Jan 2026 but the gauge was used on 15 Feb 2026. The procedure requires only in-date gauges be used. The best statement of nonconformity is:","o":[["Gauge G-22 was used on 15 Feb 2026 with a calibration certificate that expired 1 Jan 2026, contrary to procedure QP-07 which requires only in-date gauges to be used",true],["Calibration is a mess in the lab",false],["The lab should recalibrate all gauges immediately",false]],"p":2},{"t":"single","q":"Which classification fits a single missing training record for one operator, where the training system is otherwise functioning?","o":[["Minor nonconformity",true],["Major nonconformity",false],["Opportunity for improvement only",false]],"p":1,"ref":"ISO 17021-1:2015"},{"t":"multi","q":"Which characteristics make a nonconformity statement defensible?","o":[["It is factual and based on objective evidence",true],["It is specific and traceable",true],["It expresses the auditor's personal frustration",false],["It bundles three unrelated issues for efficiency",false]],"p":2},{"t":"tf","q":"If evidence could be interpreted multiple ways and no requirement is clearly breached, recording an observation or OFI may be more appropriate than a nonconformity.","a":true,"p":1},{"t":"single","q":"An auditor links a finding to 'the standard' without naming a clause. The main problem is:","o":[["The requirement is not specific enough to be traceable",true],["The evidence is too detailed",false],["The statement is too factual",false]],"p":1},{"t":"multi","q":"Which phrases indicate inappropriate auditor opinion rather than fact?","o":[["'The manager clearly does not care about quality'",true],["'Staff seem lazy about records'",true],["'Three of ten inspection reports lacked a sign-off'",false],["'Document DOC-12 rev 2 was not on the controlled list'",false]],"p":2},{"t":"single","q":"Why should a nonconformity contain only one issue?","o":[["So corrective action and verification can target a single, clear cause",true],["So the auditor writes fewer findings overall",false],["Because standards forbid writing more than one finding per audit",false]],"p":1},{"t":"single","q":"A statement reads: 'Procedure not followed.' What is the most important missing element?","o":[["The objective evidence and the specific requirement",true],["The auditor's signature",false],["The audit duration",false]],"p":1},{"t":"multi","q":"Which situations would typically justify a MAJOR nonconformity?","o":[["The absence of a required process entirely",true],["A number of minor nonconformities against one requirement indicating systemic failure",true],["A single document with a typo in the revision date",false],["An isolated missing signature on one form",false]],"p":2,"ref":"ISO 17021-1:2015"},{"t":"single","q":"Which rewrite best removes blame while staying factual? Original: 'John forgot to sign the inspection sheet.'","o":[["Inspection sheet IS-88 dated 3 Mar 2026 was not signed, contrary to WI-04 requiring inspector sign-off",true],["The inspector was careless and skipped signing",false],["Someone failed to do their job on the inspection sheet",false]],"p":2},{"t":"tf","q":"Including the document or record reference (e.g., report number and date) improves traceability of a nonconformity.","a":true,"p":1},{"t":"single","q":"An OFI should be raised when:","o":[["A requirement is met but a practice could be enhanced",true],["A requirement is clearly not met",false],["The auditor wants to avoid writing a nonconformity that is justified",false]],"p":1},{"t":"single","q":"Which is the strongest 'requirement' element for a nonconformity?","o":[["ISO 9001:2015 clause 7.1.5.2 and procedure QP-07 section 4.2",true],["The rules",false],["Good practice",false]],"p":1,"ref":"ISO 9001:2015"},{"t":"multi","q":"Select the items that should NOT appear in the nonconformity statement itself.","o":[["The proposed corrective action",true],["The presumed root cause",true],["The objective evidence",false],["The breached requirement",false]],"p":2},{"t":"single","q":"A nonconformity says: 'Several calibration records were missing.' How best to strengthen it?","o":[["Name which records, identify them, and cite the requiring clause",true],["Add the word 'unacceptable'",false],["State that the lab manager is responsible",false]],"p":1},{"t":"tf","q":"Downgrading a justified major nonconformity to an observation to keep the auditee happy is an acceptable practice.","a":false,"p":1},{"t":"single","q":"The phrase 'aspect of the requirement not met' refers to:","o":[["The precise way the evidence falls short of the requirement",true],["The cost of fixing the problem",false],["The audit scope boundary",false]],"p":1},{"t":"multi","q":"Which are valid reasons to keep solutions out of a nonconformity statement?","o":[["The auditee owns the corrective action and root cause analysis",true],["Prescribing a fix may bias or limit the auditee's solution",true],["The auditor lacks the authority to ever suggest improvements",false],["Standards require the auditor to fix the problem directly",false]],"p":2},{"t":"single","q":"An auditor records a finding but cannot point to any breached requirement. The correct action is to:","o":[["Reconsider whether it is a nonconformity or instead an OFI/observation",true],["Invent a clause to justify it",false],["Classify it as a major nonconformity anyway",false]],"p":1},{"t":"tf","q":"A conformity statement is not normally written up as a finding requiring corrective action.","a":true,"p":1},{"t":"single","q":"Which best demonstrates the 'evidence' part being verifiable?","o":[["Batch record BR-301 lacked the QC release stamp required by SOP-12",true],["Records generally look incomplete",false],["The process feels disorganized",false]],"p":1},{"t":"short","q":"In your own words, list the three essential parts of a sound nonconformity statement and briefly explain the purpose of each.","m":"Looks for: requirement/criterion (what rule), objective evidence (what was found, verifiable/traceable), and statement/why (which aspect of the requirement is not met); explains each purpose clearly.","p":2},{"t":"short","q":"Explain the practical difference between a major and a minor nonconformity, and give a short example of each.","m":"Looks for: major = systemic breakdown, total absence of a process, or multiple minors against one requirement; minor = isolated lapse not undermining the system; plausible distinct examples for each.","p":2},{"t":"tf","q":"A nonconformity statement should be written so that, after the audit, a reader who was not present can understand what was found and why it is a nonconformity.","a":true,"p":1}],"3":[{"t":"single","q":"Critique: 'The lab is non-compliant with calibration because management does not prioritize quality.' The single biggest defect is:","o":[["It states auditor opinion/blame instead of objective evidence and a linked requirement",true],["It cites too many clauses",false],["It is too specific and traceable",false]],"p":2},{"t":"multi","q":"A finding bundles three issues: an expired gauge, a missing training record, and an unsigned form. Why is this poor practice?","o":[["Each issue may map to different requirements and root causes",true],["Corrective action and verification become ambiguous",true],["It produces a longer, more impressive document",false],["It is required by ISO 19011 to bundle related findings",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"single","q":"Scenario: Procedure requires supplier evaluation before first order. Auditor finds supplier S-9 placed an order with no evaluation record. Which statement is most defensible?","o":[["Supplier S-9 received purchase order PO-220 (2 Feb 2026) with no supplier evaluation record on file, contrary to procurement procedure PR-03 cl. 5.1 requiring evaluation before first order",true],["Supplier evaluation is weak and needs a new system",false],["Procurement staff ignored the procedure as usual",false]],"p":2},{"t":"single","q":"An audit finds a documented procedure exists but is not implemented anywhere in three sampled departments. The most appropriate classification is:","o":[["Major nonconformity (systemic failure to implement)",true],["Minor nonconformity",false],["Opportunity for improvement",false]],"p":2,"ref":"ISO 17021-1:2015"},{"t":"multi","q":"Which revisions would convert 'Records bad in lab' into a defensible nonconformity?","o":[["Identify which records and where (e.g., specific log/IDs)",true],["Cite the breached clause or procedure",true],["State which aspect of the requirement is not met",true],["Add the auditor's opinion that the lab is careless",false]],"p":2},{"t":"single","q":"Why is linking to a clause insufficient if the clause is broad (e.g., 'clause 8')?","o":[["It reduces traceability; the specific sub-requirement breached should be identified",true],["Broad clauses are always invalid criteria",false],["It makes the nonconformity a major automatically",false]],"p":2},{"t":"single","q":"An auditee disputes a nonconformity. Which property of the statement best protects the auditor's position?","o":[["It is based on verifiable objective evidence tied to a specific requirement",true],["It uses strong adjectives like 'serious'",false],["It names the responsible individual",false]],"p":2},{"t":"multi","q":"Which are legitimate reasons to record an OFI instead of a nonconformity?","o":[["The requirement is met but performance could be improved",true],["There is no breached requirement to cite",true],["The auditor wants to avoid documenting a justified breach",false],["The auditee asked for fewer nonconformities",false]],"p":2},{"t":"single","q":"Scenario: Two of twenty sampled CAPA records exceeded the 30-day close target defined in QP-09, with no documented extension. Best classification, assuming the CAPA system otherwise functions:","o":[["Minor nonconformity",true],["Major nonconformity",false],["Conformity",false]],"p":2,"ref":"ISO 17021-1:2015"},{"t":"multi","q":"Which statements correctly distinguish observation/OFI from nonconformity?","o":[["A nonconformity requires a breached requirement and objective evidence",true],["An OFI does not assert a breach of a requirement",true],["An observation always mandates corrective action",false],["An OFI is a downgraded major nonconformity",false]],"p":2},{"t":"single","q":"An auditor writes the requirement and evidence well but omits the 'why'. The reader cannot tell:","o":[["Which aspect of the requirement the evidence fails to meet",true],["The date of the audit",false],["The auditor's name",false]],"p":2},{"t":"single","q":"Which best avoids embedding a solution? Original draft: 'Operators must be retrained because training records are missing.'","o":[["Training records for operators O-3 and O-5 on process P-2 were not available, contrary to TR-01 cl. 3 requiring records of completed training",true],["Operators need retraining immediately to fix records",false],["The training system should be replaced",false]],"p":2},{"t":"multi","q":"Select the elements that make a nonconformity TRACEABLE.","o":[["Specific document/record identifiers and dates",true],["Named location or process where found",true],["The exact requirement reference",true],["The auditor's emotional reaction",false]],"p":2},{"t":"single","q":"Scenario: An auditor cannot find any clause or procedure that the observed practice violates, but believes it is risky. Best action:","o":[["Raise it as an OFI/observation, not a nonconformity",true],["Raise a major nonconformity to be safe",false],["Force-fit it to an unrelated clause",false]],"p":2},{"t":"single","q":"Which is the clearest 'statement of nonconformity' (the why) for an unsigned release record?","o":[["The release record was not authorized as required, since the mandatory QA sign-off was absent",true],["The record looked wrong",false],["QA needs to sign records faster",false]],"p":1},{"t":"multi","q":"Which are risks of including presumed root cause in the nonconformity statement?","o":[["It may bias the auditee's own root cause analysis",true],["It may be wrong and undermine credibility",true],["It guarantees a faster corrective action",false],["It is required by ISO 19011",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"tf","q":"A nonconformity statement that is factual and specific but cites no requirement is still incomplete.","a":true,"p":1},{"t":"single","q":"Scenario: The same requirement (document control) is breached in five different ways across the site. Best handling:","o":[["Consider a single major nonconformity describing the systemic failure with examples, or assess against the requirement as a whole",true],["Write it as an OFI",false],["Ignore four and write only one minor",false]],"p":2,"ref":"ISO 17021-1:2015"},{"t":"tf","q":"Two auditors independently using the same nonconformity statement and evidence should reach the same conclusion about the breach.","a":true,"p":1},{"t":"single","q":"Which best shows 'one issue per nonconformity'?","o":[["A statement addressing only the expired calibration of gauge G-22",true],["A statement covering calibration, training, and housekeeping together",false],["A statement listing every finding from the day",false]],"p":1},{"t":"multi","q":"Which would weaken the defensibility of a nonconformity in a dispute?","o":[["Subjective adjectives without facts",true],["No traceable evidence reference",true],["A clearly cited clause",false],["A specific, dated record reference",false]],"p":2},{"t":"single","q":"A grade decision: a required management review has never been conducted since certification. This is best classified as:","o":[["Major nonconformity",true],["Minor nonconformity",false],["Observation",false]],"p":2,"ref":"ISO 17021-1:2015"},{"t":"multi","q":"Which principles from ISO 19011 support good nonconformity writing?","o":[["Evidence-based approach",true],["Fair presentation (truthful and accurate reporting)",true],["Confidentiality of personal blame in findings",false],["Maximising the number of findings",false]],"p":2,"ref":"ISO 19011:2018"},{"t":"tf","q":"It is acceptable to classify a nonconformity as major or minor based solely on how the auditee will react, rather than on the nature of the failure.","a":false,"p":1},{"t":"single","q":"Best way to handle a finding where the audit criterion itself is ambiguous:","o":[["Clarify the requirement with evidence before raising the nonconformity, or record an observation if no clear breach exists",true],["Raise a major nonconformity to force clarification",false],["Blame the auditee for the ambiguity",false]],"p":2},{"t":"short","q":"Critique and rewrite this weak nonconformity: 'Maintenance is bad; equipment keeps breaking and nobody seems to log it properly.' Provide an improved version.","m":"Looks for: identifies missing requirement, lack of objective evidence, subjective/blame language, and rewrites with a specific record/equipment ID, dated evidence, and a cited requirement plus the aspect not met.","p":3},{"t":"short","q":"Rewrite as a defensible statement: 'The QC team is careless because too many products fail final inspection.' Then explain each correction you made.","m":"Looks for: removes blame/opinion, adds factual evidence (e.g., specific lots/inspection records and rates), links to a requirement/spec, and frames the why; explanation maps each fix to a principle (factual, specific, traceable, no blame).","p":3},{"t":"short","q":"Given evidence that 3 of 12 sampled supplier files lacked the required approval before first order (procedure PR-03 cl. 5.1), draft a complete nonconformity statement with all three parts and justify whether it is major or minor.","m":"Looks for: requirement (PR-03 cl. 5.1), objective evidence (3 of 12 files, identifiable), statement of why (approval absent before first order); reasoned classification (likely minor unless systemic) with justification.","p":3},{"t":"short","q":"Explain how you would decide between recording a finding as a nonconformity versus an opportunity for improvement, and give a worked example for each from the same audit area.","m":"Looks for: nonconformity requires a breached requirement + objective evidence; OFI has no breach but room to improve; two coherent examples from one area showing the distinction.","p":3},{"t":"short","q":"Describe the common pitfalls that make nonconformity statements indefensible and how to avoid each. Address at least four pitfalls.","m":"Looks for: at least four of - vague language, missing/weak evidence, no linked requirement, blame/opinion, embedded solutions or root cause, multiple issues bundled, wrong classification; each paired with a concrete avoidance technique.","p":3},{"t":"single","q":"Which statement correctly separates the three parts? 'SOP-12 cl. 4 requires QC release before shipment; batch BR-301 shipped 5 Apr 2026 had no QC release; therefore product was shipped without the required QC release.'","o":[["Requirement, evidence, and why are all clearly present and distinct",true],["It contains an embedded corrective action",false],["It is missing the objective evidence",false]],"p":2},{"t":"tf","q":"When several minor nonconformities cluster against a single requirement, an auditor may reasonably escalate the classification to major if it indicates systemic failure.","a":true,"p":1,"ref":"ISO 17021-1:2015"}]}},"Corrective action planning":{"levels":{"1":[{"t":"single","q":"Which ISO 9001:2015 clause specifically addresses nonconformity and corrective action?","o":[["Clause 10.2",true],["Clause 6.1",false],["Clause 7.5",false]],"p":1,"ref":"ISO 9001:2015 §10.2"},{"t":"single","q":"What is the primary purpose of a corrective action?","o":[["To eliminate the cause of a nonconformity so it does not recur",true],["To immediately fix the affected product or service",false],["To record the nonconformity in the audit report",false]],"p":1,"ref":"ISO 9001:2015 §10.2"},{"t":"single","q":"What is the term for the immediate fix applied to deal with a detected nonconformity?","o":[["Correction",true],["Corrective action",false],["Preventive action",false]],"p":1,"ref":"ISO 9001:2015 §10.2"},{"t":"tf","q":"Correction and corrective action mean the same thing.","a":false,"p":1},{"t":"tf","q":"A corrective action is intended to prevent the recurrence of a nonconformity.","a":true,"p":1,"ref":"ISO 9001:2015 §10.2"},{"t":"single","q":"When a nonconformity occurs, what must the organization do first according to ISO 9001:2015?","o":[["React to it, including taking action to control and correct it",true],["Update the quality policy",false],["Schedule the next management review",false]],"p":1,"ref":"ISO 9001:2015 §10.2.1"},{"t":"tf","q":"Replacing a defective part for the customer, by itself, eliminates the cause of the nonconformity.","a":false,"p":1},{"t":"single","q":"What is a nonconformity?","o":[["A non-fulfilment of a requirement",true],["A customer complaint that has been resolved",false],["An opportunity for improvement",false]],"p":1,"ref":"ISO 9000:2015"},{"t":"single","q":"Which of these is an example of containment (correction) rather than corrective action?","o":[["Quarantining suspect stock to stop it being shipped",true],["Retraining operators to remove the cause of the error",false],["Revising a procedure to prevent the error recurring",false]],"p":1},{"t":"tf","q":"Corrective action should address the root cause, not just the symptom of a problem.","a":true,"p":1},{"t":"single","q":"Who should normally own a corrective action to closure?","o":[["A named, responsible person with appropriate authority",true],["Any available employee",false],["Only the external auditor",false]],"p":1},{"t":"tf","q":"Every corrective action must be reviewed for effectiveness after it has been implemented.","a":true,"p":1,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"Which document records the evidence that a corrective action was taken and was effective?","o":[["Retained documented information",true],["The organization's marketing brochure",false],["The supplier price list",false]],"p":1,"ref":"ISO 9001:2015 §10.2.2"},{"t":"tf","q":"A corrective action with no due date or owner is well planned.","a":false,"p":1},{"t":"single","q":"What is the term for action taken to eliminate the cause of a POTENTIAL nonconformity before it occurs?","o":[["Preventive action",true],["Correction",false],["Corrective action",false]],"p":1,"ref":"ISO 9000:2015"},{"t":"single","q":"Where do organizations look to determine whether a similar nonconformity exists or could occur?","o":[["Elsewhere in the organization or in similar processes",true],["Only in the single process where it was found",false],["Only in the finance department",false]],"p":1,"ref":"ISO 9001:2015 §10.2.1"},{"t":"tf","q":"If no corrective action is taken, the organization is not required to retain any documented information about the nonconformity.","a":false,"p":1,"ref":"ISO 9001:2015 §10.2.2"},{"t":"single","q":"Corrective action must be appropriate to what?","o":[["The effects of the nonconformities encountered",true],["The size of the organization's marketing budget",false],["The number of employees present that day",false]],"p":1,"ref":"ISO 9001:2015 §10.2.1"},{"t":"tf","q":"Reviewing the effectiveness of a corrective action may show that the action did not actually remove the cause.","a":true,"p":1},{"t":"single","q":"Which of the following best describes good timeliness in corrective action planning?","o":[["Actions have realistic target dates and are tracked to closure",true],["Actions are left open indefinitely until convenient",false],["Actions are closed immediately without verification",false]],"p":1}],"2":[{"t":"single","q":"In the ISO 9001:2015 corrective action sequence, what comes immediately after reacting to and correcting the nonconformity?","o":[["Evaluating the need for action to eliminate the cause",true],["Updating risks and opportunities",false],["Changing the quality management system",false]],"p":1,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"Why is correction alone usually insufficient as a response to a nonconformity?","o":[["It fixes the immediate issue but leaves the cause in place, so the problem can recur",true],["It is more expensive than corrective action",false],["It is prohibited by ISO 9001",false]],"p":1},{"t":"multi","q":"Which of the following are required steps within the ISO 9001:2015 corrective action process?","o":[["Determine the causes of the nonconformity",true],["Determine if similar nonconformities exist or could potentially occur",true],["Notify all customers regardless of relevance",false],["Discard all records of the nonconformity",false]],"p":2,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"An operator error caused a mislabeled batch. Which response targets the root cause rather than the symptom?","o":[["Investigating why the labeling step allowed the error and mistake-proofing it",true],["Relabeling the affected batch and shipping it",false],["Apologizing to the customer",false]],"p":1},{"t":"single","q":"What is the main risk of closing a corrective action without verifying effectiveness?","o":[["The cause may remain and the nonconformity can recur unnoticed",true],["The audit will take less time",false],["The documented information becomes confidential",false]],"p":2},{"t":"multi","q":"Which of the following are valid root cause analysis techniques used in corrective action planning?","o":[["5 Whys",true],["Fishbone (Ishikawa) diagram",true],["Coin flip",false],["Choosing the most convenient blameable person",false]],"p":2},{"t":"single","q":"How does ISO 9001:2015 treat 'preventive action' compared with the 1994/2008 versions?","o":[["It is largely addressed through risk-based thinking in clause 6.1 rather than a separate clause",true],["It is a mandatory standalone clause 10.4",false],["It has been removed entirely with no equivalent concept",false]],"p":2,"ref":"ISO 9001:2015 §6.1"},{"t":"single","q":"After implementing a corrective action, the organization must, if necessary, do which of the following?","o":[["Update the risks and opportunities determined during planning",true],["Delete the original nonconformity record",false],["Stop monitoring the affected process",false]],"p":1,"ref":"ISO 9001:2015 §10.2.1"},{"t":"multi","q":"Which documented information must be retained as evidence under ISO 9001:2015 clause 10.2.2?","o":[["The nature of the nonconformities and any subsequent actions taken",true],["The results of any corrective action",true],["The personal medical records of staff involved",false],["The organization's competitors' pricing",false]],"p":2,"ref":"ISO 9001:2015 §10.2.2"},{"t":"single","q":"A recurring nonconformity keeps reappearing despite repeated 'corrections'. What does this most likely indicate?","o":[["The corrective action did not address the true root cause",true],["The standard does not apply",false],["The nonconformity should be ignored",false]],"p":2},{"t":"single","q":"Why must a corrective action be scaled to the effects of the nonconformity?","o":[["So effort is proportionate to risk and consequences, avoiding both under- and over-reaction",true],["So every action requires board sign-off",false],["So all actions take exactly the same amount of time",false]],"p":1,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"Which statement best distinguishes risk-based thinking from traditional preventive action?","o":[["Risk-based thinking is built into the whole management system rather than being a separate after-the-fact procedure",true],["Risk-based thinking only applies after a nonconformity occurs",false],["Risk-based thinking replaces corrective action entirely",false]],"p":2,"ref":"ISO 9001:2015 §6.1"},{"t":"single","q":"When determining causes, why is it important to ask whether similar nonconformities exist elsewhere?","o":[["The same cause may affect other processes, products, or sites that have not yet failed",true],["It is only done to lengthen the report",false],["It is forbidden under clause 10.2",false]],"p":1,"ref":"ISO 9001:2015 §10.2.1"},{"t":"multi","q":"Which of the following indicate a poorly planned corrective action?","o":[["No assigned owner",true],["No target completion date",true],["A defined method to verify effectiveness",false],["Root cause clearly identified",false]],"p":2},{"t":"single","q":"What is the correct order: react/contain, then which sequence?","o":[["Evaluate need, determine causes, check for similar NCs, implement action, review effectiveness, update risks, change the MS if needed",true],["Change the MS, implement action, then evaluate need",false],["Review effectiveness, determine causes, then react",false]],"p":2,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"A corrective action proposes 'remind staff to be more careful'. Why is this generally weak?","o":[["It relies on human vigilance and does not change the system or remove the cause",true],["It is too expensive to implement",false],["It is prohibited by ISO 9001",false]],"p":2},{"t":"tf","q":"Verifying effectiveness can include monitoring data over a defined period to confirm the nonconformity has not recurred.","a":true,"p":1},{"t":"single","q":"Which is the best evidence that a corrective action was effective?","o":[["Objective data showing the nonconformity has not recurred over a meaningful period",true],["A verbal assurance from the action owner",false],["The fact that the action was marked closed in the system",false]],"p":2},{"t":"single","q":"During corrective action, when might an organization need to change the quality management system itself?","o":[["When the root cause reveals a gap in a process, procedure, or control that must be redesigned",true],["Whenever any nonconformity occurs, regardless of cause",false],["Never, the MS must remain unchanged",false]],"p":1,"ref":"ISO 9001:2015 §10.2.1"},{"t":"multi","q":"Which of the following are legitimate inputs that may trigger corrective action?","o":[["Customer complaints",true],["Internal audit findings",true],["A sunny weather forecast",false],["The CEO's favorite color",false]],"p":2},{"t":"single","q":"What distinguishes 'correction' from 'corrective action' in a single sentence?","o":[["Correction fixes the immediate nonconformity; corrective action removes its cause to prevent recurrence",true],["Correction prevents recurrence; corrective action only fixes the symptom",false],["They are interchangeable terms with no difference",false]],"p":1,"ref":"ISO 9001:2015 §10.2"},{"t":"single","q":"Why should corrective action effectiveness review be planned at the time the action is defined?","o":[["So the verification criteria and timing are clear and the action is not closed prematurely",true],["So the action can be closed before it is implemented",false],["Because reviews are optional and rarely done",false]],"p":2},{"t":"tf","q":"It is acceptable to assign one corrective action to address multiple distinct root causes identified during analysis.","a":false,"p":2},{"t":"single","q":"A team identifies three contributing causes for a nonconformity. What is the best planning approach?","o":[["Define actions addressing each significant cause, with owners and dates",true],["Pick the easiest single cause and ignore the rest",false],["Close the nonconformity without action",false]],"p":2},{"t":"short","q":"Explain the difference between correction and corrective action, giving one example of each.","m":"Looks for: correction = immediate fix/containment of the nonconformity (e.g. rework, scrap, quarantine); corrective action = eliminating the root cause to prevent recurrence (e.g. revise procedure, mistake-proof process); a clear example for each.","p":2},{"t":"short","q":"List, in order, the main steps ISO 9001:2015 requires when a nonconformity occurs.","m":"Looks for: react/control and correct, evaluate the need for action to eliminate cause, determine causes, determine if similar NCs exist, implement action, review effectiveness, update risks/opportunities, change the MS if needed.","p":2}],"3":[{"t":"single","q":"A weld defect recurs across three production lines. The team fixes only the line where it was found. What is the most significant planning failure?","o":[["They did not determine whether similar nonconformities existed elsewhere before acting",true],["They documented the action too thoroughly",false],["They reviewed effectiveness too early",false]],"p":2,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"An auditor sees a corrective action closed the same day it was raised, with 'product reworked' as evidence. What is the correct finding?","o":[["Only correction was performed; corrective action to address the cause and verify effectiveness is missing",true],["The action is fully compliant and complete",false],["The nonconformity should be re-raised as a preventive action",false]],"p":2,"ref":"ISO 9001:2015 §10.2"},{"t":"single","q":"Root cause analysis concludes 'operator did not follow the procedure'. Why is this often an inadequate stopping point?","o":[["It stops at a symptom; it does not ask why the procedure was not followed or could not be followed",true],["It is too detailed for corrective action",false],["Procedures are never relevant to root cause",false]],"p":2},{"t":"multi","q":"In a robust corrective action plan for a systemic nonconformity, which elements should be present?","o":[["Verified root cause(s)",true],["Specific actions with owners and due dates",true],["A defined method and timing to verify effectiveness",true],["A statement that no records will be kept",false]],"p":2,"ref":"ISO 9001:2015 §10.2.2"},{"t":"single","q":"After a corrective action, monitoring shows the nonconformity recurred three months later. What should happen?","o":[["The corrective action is treated as ineffective and the cause re-investigated; the MS may need further change",true],["The recurrence is ignored because an action was already taken",false],["The original record is deleted to keep metrics clean",false]],"p":2,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"How should risk-based thinking interact with a completed corrective action?","o":[["The risks and opportunities identified in planning should be updated to reflect what was learned",true],["Risks should never be revisited once set",false],["Corrective action replaces the need to consider risk",false]],"p":2,"ref":"ISO 9001:2015 §6.1"},{"t":"multi","q":"Which of the following are signs that a corrective action only addressed a symptom?","o":[["The same nonconformity recurs after the action",true],["The action is purely a one-time correction relabeled as corrective action",true],["The root cause statement merely restates the problem",true],["Objective data confirm no recurrence over time",false]],"p":2},{"t":"single","q":"A nonconformity has minimal effect and almost no chance of recurrence. What does clause 10.2 allow?","o":[["The extent of corrective action can be proportionate, including deciding limited action is appropriate to the effects",true],["The same exhaustive action as for a critical safety issue is mandatory",false],["No documentation of the decision is permitted",false]],"p":2,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"Why is assigning corrective actions without authority or resources a planning weakness?","o":[["The owner cannot implement the change, so the action stalls and the cause persists",true],["It speeds up closure",false],["It is required by clause 10.2",false]],"p":2},{"t":"multi","q":"Which practices strengthen the verification of corrective action effectiveness?","o":[["Defining measurable acceptance criteria up front",true],["Monitoring relevant data over a defined period before closing",true],["Closing the action based on the owner's opinion alone",false],["Verifying only that the paperwork was filed",false]],"p":2},{"t":"single","q":"A supplier ships out-of-spec parts. The organization sorts the current lot and continues. Which step of clause 10.2 is most clearly missing?","o":[["Determining and eliminating the cause, including supplier-side action, to prevent recurrence",true],["Reacting to the nonconformity",false],["Retaining a record of the nonconformity",false]],"p":2,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"Two nonconformities share the same underlying cause but were raised separately. What is the best planning response?","o":[["Address the common root cause once and link both records, verifying effectiveness against both",true],["Raise a third unrelated action",false],["Close both with corrections only",false]],"p":2},{"t":"single","q":"What is the role of timeliness in corrective action, beyond meeting an audit deadline?","o":[["Delays leave the cause active, so further nonconformities and risk exposure continue to accumulate",true],["Timeliness only matters for cosmetic reasons",false],["Faster closure always means a better root cause",false]],"p":2},{"t":"multi","q":"Which inputs should feed the evaluation of whether corrective action is needed?","o":[["Severity and consequences of the nonconformity",true],["Likelihood of recurrence",true],["Whether similar nonconformities exist elsewhere",true],["The day of the week the issue was found",false]],"p":2,"ref":"ISO 9001:2015 §10.2.1"},{"t":"single","q":"During management review, corrective action data show many actions reopened after closure. What does this most likely reveal?","o":[["Weak root cause analysis and/or inadequate effectiveness verification",true],["That corrective action is unnecessary",false],["That the standard should be ignored",false]],"p":2},{"t":"single","q":"Why might a corrective action legitimately require a change to the quality management system?","o":[["Because the root cause exposed a flawed or missing process, control, or competence that must be redesigned, not just patched",true],["Because any nonconformity automatically rewrites the whole MS",false],["Because the MS must change after every audit",false]],"p":2,"ref":"ISO 9001:2015 §10.2.1"},{"t":"multi","q":"Which statements about preventive action and risk-based thinking in ISO 9001:2015 are correct?","o":[["Risk-based thinking aims to prevent nonconformities before they occur",true],["Risk and opportunity actions are addressed in clause 6.1",true],["Preventive action exists as a separate standalone clause in the 2015 version",false],["Risk-based thinking is only triggered by customer complaints",false]],"p":2,"ref":"ISO 9001:2015 §6.1"},{"t":"single","q":"A corrective action's effectiveness check is scheduled for a date before the action is even implemented. What is wrong?","o":[["Effectiveness cannot be verified until the action has been in place long enough to generate evidence",true],["Nothing; earlier is always better",false],["Effectiveness checks are not required",false]],"p":2},{"t":"single","q":"What best characterizes a strong, well-bounded root cause statement?","o":[["It identifies a specific, addressable cause whose removal would prevent recurrence",true],["It assigns blame to an individual",false],["It simply restates the nonconformity in different words",false]],"p":2},{"t":"multi","q":"In a corrective action register, which fields support good governance and ownership?","o":[["Responsible owner",true],["Target and actual completion dates",true],["Effectiveness verification status",true],["The owner's favorite lunch",false]],"p":2},{"t":"single","q":"An organization closes corrective actions on schedule but recurrence rates do not fall. The MOST useful improvement is which of the following?","o":[["Strengthen root cause analysis and effectiveness verification rather than focus on closure speed",true],["Set even tighter closure deadlines",false],["Stop raising nonconformities",false]],"p":2},{"t":"single","q":"How should containment (correction) and corrective action be sequenced in time?","o":[["Contain immediately to limit harm, then pursue corrective action to eliminate the cause",true],["Skip containment and wait for the full root cause analysis",false],["Do corrective action first, then decide whether to contain",false]],"p":2},{"t":"tf","q":"A corrective action plan should explicitly state how and when effectiveness will be confirmed.","a":true,"p":2},{"t":"single","q":"Which scenario best demonstrates updating risks after corrective action?","o":[["A near-miss reveals a hazard, prompting the organization to revise its risk register and add a new control",true],["The organization deletes the near-miss to avoid record-keeping",false],["The organization repeats the same correction whenever the issue arises",false]],"p":2,"ref":"ISO 9001:2015 §6.1"},{"t":"single","q":"Why is it important to distinguish 'cause' from 'contributing factors' when planning corrective action?","o":[["Addressing only contributing factors may not stop recurrence if the underlying cause remains",true],["They are identical and need no distinction",false],["Contributing factors are always irrelevant",false]],"p":2},{"t":"single","q":"A corrective action is documented but no evidence of implementation or verification is retained. Which clause 10.2.2 requirement is unmet?","o":[["Retaining documented information on the results of any corrective action",true],["Determining the quality policy",false],["Conducting a customer satisfaction survey",false]],"p":2,"ref":"ISO 9001:2015 §10.2.2"},{"t":"single","q":"Which of the following best reflects proportionality in corrective action planning?","o":[["A safety-critical recurring defect gets deep analysis and systemic change; a minor one-off cosmetic flaw gets lighter action",true],["Every nonconformity receives identical exhaustive treatment",false],["Severity has no bearing on the action taken",false]],"p":2,"ref":"ISO 9001:2015 §10.2.1"},{"t":"short","q":"A customer complaint reveals that shipped product was mislabeled. Describe a complete corrective action plan, from containment through verifying effectiveness.","m":"Looks for: immediate containment/correction (quarantine, recall or rework mislabeled stock), evaluate need for action, root cause analysis of why labeling failed, check for similar NCs on other products/lines, implement systemic action (e.g. mistake-proofing, process/control change), assign owner and due date, verify effectiveness with data over time, update risks and MS if needed, retain records.","p":3},{"t":"short","q":"Explain why 'retraining the operator' is frequently an inadequate corrective action and what a stronger plan might include.","m":"Looks for: retraining addresses a symptom/human factor and assumes operator was the cause; recurrence likely if the system permits the error; stronger plan investigates why the procedure was unclear/unfollowable, mistake-proofs the process, changes the control or design, and verifies effectiveness rather than relying on vigilance.","p":3},{"t":"short","q":"Describe how risk-based thinking in ISO 9001:2015 relates to the older concept of preventive action.","m":"Looks for: 2015 version removed the standalone preventive action clause; prevention is embedded throughout via risk-based thinking (clause 6.1) so risks/opportunities are addressed proactively across the system rather than as a separate reactive procedure; corrective action updates risks afterward.","p":3},{"t":"short","q":"Outline how you would verify that a corrective action has been effective, and what to do if it has not.","m":"Looks for: define measurable acceptance criteria up front, monitor relevant data over a defined period, confirm the nonconformity has not recurred and the cause is removed before closing; if ineffective, treat as not closed, re-investigate root cause, revise the action and possibly the MS, retain records of the review.","p":3},{"t":"short","q":"A manager wants all corrective actions closed within 48 hours to improve metrics. Critique this policy from a corrective action planning perspective.","m":"Looks for: pressure to close fast encourages corrections over real corrective action; insufficient time for root cause analysis and for effectiveness verification (which needs data over time); metric becomes closure speed not effectiveness; better approach is realistic dates scaled to complexity, with verification before closure and tracking of recurrence rates.","p":3}]}},"Incident investigation":{"levels":{"1":[{"t":"single","q":"In OH&S terms, what is an 'incident'?","o":[["An occurrence arising out of, or in the course of, work that could or did result in injury or ill health",true],["Only an event that results in a fatality",false],["A planned safety drill",false]],"p":1,"ref":"ISO 45001:2018 §3.35"},{"t":"single","q":"What term best describes a 'near-miss'?","o":[["An incident where no injury, ill health or damage occurred but had the potential to",true],["An incident causing permanent disability",false],["A scheduled maintenance task",false]],"p":1,"ref":"ISO 45001:2018 §3.35"},{"t":"single","q":"An 'accident' is most accurately defined as an incident that:","o":[["Resulted in injury, ill health or damage",true],["Was deliberately caused",false],["Had no consequences at all",false]],"p":1},{"t":"single","q":"Which clause of ISO 45001:2018 deals with incident investigation and corrective action?","o":[["Clause 10.2",true],["Clause 4.1",false],["Clause 7.2",false]],"p":1,"ref":"ISO 45001:2018 §10.2"},{"t":"single","q":"What is the FIRST priority when arriving at an incident scene?","o":[["Make the area safe and protect people from further harm",true],["Begin interviewing witnesses",false],["Write the final report",false]],"p":1},{"t":"single","q":"Why should an incident scene be preserved as soon as possible?","o":[["To prevent loss or alteration of physical evidence",true],["To delay production restart indefinitely",false],["To assign blame to a worker",false]],"p":1},{"t":"single","q":"Which of these is a common evidence category in the '4 Ps' approach?","o":[["People",true],["Profit",false],["Promotion",false]],"p":1},{"t":"single","q":"When should an incident investigation ideally begin?","o":[["As soon as practicable after the scene is made safe",true],["Several weeks later, once everyone has forgotten",false],["Only after the next audit",false]],"p":1},{"t":"single","q":"What kind of questions should an interviewer mainly use with witnesses?","o":[["Open questions",true],["Leading questions",false],["Accusatory questions",false]],"p":1},{"t":"single","q":"What is the 'immediate cause' of an incident?","o":[["The unsafe act or condition that directly led to the event",true],["The organisation's annual turnover",false],["The weather forecast for next week",false]],"p":1},{"t":"single","q":"What is a 'root cause'?","o":[["The underlying reason that, if corrected, would prevent recurrence",true],["The first witness to arrive",false],["The colour of the warning sign",false]],"p":1},{"t":"single","q":"Which control is the MOST effective in the hierarchy of controls?","o":[["Elimination",true],["Personal protective equipment",false],["Warning signs",false]],"p":1},{"t":"single","q":"Which control is the LEAST effective in the hierarchy of controls?","o":[["Personal protective equipment",true],["Substitution",false],["Engineering controls",false]],"p":1},{"t":"single","q":"What is a 'dangerous occurrence'?","o":[["A specified high-potential event that must be reported even if no one was hurt",true],["A minor cut requiring a plaster",false],["A routine toolbox talk",false]],"p":1},{"t":"single","q":"A non-blame investigation approach mainly aims to:","o":[["Encourage open reporting and find systemic causes",true],["Identify a single person to punish",false],["Avoid recording any findings",false]],"p":1},{"t":"tf","q":"A near-miss should be investigated even though no one was injured.","a":true,"p":1},{"t":"tf","q":"The main purpose of an incident investigation is to assign blame to the worker involved.","a":false,"p":1},{"t":"tf","q":"Witness accounts can change over time, so they should be gathered promptly.","a":true,"p":1},{"t":"tf","q":"Personal protective equipment is the strongest control in the hierarchy of controls.","a":false,"p":1},{"t":"tf","q":"Photographs and sketches of the scene are useful forms of physical evidence.","a":true,"p":1}],"2":[{"t":"single","q":"Which sequence best reflects a logical investigation process?","o":[["Make safe, gather evidence, analyse causes, recommend actions, report",true],["Report, recommend actions, gather evidence, make safe",false],["Analyse causes, make safe, report, gather evidence",false]],"p":1},{"t":"single","q":"In causal analysis, 'underlying causes' typically refer to:","o":[["Contributing factors behind the immediate cause, such as inadequate procedures or supervision",true],["The exact second the incident occurred",false],["The name of the investigator",false]],"p":1},{"t":"single","q":"Why is investigator impartiality important?","o":[["It ensures conclusions are based on evidence rather than bias",true],["It guarantees no corrective actions are needed",false],["It allows the report to be skipped",false]],"p":1},{"t":"single","q":"Which of the '4 Ps' covers procedures, permits and records?","o":[["Paper",true],["Position",false],["People",false]],"p":1},{"t":"single","q":"Which of the '4 Ps' covers the layout and physical positions of plant and people?","o":[["Position",true],["Paper",false],["Parts",false]],"p":1},{"t":"single","q":"A 'just culture' balances which two ideas?","o":[["Individual accountability and a non-punitive, systems-focused response",true],["Punishment and secrecy",false],["Speed and ignoring evidence",false]],"p":1},{"t":"single","q":"When interviewing a witness, an investigator should:","o":[["Interview them individually and separately from others",true],["Interview all witnesses together to save time",false],["Tell them what the other witnesses said first",false]],"p":1},{"t":"single","q":"Per ISO 45001:2018 §10.2, after determining the root cause(s), the organisation must:","o":[["Determine and implement action to eliminate the causes and prevent recurrence",true],["Close the case without action",false],["Only update the canteen menu",false]],"p":1,"ref":"ISO 45001:2018 §10.2"},{"t":"single","q":"Which factor is an example of a 'human factor' that should be examined, not blamed?","o":[["Fatigue caused by excessive shift length",true],["The worker's personality alone",false],["The worker's choice of lunch",false]],"p":1},{"t":"single","q":"A corrective action is considered effective when it:","o":[["Prevents recurrence by addressing the root cause",true],["Simply reminds workers to be careful",false],["Closes the report quickly",false]],"p":1},{"t":"single","q":"Why is a legal or regulatory notification sometimes required after an incident?","o":[["Certain serious injuries and dangerous occurrences are reportable by law",true],["To advertise the company",false],["To avoid writing any report",false]],"p":1},{"t":"single","q":"What distinguishes a contributory factor from the root cause?","o":[["A contributory factor increases the likelihood or severity but is not the underlying systemic reason",true],["A contributory factor is always the only cause",false],["There is no difference between them",false]],"p":1},{"t":"single","q":"Which document output captures what the organisation learned to share across sites?","o":[["A lessons-learned communication or safety alert",true],["A purchase order",false],["An employee parking permit",false]],"p":1},{"t":"tf","q":"Leading questions during interviews can distort a witness's recollection.","a":true,"p":1},{"t":"tf","q":"A single incident can have more than one root cause.","a":true,"p":1},{"t":"tf","q":"Corrective actions should be assigned an owner and a target completion date.","a":true,"p":1},{"t":"multi","q":"Which of the following are valid reasons to investigate incidents? (Select all that apply.)","o":[["To identify root causes and prevent recurrence",true],["To meet legal and standard requirements",true],["To identify a worker to dismiss",false],["To improve risk controls and learn lessons",true]],"p":2},{"t":"multi","q":"Which of the following are part of the '4 Ps' evidence-gathering model? (Select all that apply.)","o":[["People",true],["Parts",true],["Position",true],["Profit",false]],"p":2},{"t":"multi","q":"Which actions help preserve incident scene evidence? (Select all that apply.)","o":[["Cordon off the area",true],["Photograph the scene before moving items",true],["Record positions of equipment and people",true],["Clean up immediately to resume work",false]],"p":2},{"t":"multi","q":"Which are characteristics of effective witness interviewing? (Select all that apply.)","o":[["Use open, non-leading questions",true],["Adopt a non-blaming tone",true],["Interview witnesses separately",true],["Accuse the witness of negligence",false]],"p":2},{"t":"multi","q":"Which of these are root or underlying causes rather than immediate causes? (Select all that apply.)","o":[["Inadequate training",true],["Poor maintenance management",true],["A guard that was physically missing at the moment of injury",false],["Insufficient supervision",true]],"p":2},{"t":"multi","q":"Which controls rank above PPE in the hierarchy of controls? (Select all that apply.)","o":[["Elimination",true],["Substitution",true],["Engineering controls",true],["Warning signs alone",false]],"p":2},{"t":"single","q":"Why should corrective actions be tracked to closure?","o":[["To verify they are implemented and effective in preventing recurrence",true],["To increase paperwork for its own sake",false],["To delay the investigation",false]],"p":1},{"t":"short","q":"Explain the difference between a near-miss and an accident, and why both are worth investigating.","m":"Looks for: near-miss = potential but no harm/damage; accident = harm/damage occurred; both share causes; investigating near-misses prevents future accidents.","p":2},{"t":"short","q":"List the typical sequence of steps in conducting an incident investigation.","m":"Looks for: secure/make scene safe; preserve evidence; gather facts (people, parts, position, paper); interview witnesses; analyse causes (immediate, underlying, root); recommend controls; report; corrective action; follow-up/lessons learned.","p":2},{"t":"single","q":"Which of these is the best reason to investigate near-misses as well as injuries?","o":[["They share the same underlying causes and offer free lessons before harm occurs",true],["They never need any action",false],["They are always more serious than accidents",false]],"p":1}],"3":[{"t":"single","q":"In root cause analysis, repeatedly asking 'why' to trace a causal chain is associated with which technique?","o":[["The 5 Whys",true],["SWOT analysis",false],["Gantt charting",false]],"p":1},{"t":"single","q":"A fishbone (Ishikawa) diagram is used in investigation primarily to:","o":[["Organise possible causes into categories to explore contributory factors",true],["Schedule corrective actions over time",false],["Calculate insurance premiums",false]],"p":1},{"t":"single","q":"Per ISO 45001:2018 §10.2, evidence that corrective action was effective should be:","o":[["Reviewed, with the action's effectiveness evaluated and documented",true],["Assumed without verification",false],["Discarded after closure",false]],"p":1,"ref":"ISO 45001:2018 §10.2"},{"t":"single","q":"Which statement best reflects a human-factors view of an operator 'error'?","o":[["The error is often a symptom of deeper system and design weaknesses",true],["The error proves the operator is solely to blame",false],["The error should be ignored entirely",false]],"p":1},{"t":"single","q":"When immediate corrective action and the formal investigation conflict on timing, the investigator should:","o":[["Take interim measures to control risk while preserving evidence for the full investigation",true],["Skip interim measures and wait for the final report",false],["Destroy evidence to speed things up",false]],"p":1},{"t":"single","q":"Why is it important to distinguish 'active failures' from 'latent conditions'?","o":[["Latent conditions are dormant organisational weaknesses that enable active failures and must be addressed to prevent recurrence",true],["Active failures are always irrelevant",false],["Latent conditions never matter",false]],"p":1},{"t":"single","q":"An investigation finds the same root cause as a previous incident. This most likely indicates:","o":[["The earlier corrective action was ineffective or not implemented",true],["Investigations are unnecessary",false],["The root cause was correct and nothing more is needed",false]],"p":1},{"t":"single","q":"Per ISO 45001:2018 §10.2, the results of investigations should be:","o":[["Communicated to relevant interested parties, including worker representatives where appropriate",true],["Kept secret from all workers",false],["Shared only with competitors",false]],"p":1,"ref":"ISO 45001:2018 §10.2"},{"t":"single","q":"The level of investigation effort applied to an incident should normally be proportional to:","o":[["The actual and potential severity and likelihood of recurrence",true],["The seniority of the nearest manager",false],["The time of day it happened",false]],"p":1},{"t":"single","q":"Which is the best example of an evidence-based, non-blaming root-cause statement?","o":[["The guard interlock had been bypassed because the procedure made the machine impractical to operate as designed",true],["The operator was careless and deserves discipline",false],["Bad luck caused the injury",false]],"p":1},{"t":"single","q":"When witness recollections conflict, the investigator should:","o":[["Corroborate accounts against physical evidence rather than simply choosing one",true],["Accept the most senior person's account automatically",false],["Discard all witness evidence",false]],"p":1},{"t":"tf","q":"Addressing only the immediate cause of an incident, without the root cause, leaves the risk of recurrence largely unchanged.","a":true,"p":1},{"t":"tf","q":"Disciplining a worker is usually an effective corrective action because it removes the hazard.","a":false,"p":1},{"t":"tf","q":"Interim controls may be put in place before the investigation is complete.","a":true,"p":1},{"t":"tf","q":"A just culture means no one is ever held accountable for reckless or wilful violations.","a":false,"p":1},{"t":"multi","q":"Which of the following are recognised root cause analysis methods? (Select all that apply.)","o":[["5 Whys",true],["Fishbone (Ishikawa) diagram",true],["Fault tree analysis",true],["Coin toss",false]],"p":2},{"t":"multi","q":"Which factors typically belong to 'organisational' or 'latent' causes? (Select all that apply.)","o":[["Inadequate procedures",true],["Insufficient training and competence",true],["Production pressure overriding safety",true],["The exact angle of the falling object at impact",false]],"p":2},{"t":"multi","q":"Which elements should appear in a sound incident investigation report? (Select all that apply.)","o":[["Description of what happened and the consequences",true],["Causal analysis (immediate, underlying, root)",true],["Recommended controls and corrective actions with owners and dates",true],["Personal opinions about who to blame",false]],"p":2},{"t":"multi","q":"Which practices support a fair, just-culture investigation? (Select all that apply.)","o":[["Focusing on system and design weaknesses",true],["Separating honest error from reckless violation",true],["Protecting reporters of near-misses from punishment",true],["Naming and shaming the worker in the report",false]],"p":2},{"t":"multi","q":"Which are appropriate corrective actions, ranked using the hierarchy of controls? (Select all that apply.)","o":[["Eliminate the hazardous process step",true],["Substitute a less hazardous material",true],["Add an engineering interlock",true],["Issue a verbal reminder to be careful",false]],"p":2},{"t":"multi","q":"Which are legitimate sources of physical and documentary evidence? (Select all that apply.)","o":[["Damaged parts and equipment",true],["Maintenance and training records",true],["CCTV footage and photographs",true],["A guess about what probably happened",false]],"p":2},{"t":"single","q":"Which best describes why timeliness matters in evidence gathering?","o":[["Physical evidence can be disturbed and memories fade, reducing accuracy over time",true],["Late evidence is automatically more reliable",false],["Timing has no effect on evidence quality",false]],"p":1},{"t":"single","q":"A corrective action that relies solely on retraining the injured worker is often weak because:","o":[["It does not change the underlying conditions that allowed the incident, so others remain exposed",true],["Retraining is always illegal",false],["The worker can never be retrained",false]],"p":1},{"t":"short","q":"Scenario: A maintenance technician receives an electric shock while working on a machine that was supposedly isolated. Outline how you would investigate, identifying likely immediate, underlying and root causes.","m":"Looks for: make safe and preserve scene; verify isolation/lockout-tagout status; immediate cause = live circuit/failed isolation; underlying = inadequate LOTO procedure, lack of verification step, training/supervision gaps; root = system/management failure in energy-control programme; non-blame; corrective actions up the hierarchy.","p":3},{"t":"short","q":"Scenario: Two witnesses to a forklift incident give contradictory accounts of the forklift's speed. Explain how you would handle the conflicting evidence.","m":"Looks for: interview separately; use open questions; corroborate with physical evidence (skid marks, damage, telematics/CCTV, load); avoid leading; document both accounts; weigh against objective data rather than seniority; remain impartial.","p":3},{"t":"short","q":"Explain the difference between immediate, underlying and root causes, using a worked example.","m":"Looks for: immediate = unsafe act/condition at point of event; underlying = contributory factors (procedures, supervision, design); root = systemic management failure; coherent example linking the three levels; recurrence prevention via root cause.","p":3},{"t":"short","q":"Describe how the hierarchy of controls should guide the corrective actions arising from an investigation, and why PPE-only fixes are discouraged.","m":"Looks for: elimination > substitution > engineering > administrative > PPE; prefer higher-order controls; PPE relies on human behaviour and is last resort; justify selection; verify effectiveness.","p":3},{"t":"short","q":"Explain how a 'just culture' and human-factors thinking improve incident investigation outcomes and reporting rates.","m":"Looks for: non-blame encourages open reporting of near-misses; distinguishes error from reckless violation; focuses on system/design fixes; balances accountability and learning; improves data quality and prevention; links to ISO 45001 worker participation.","p":3},{"t":"single","q":"Why is it best practice for the investigation team to be independent of those directly responsible for the area or activity involved?","o":[["To reduce conflict of interest and bias when determining causes",true],["Because only outsiders understand the process",false],["To make the report easier to ignore",false]],"p":1},{"t":"single","q":"A recommended action reads 'remind staff to take more care'. The strongest critique is that it:","o":[["Relies on behaviour, is low in the hierarchy of controls, and does not address the root cause",true],["Is too expensive to implement",false],["Is the most effective possible control",false]],"p":1},{"t":"single","q":"In a timeline (sequence-of-events) reconstruction, the main purpose is to:","o":[["Establish the order and timing of events to expose decision points and contributory factors",true],["Decide who to discipline first",false],["Replace the need for physical evidence",false]],"p":1},{"t":"multi","q":"Which outputs should an investigation feed into the wider OH&S management system? (Select all that apply.)","o":[["Updated risk assessments and controls",true],["Lessons learned shared across relevant sites",true],["Revised procedures or training where needed",true],["Permanent concealment of the findings",false]],"p":2}]}},"Hazard identification":{"levels":{"1":[{"t":"single","q":"In OH&S terms, what is a 'hazard'?","o":[["A source or situation with the potential to cause harm or injury",true],["The probability that harm will actually occur",false],["The financial cost of an incident",false]],"p":1,"ref":"ISO 45001:2018 §3.19"},{"t":"single","q":"How is 'risk' best distinguished from a 'hazard'?","o":[["Risk combines the likelihood of exposure with the severity of the resulting harm",true],["Risk and hazard mean exactly the same thing",false],["Risk only applies to chemical substances",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2"},{"t":"tf","q":"A spilled liquid on a walkway is an example of a hazard.","a":true,"p":1},{"t":"tf","q":"A hazard and a risk are identical concepts that can be used interchangeably.","a":false,"p":1},{"t":"single","q":"Loud machinery noise that can damage hearing belongs to which hazard category?","o":[["Physical",true],["Biological",false],["Psychosocial",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2"},{"t":"single","q":"Exposure to a corrosive cleaning agent is which type of hazard?","o":[["Chemical",true],["Ergonomic",false],["Mechanical",false]],"p":1},{"t":"single","q":"Working with patients who may carry an infectious virus is which hazard category?","o":[["Biological",true],["Electrical",false],["Physical",false]],"p":1},{"t":"single","q":"Repetitive lifting causing back strain is classified as which hazard?","o":[["Ergonomic",true],["Chemical",false],["Biological",false]],"p":1},{"t":"single","q":"Excessive workload, bullying, and harassment are examples of which hazard category?","o":[["Psychosocial",true],["Physical",false],["Mechanical",false]],"p":1},{"t":"single","q":"An unguarded rotating shaft that could trap clothing is which type of hazard?","o":[["Mechanical",true],["Chemical",false],["Psychosocial",false]],"p":1},{"t":"single","q":"A frayed power cable that could cause a shock is which hazard category?","o":[["Electrical",true],["Ergonomic",false],["Biological",false]],"p":1},{"t":"single","q":"Which of these is a recognised method for identifying workplace hazards?","o":[["Routine workplace inspections",true],["Ignoring reports from staff",false],["Assuming no hazards exist",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2"},{"t":"single","q":"A Job Safety Analysis (JSA) identifies hazards by doing what?","o":[["Breaking a job down into steps and examining each for hazards",true],["Counting the number of workers on site",false],["Measuring company profit per task",false]],"p":1},{"t":"tf","q":"Consulting workers who perform a task is a valuable way to identify hazards.","a":true,"p":1},{"t":"single","q":"Which is the FIRST and most effective option in the hierarchy of controls?","o":[["Elimination of the hazard",true],["Personal protective equipment (PPE)",false],["Administrative controls",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"Where does PPE sit in the hierarchy of controls?","o":[["Last, as the least effective control",true],["First, as the most effective control",false],["It is not part of the hierarchy at all",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"tf","q":"PPE is placed last in the hierarchy of controls because it does not remove the hazard, only the worker's exposure to it.","a":true,"p":1},{"t":"single","q":"Risk level is commonly assessed by combining which two factors?","o":[["Likelihood of occurrence and severity of harm",true],["The cost of equipment and the age of the building",false],["Worker seniority and shift length",false]],"p":1},{"t":"single","q":"Replacing a hazardous solvent with a safer water-based one is an example of which control?","o":[["Substitution",true],["Elimination",false],["PPE",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"tf","q":"Hazard identification should be a one-time activity completed only when a facility first opens.","a":false,"p":1}],"2":[{"t":"single","q":"Why is a hazard that has not yet caused harm still important to record?","o":[["Because it has the potential to cause harm and the risk must be assessed and controlled",true],["Because only hazards that have caused harm matter",false],["Because recording it satisfies payroll requirements",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2"},{"t":"multi","q":"Which of the following are examples of NON-routine activities or emergency situations that hazard identification must consider?","o":[["A planned equipment maintenance shutdown",true],["A fire or chemical spill emergency",true],["Normal daily data entry at a desk",false],["Standard end-of-shift cleanup that occurs every day",false]],"p":2,"ref":"ISO 45001:2018 §6.1.2"},{"t":"multi","q":"Which methods are appropriate for identifying hazards in a process plant?","o":[["HAZOP (Hazard and Operability) study",true],["Task analysis / Job Safety Analysis",true],["Reviewing past incident and near-miss data",true],["Waiting for an injury before acting",false]],"p":2,"ref":"ISO 45001:2018 §6.1.2"},{"t":"single","q":"A checklist-based inspection is most useful for what purpose?","o":[["Ensuring known, common hazards are not overlooked during inspection",true],["Discovering completely novel hazards no one has ever imagined",false],["Calculating the annual safety budget",false]],"p":1},{"t":"single","q":"What is the main limitation of relying only on a pre-printed hazard checklist?","o":[["It may miss site-specific or novel hazards not on the list",true],["It always finds every possible hazard",false],["It cannot be used during inspections",false]],"p":2},{"t":"multi","q":"Why should workers be consulted during hazard identification?","o":[["They have first-hand knowledge of how tasks are actually performed",true],["They often notice hazards and workarounds management cannot see",true],["Their participation is required by ISO 45001",true],["Their input should be ignored to save time",false]],"p":2,"ref":"ISO 45001:2018 §5.4"},{"t":"single","q":"In a simple risk matrix, a hazard rated high likelihood and high severity should be treated how?","o":[["As a high priority requiring prompt control measures",true],["As a low priority that can be ignored",false],["The same as a low-likelihood, low-severity hazard",false]],"p":1},{"t":"single","q":"Installing a machine guard or local exhaust ventilation is an example of which control type?","o":[["Engineering control",true],["Administrative control",false],["PPE",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"Job rotation, safe-work procedures, and training are examples of which control type?","o":[["Administrative controls",true],["Engineering controls",false],["Elimination",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"multi","q":"Place these controls in the correct effectiveness order by selecting the statements that are TRUE.","o":[["Elimination is more effective than substitution",true],["Engineering controls are more effective than administrative controls",true],["PPE is more effective than elimination",false],["Administrative controls are more effective than engineering controls",false]],"p":2,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"After a new piece of equipment is introduced, what should happen to the hazard identification?","o":[["It should be reviewed and updated to cover the change",true],["Nothing, because it was completed previously",false],["It should be deleted as no longer relevant",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2"},{"t":"tf","q":"Emergencies and foreseeable abnormal situations should be included in the scope of hazard identification.","a":true,"p":1},{"t":"tf","q":"Both routine and non-routine activities must be considered when identifying hazards.","a":true,"p":1},{"t":"single","q":"Which sequence correctly orders the hierarchy of controls from most to least effective?","o":[["Elimination, substitution, engineering, administrative, PPE",true],["PPE, administrative, engineering, substitution, elimination",false],["Engineering, elimination, PPE, substitution, administrative",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"Reviewing incident and near-miss data helps hazard identification primarily because it does what?","o":[["Reveals hazards and failure patterns already present in the workplace",true],["Predicts the company's future revenue",false],["Replaces the need for any inspection",false]],"p":1},{"t":"multi","q":"Which factors should be considered when determining the SEVERITY of harm from a hazard?","o":[["The potential extent of injury or ill health (e.g., minor cut vs. fatality)",true],["The number of people who could be exposed",true],["Whether the harm could be permanent or reversible",true],["The brand of the manufacturer's logo",false]],"p":2},{"t":"single","q":"A control that lowers likelihood but does NOT remove the hazard is best described as which?","o":[["A risk-reduction control rather than elimination",true],["Elimination of the hazard",false],["A guarantee that no harm can occur",false]],"p":1},{"t":"tf","q":"Substitution always completely removes a hazard from the workplace.","a":false,"p":1},{"t":"single","q":"Which statement about likelihood and severity is correct?","o":[["A low-likelihood event with catastrophic severity can still warrant strong controls",true],["Only likelihood matters; severity is irrelevant",false],["A hazard with high severity but low likelihood needs no attention",false]],"p":1},{"t":"multi","q":"Which inputs are useful sources when identifying hazards for a task?","o":[["Direct observation and workplace inspection",true],["Worker consultation and interviews",true],["Safety data sheets (SDS) for chemicals used",true],["The colour of the office walls",false]],"p":2},{"t":"single","q":"What does it mean to identify hazards for 'non-routine' activities?","o":[["Considering infrequent tasks such as maintenance, start-up, shutdown, and breakdowns",true],["Considering only the most common daily tasks",false],["Ignoring any task that happens rarely",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2"},{"t":"single","q":"Why is consultation with workers a requirement and not just a courtesy in ISO 45001?","o":[["Worker participation improves hazard identification quality and is mandated by the standard",true],["It is optional and the standard discourages it",false],["It only matters for senior managers",false]],"p":1,"ref":"ISO 45001:2018 §5.4"},{"t":"single","q":"A standby diesel generator is only run during a power outage. How should its hazards be treated?","o":[["As a non-routine activity whose hazards (fumes, fuel, hot surfaces) must still be identified and controlled",true],["As irrelevant because it rarely operates",false],["As covered automatically by the office assessment",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2"},{"t":"single","q":"A trip hazard rated as 'likely' with 'minor' severity, versus a fall-from-height rated 'unlikely' with 'fatal' severity. What is the prudent approach?","o":[["Assess both on the risk matrix and prioritise controls for the fall-from-height due to its severe consequence",true],["Always prioritise the more likely hazard regardless of severity",false],["Ignore the fall-from-height because it is unlikely",false]],"p":2},{"t":"short","q":"Explain the difference between a hazard and a risk, giving one workplace example of each.","m":"Looks for: hazard = source/potential to cause harm; risk = likelihood x severity / chance harm occurs; a concrete example distinguishing the two (e.g., wet floor is the hazard, the chance of slipping and being injured is the risk).","p":2},{"t":"short","q":"List the hierarchy of controls in order and explain why PPE is placed last.","m":"Looks for: elimination, substitution, engineering, administrative, PPE in correct order; PPE last because it does not remove or reduce the hazard at source, relies on correct use/compliance, and only protects the individual wearer.","p":2}],"3":[{"t":"single","q":"During a HAZOP study, guide words such as 'no flow' or 'more pressure' are applied for what purpose?","o":[["To systematically explore deviations from design intent and reveal hazards",true],["To assign blame to operators after an incident",false],["To calculate the depreciation of plant equipment",false]],"p":2,"ref":"ISO 45001:2018 §6.1.2"},{"t":"single","q":"Which statement best captures why hazard identification must be proactive rather than reactive?","o":[["Identifying hazards before harm occurs allows controls to be applied and prevents incidents",true],["Hazards can only be known after an injury has happened",false],["Reactive identification is always sufficient under ISO 45001",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2"},{"t":"multi","q":"Which circumstances should TRIGGER a review and update of existing hazard identification?","o":[["Introduction of new equipment, materials, or processes",true],["A change in legal requirements or organisational structure",true],["Lessons learned from an incident or near-miss investigation",true],["A change in the company's marketing slogan",false]],"p":2,"ref":"ISO 45001:2018 §6.1.2"},{"t":"multi","q":"For the hierarchy of controls, which combinations correctly pair an action with its control level?","o":[["Removing a hazardous process step entirely = elimination",true],["Replacing a toxic solvent with a less toxic one = substitution",true],["Enclosing a noisy machine in an acoustic booth = engineering",true],["Issuing earplugs and a noise-awareness policy = elimination",false]],"p":2,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"A risk assessment shows residual risk is still unacceptable after an administrative control. What is the most appropriate next step?","o":[["Move higher up the hierarchy and apply engineering, substitution, or elimination where reasonably practicable",true],["Accept the risk because a control has already been applied",false],["Add a second administrative control and stop there regardless of residual risk",false]],"p":2,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"Why should hazard identification explicitly consider people other than direct employees (e.g., contractors, visitors)?","o":[["They may be exposed to the same or different hazards and the OH&S system must account for all affected persons",true],["Only direct employees can ever be harmed",false],["Contractors are exempt from all workplace hazards",false]],"p":2,"ref":"ISO 45001:2018 §6.1.2"},{"t":"single","q":"What is 'residual risk'?","o":[["The risk that remains after controls have been implemented",true],["The risk before any control is applied",false],["A risk that no longer exists",false]],"p":1},{"t":"multi","q":"Which are valid reasons that PPE is the least preferred control in the hierarchy?","o":[["It depends on correct fit, use, and maintenance by each individual",true],["It does not eliminate or reduce the hazard at its source",true],["It can fail or be removed, leaving the worker fully exposed",true],["It protects everyone in the area equally without being worn",false]],"p":2,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"In a 5x5 risk matrix, severity is rated 5 (fatal) and likelihood 2 (unlikely), giving a score of 10 out of 25. How should this be handled?","o":[["Evaluated against the organisation's risk acceptance criteria; high-severity outcomes typically demand robust controls despite low likelihood",true],["Automatically ignored because 10 is below the midpoint",false],["Treated as zero risk because it is unlikely",false]],"p":2},{"t":"single","q":"Which best describes the relationship between hazard identification and risk assessment?","o":[["Hazard identification finds what could cause harm; risk assessment evaluates the likelihood and severity to prioritise controls",true],["They are the same step with no distinction",false],["Risk assessment must always be done before any hazard is identified",false]],"p":1,"ref":"ISO 45001:2018 §6.1.2"},{"t":"single","q":"A task is performed differently by night-shift workers than the documented procedure assumes. Why does this matter for hazard identification?","o":[["Actual work-as-done can introduce hazards not captured by work-as-imagined, so observation and consultation are essential",true],["It does not matter because the written procedure is authoritative",false],["Only the day shift needs to be assessed",false]],"p":2},{"t":"multi","q":"Which are characteristics of a robust hazard identification process under ISO 45001?","o":[["It is ongoing and proactive, not a single event",true],["It covers routine, non-routine activities, and emergency situations",true],["It involves worker participation and consultation",true],["It is performed once and never revisited",false]],"p":2,"ref":"ISO 45001:2018 §6.1.2"},{"t":"single","q":"When two controls are 'reasonably practicable', how does the hierarchy guide the choice?","o":[["Prefer the control higher in the hierarchy as it is generally more reliable and effective",true],["Always choose the cheapest control regardless of position",false],["Always choose PPE because it is simplest",false]],"p":1,"ref":"ISO 45001:2018 §8.1.2"},{"t":"tf","q":"A near-miss with no injury provides no useful information for hazard identification.","a":false,"p":1},{"t":"tf","q":"Once controls are in place, the residual risk should be re-evaluated to confirm it is acceptable.","a":true,"p":1},{"t":"single","q":"Why might a workplace inspection alone be insufficient for thorough hazard identification?","o":[["It captures conditions at a single point in time and may miss intermittent, task-based, or psychosocial hazards",true],["Inspections always reveal every possible hazard including future ones",false],["Inspections are never useful for hazard identification",false]],"p":2},{"t":"single","q":"How should psychosocial hazards such as chronic overload or harassment typically be identified?","o":[["Through worker consultation, surveys, absence/turnover data, and confidential reporting, since they are often not visually observable",true],["Solely through a visual walk-through inspection",false],["They cannot be identified and need not be considered",false]],"p":2,"ref":"ISO 45001:2018 §6.1.2"},{"t":"multi","q":"Which data sources can reveal hazards that direct observation might miss?","o":[["Incident and near-miss reports",true],["Worker health surveillance and sickness-absence trends",true],["Maintenance logs and equipment failure records",true],["The office stationery inventory",false]],"p":2},{"t":"single","q":"Scenario: A warehouse introduces a new forklift route that crosses a busy pedestrian walkway. Applying the hierarchy of controls, which is the BEST first option to consider?","o":[["Re-route or physically separate forklifts and pedestrians (elimination/engineering) before relying on signs or hi-vis vests",true],["Issue hi-vis vests to all pedestrians and consider the risk controlled",false],["Put up a warning sign and take no further action",false]],"p":2,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"Scenario: After a chemical process change, a worker reports a new strong odour. What is the correct hazard-identification response?","o":[["Treat the change as a trigger to re-assess hazards, consult the SDS, and evaluate exposure controls",true],["Wait until someone reports feeling ill before acting",false],["Assume the existing assessment still covers the new chemical",false]],"p":2,"ref":"ISO 45001:2018 §6.1.2"},{"t":"single","q":"Scenario: A maintenance team must enter a confined space (a non-routine task). Which hazard-identification approach is most appropriate?","o":[["A task-specific assessment / permit-to-work covering atmosphere, access, and emergency rescue before entry",true],["Rely on the general office hazard assessment",false],["Skip assessment because entry is infrequent",false]],"p":2},{"t":"single","q":"Scenario: A risk matrix flags a process as 'medium' risk, but workers strongly disagree, citing repeated near-misses. What should the assessor do?","o":[["Treat the worker input and near-miss data as evidence to re-examine the likelihood/severity ratings and revise if warranted",true],["Dismiss worker concerns because the matrix score is final",false],["Lower the rating to reduce paperwork",false]],"p":2,"ref":"ISO 45001:2018 §5.4"},{"t":"multi","q":"Which statements about elimination and substitution are correct?","o":[["Elimination removes the hazard so the associated risk no longer exists",true],["Substitution replaces the hazard with something less hazardous but some residual risk may remain",true],["Both can sometimes introduce new hazards that must themselves be assessed",true],["Elimination is the least effective control",false]],"p":2,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"What is the danger of stopping the hierarchy of controls at PPE when a higher-order control is reasonably practicable?","o":[["The hazard remains at full strength and protection relies entirely on consistent, correct PPE use, leaving little margin if PPE fails",true],["There is no danger; PPE is always the safest choice",false],["It guarantees zero residual risk",false]],"p":2,"ref":"ISO 45001:2018 §8.1.2"},{"t":"single","q":"Why must hazard identification be linked to the management of change (MOC) process?","o":[["So that new hazards introduced by changes are identified and controlled before the change is implemented",true],["So that changes can proceed without any assessment",false],["Because MOC replaces the need for hazard identification entirely",false]],"p":2,"ref":"ISO 45001:2018 §6.1.2"},{"t":"tf","q":"A single severe hazard with low likelihood may justify elimination or engineering controls rather than relying on PPE alone.","a":true,"p":1},{"t":"tf","q":"Worker participation in hazard identification can be replaced entirely by a generic external checklist.","a":false,"p":1},{"t":"short","q":"Describe a systematic process for identifying hazards associated with a new manufacturing line, naming at least three identification methods and explaining how routine, non-routine, and emergency situations are covered.","m":"Looks for: a structured approach (e.g., task breakdown/JSA, inspection, HAZOP, worker consultation, SDS review, incident-data review); explicit coverage of routine operation, non-routine tasks (maintenance/start-up/shutdown), and emergencies; mention of who is affected and recording outputs for risk assessment.","p":3},{"t":"short","q":"Explain how likelihood and severity are combined in a risk matrix, and discuss why a low-likelihood / high-severity hazard cannot simply be dismissed.","m":"Looks for: risk = likelihood x severity (or matrix scoring); explanation that catastrophic consequences (e.g., fatality) warrant strong controls even when probability is low; reference to risk acceptance criteria and the precautionary need to control severe outcomes.","p":3},{"t":"short","q":"A company has applied PPE as the only control for a noise hazard. Critique this decision and recommend improvements using the hierarchy of controls.","m":"Looks for: recognition that PPE is the least effective/last control; recommendation to consider elimination/substitution (quieter process or equipment), engineering (enclosure, acoustic barriers, damping), and administrative controls (limiting exposure time, rotation) before/alongside PPE; note that PPE depends on correct use and does not reduce the hazard at source.","p":3},{"t":"short","q":"Explain why and when existing hazard identification and risk assessments should be reviewed and updated, with reference to change and worker participation.","m":"Looks for: triggers such as new equipment/materials/processes, legal or organisational change, post-incident/near-miss lessons learned, and periodic review; emphasis that the process is ongoing not one-off; the role of worker consultation and that updates feed back into controls.","p":3},{"t":"short","q":"Discuss how worker participation and consultation strengthen hazard identification, and give two examples of hazards that are likely to be missed without it.","m":"Looks for: workers' first-hand knowledge of work-as-done, workarounds, and intermittent conditions; ISO 45001 requirement for participation; examples such as psychosocial hazards (overload, harassment), task-specific shortcuts, ergonomic strain, or intermittent equipment faults that an inspection alone would miss.","p":3}]}},"Management review preparation":{"levels":{"1":[{"t":"single","q":"In ISO 9001:2015, which clause specifies requirements for management review?","o":[["Clause 9.3",true],["Clause 8.5",false],["Clause 7.1",false]],"p":1,"ref":"ISO 9001:2015 9.3"},{"t":"single","q":"Who is responsible for conducting the management review of the quality management system?","o":[["Top management",true],["The internal audit team",false],["Any available department head",false]],"p":1,"ref":"ISO 9001:2015 9.3.1"},{"t":"single","q":"How often must management reviews be conducted according to ISO 9001:2015?","o":[["At planned intervals",true],["Only when a major nonconformity occurs",false],["Every calendar week",false]],"p":1,"ref":"ISO 9001:2015 9.3.1"},{"t":"single","q":"What must be retained as evidence that management reviews have taken place?","o":[["Documented information",true],["Only verbal confirmation from the CEO",false],["A signed audit certificate",false]],"p":1,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"Which of the following is a required input to the management review?","o":[["Results of customer satisfaction and feedback",true],["The personal opinions of the chairperson only",false],["The marketing budget for next year",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"Which of the following is a required output of the management review?","o":[["Decisions related to opportunities for improvement",true],["A list of staff holiday dates",false],["The minutes of the previous audit only",false]],"p":1,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"Which input considers whether the quality management system continues to fit the organization?","o":[["The suitability, adequacy and effectiveness of the QMS",true],["The colour scheme of the agenda",false],["The number of emails sent that quarter",false]],"p":1,"ref":"ISO 9001:2015 9.3.1"},{"t":"single","q":"Which item is a required management review input under ISO 9001:2015?","o":[["Status of actions from previous management reviews",true],["The auditor's salary",false],["Competitor pricing lists",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"Performance information about which parties must be considered as a review input?","o":[["External providers (suppliers)",true],["Local government officials",false],["Former employees",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"Which review input concerns the achievement of planned targets for quality?","o":[["The extent to which quality objectives have been met",true],["The number of meeting rooms booked",false],["The colour of the company logo",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"Which required output addresses gaps in people, infrastructure or competence?","o":[["Resource needs",true],["The lunch menu",false],["The seating plan",false]],"p":1,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"Audit results that must be reviewed in management review include which of the following?","o":[["Results of internal and external audits",true],["Only the auditor's travel expenses",false],["Only audits older than ten years",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"Which input covers complaints, returns and corrective actions taken?","o":[["Nonconformities and corrective actions",true],["The annual gala invitation list",false],["The office parking allocation",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"Changes in which factors are a required review input?","o":[["External and internal issues relevant to the QMS",true],["The personal hobbies of staff",false],["The brand of office coffee",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"What is the primary purpose of management review?","o":[["To ensure continuing suitability, adequacy, effectiveness and alignment with strategy",true],["To assign blame for nonconformities",false],["To replace the internal audit programme",false]],"p":1,"ref":"ISO 9001:2015 9.3.1"},{"t":"tf","q":"Management review is a responsibility of top management.","a":true,"p":1,"ref":"ISO 9001:2015 9.3.1"},{"t":"tf","q":"Management reviews must be carried out at planned intervals.","a":true,"p":1,"ref":"ISO 9001:2015 9.3.1"},{"t":"tf","q":"Documented information must be retained as evidence of the results of management reviews.","a":true,"p":1,"ref":"ISO 9001:2015 9.3.3"},{"t":"tf","q":"Customer satisfaction and feedback are required inputs to the management review.","a":true,"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"tf","q":"Decisions on resource needs are a valid output of a management review.","a":true,"p":1,"ref":"ISO 9001:2015 9.3.3"}],"2":[{"t":"single","q":"When preparing the agenda for a management review, which sequence best supports effective decision-making?","o":[["Group inputs logically, then move to decisions and assigned actions for outputs",true],["List random topics in the order people arrive",false],["Cover only the topics the chairperson finds interesting",false]],"p":1,"ref":"ISO 9001:2015 9.3"},{"t":"single","q":"A reviewer summarises three years of audit data for the meeting. What is the best way to present it as a review input?","o":[["As trend information showing direction over time, not just raw counts",true],["As a single number with no context",false],["By omitting any years with poor results",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"Which input addresses whether risk and opportunity actions actually worked?","o":[["The effectiveness of actions taken to address risks and opportunities",true],["The number of risks first identified ten years ago",false],["The cost of the risk register software only",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"During preparation, you find that 'opportunities for improvement' has no data. What is the most appropriate action?","o":[["Collect candidate improvement items from audits, feedback and process data before the meeting",true],["Leave the input blank because no one raised it",false],["Cancel the management review entirely",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"A management review is held but no decisions or actions are recorded. Why is this a problem?","o":[["Outputs (decisions and actions) are required and must be retained as documented information",true],["It is acceptable as long as attendance was recorded",false],["Outputs are optional under ISO 9001:2015",false]],"p":2,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"What is the best practice for handling actions assigned during a review?","o":[["Record each action with an owner and due date, and track to closure",true],["Note the action verbally and rely on memory",false],["Assign all actions to the same person regardless of role",false]],"p":1,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"Process performance and product conformity should be presented in the review primarily to do what?","o":[["Evaluate whether processes are achieving intended results",true],["Fill time in the agenda",false],["Replace the need for monitoring and measurement",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"Why should the status of actions from previous management reviews be an early agenda item?","o":[["To confirm prior decisions were implemented and effective before making new ones",true],["Because old actions are more important than current data",false],["To avoid discussing current performance",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"Adequacy of resources as a review input is intended to surface what?","o":[["Whether people, infrastructure and competence are sufficient for the QMS",true],["Whether the meeting room is large enough",false],["The travel budget of senior managers",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"A draft agenda omits 'performance of external providers'. What should the preparer do?","o":[["Add it, since supplier performance is a required input",true],["Leave it out to keep the meeting short",false],["Replace it with the internal staff roster",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"Which statement best describes how monitoring and measurement results feed the review?","o":[["They provide objective evidence of QMS performance against planned arrangements",true],["They are only relevant to the finance department",false],["They should be excluded to keep the review qualitative",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"What is the most appropriate evidence to retain after a management review?","o":[["Records of the inputs considered, decisions made and actions assigned",true],["Only the date and time of the meeting",false],["A photograph of the attendees",false]],"p":1,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"When customer feedback shows a rising complaint trend, what should the review output address?","o":[["Decisions on improvement and any needed changes or resources",true],["A decision to stop collecting feedback",false],["No action, since complaints are normal",false]],"p":2,"ref":"ISO 9001:2015 9.3.3"},{"t":"multi","q":"Which of the following are required INPUTS to a management review under ISO 9001:2015? (Select all that apply)","o":[["Status of actions from previous reviews",true],["Customer satisfaction and feedback",true],["Results of audits",true],["The personal travel plans of directors",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"multi","q":"Which of the following are required OUTPUTS of a management review? (Select all that apply)","o":[["Decisions on opportunities for improvement",true],["Decisions on any need for changes to the QMS",true],["Decisions on resource needs",true],["A ranking of employees by seniority",false]],"p":2,"ref":"ISO 9001:2015 9.3.3"},{"t":"multi","q":"When preparing review evidence, which practices improve the quality of the inputs? (Select all that apply)","o":[["Summarising data as trends over time",true],["Linking each input to a clear data source",true],["Highlighting items needing a decision",true],["Hiding poor results to keep morale high",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"multi","q":"Which items below are valid management review INPUTS? (Select all that apply)","o":[["Process performance and conformity of products and services",true],["The effectiveness of actions for risks and opportunities",true],["Adequacy of resources",true],["The brand of the company vehicles",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"If top management delegates chairing the review but never participates, what is the main risk?","o":[["The review may fail to meet the requirement that it be a top-management responsibility",true],["The meeting will simply run longer",false],["No risk; delegation removes all top-management duties",false]],"p":2,"ref":"ISO 9001:2015 9.3.1"},{"t":"single","q":"Which preparation step best ensures the review covers changes in context?","o":[["Gathering updates on external and internal issues since the last review",true],["Reusing last year's context analysis unchanged",false],["Ignoring context because it rarely changes",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"A reviewer wants to demonstrate the QMS is effective. Which evidence is most relevant?","o":[["Quality objective results showing targets met or trending toward them",true],["The number of pages in the quality manual",false],["The age of the management system certificate",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"How should opportunities for improvement identified in the review be handled?","o":[["Captured as outputs with decisions and, where chosen, assigned actions",true],["Noted only if convenient and never tracked",false],["Forwarded to customers for their decision",false]],"p":1,"ref":"ISO 9001:2015 9.3.3"},{"t":"tf","q":"The effectiveness of actions taken to address risks and opportunities is a required management review input.","a":true,"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"tf","q":"Changes to the quality management system can be a valid output of a management review.","a":true,"p":1,"ref":"ISO 9001:2015 9.3.3"},{"t":"tf","q":"Opportunities for improvement do not need to be considered as a review input.","a":false,"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"short","q":"List three required inputs to a management review under ISO 9001:2015 and briefly explain why each matters for decision-making.","m":"Looks for: three valid 9.3.2 inputs (e.g. status of prior actions, customer satisfaction/feedback, audit results, process performance, nonconformities/corrective actions, external provider performance, resource adequacy, objective results) each with a short rationale tying it to evidence-based decisions.","p":2},{"t":"short","q":"Describe how you would prepare an agenda and collect evidence for a management review so that the meeting can produce valid outputs.","m":"Looks for: mapping agenda to required inputs, assigning data owners, summarising evidence as trends, flagging items needing decisions, planning for outputs (improvement, QMS changes, resource needs), and retaining documented information.","p":2}],"3":[{"t":"single","q":"A management review records inputs and discussion but the only output is 'continue as is' with no rationale. From an audit standpoint, what is the key concern?","o":[["The lack of documented decisions and rationale weakens evidence that outputs were genuinely produced",true],["Nothing; 'continue as is' satisfies all output requirements automatically",false],["The review should have been skipped to save time",false]],"p":2,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"Top management proposes holding the review every three years to reduce effort. Why is this likely noncompliant?","o":[["Planned intervals must be appropriate to keep the QMS suitable, adequate and effective; three years is unlikely to be adequate",true],["Any interval longer than monthly is automatically prohibited",false],["The standard mandates exactly quarterly reviews",false]],"p":2,"ref":"ISO 9001:2015 9.3.1"},{"t":"single","q":"During preparation you discover the previous review's actions were never tracked to closure. What is the most defensible course of action?","o":[["Reconstruct action status, report open items as an input, and improve the tracking mechanism",true],["Mark all previous actions closed to keep the record tidy",false],["Omit previous-action status from this review",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"A site presents only favourable metrics and excludes a process with chronic nonconformities. How does this undermine the review?","o":[["Selective evidence prevents a fair evaluation of suitability, adequacy and effectiveness",true],["It is good practice to present only positive data",false],["It has no effect because outputs are decided by top management anyway",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"For a multi-site organization, what is the best preparation approach to keep review inputs meaningful?","o":[["Consolidate site data into organization-level trends while preserving the ability to drill into problem sites",true],["Average everything into a single number so problems disappear",false],["Review only the best-performing site",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"A reviewer wants the review output to drive real change. Which output structure best supports this?","o":[["Explicit decisions, each linked to an owner, action, due date and follow-up mechanism",true],["A general statement that improvement is encouraged",false],["A list of inputs repeated without any decision",false]],"p":2,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"Customer satisfaction is high overall but one key account is at risk. How should preparation handle this nuance?","o":[["Present both the aggregate and the segmented risk so the review can decide on targeted action",true],["Report only the high aggregate score",false],["Exclude the at-risk account to avoid alarming management",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"External provider performance has declined for a critical supplier. Which review output is most appropriate?","o":[["A decision and action addressing supplier controls, with resource or change implications considered",true],["No action, since suppliers are outside the QMS",false],["A decision to stop measuring supplier performance",false]],"p":2,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"Why is it good practice to link each agenda input to a named data owner before the review?","o":[["It ensures evidence is collected, current and accountable, improving the quality of decisions",true],["It lengthens the meeting deliberately",false],["It removes the need for top management to attend",false]],"p":1,"ref":"ISO 9001:2015 9.3"},{"t":"single","q":"A review combines QMS, environmental and OH&S systems into one meeting. What is the main preparation requirement to stay compliant?","o":[["Each standard's required inputs and outputs are covered and the relevant evidence is retained",true],["Only the quality inputs need to be addressed",false],["Combined reviews are not permitted under ISO management system standards",false]],"p":2,"ref":"ISO 9001:2015 9.3"},{"t":"single","q":"Quality objectives were not met for two consecutive periods. What should the preparer ensure the review can do?","o":[["Decide on corrective improvement, changes to objectives or resources, with rationale recorded",true],["Quietly remove the objectives that were missed",false],["Defer any decision to the next certification audit",false]],"p":2,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"Which approach best demonstrates that management review outputs were effective over time?","o":[["Tracking closure and verifying that prior decisions produced the intended results, reported at the next review",true],["Counting how many decisions were written down",false],["Repeating the same decisions every cycle",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"An auditor asks for evidence of the management review. What is the strongest response?","o":[["Documented information covering inputs considered, decisions, actions, owners and due dates",true],["A verbal assurance that the review happened",false],["The previous year's audit report only",false]],"p":1,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"How should significant changes in internal or external issues be reflected in review preparation?","o":[["Refresh the context analysis and surface impacts on risks, objectives and resources for decision",true],["Carry forward last year's analysis without review",false],["Treat context as fixed once documented",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"A proposed review output is 'investigate option X'. What makes this a usable output rather than a vague intention?","o":[["Assigning an owner, scope, due date and a point to report findings back",true],["Stating it broadly so it cannot be measured",false],["Leaving it unassigned so anyone may act",false]],"p":2,"ref":"ISO 9001:2015 9.3.3"},{"t":"multi","q":"In a scenario where audit results, complaint trends and supplier performance all worsened, which review OUTPUTS would be appropriate? (Select all that apply)","o":[["Decisions on specific improvement actions with owners",true],["A decision on needed changes to the QMS",true],["A decision on additional resource needs",true],["A decision to delete the affected processes from scope without analysis",false]],"p":2,"ref":"ISO 9001:2015 9.3.3"},{"t":"multi","q":"Which preparation practices help ensure a management review is evidence-based and defensible? (Select all that apply)","o":[["Mapping the agenda to all required inputs",true],["Assigning data owners and verifying data currency",true],["Retaining documented information of decisions and actions",true],["Presenting only the metrics that look favourable",false]],"p":2,"ref":"ISO 9001:2015 9.3"},{"t":"multi","q":"Which of the following are legitimate reasons to hold an additional, unplanned management review? (Select all that apply)","o":[["A major change in external or internal context",true],["A series of significant nonconformities",true],["A strategic change affecting the QMS",true],["The chairperson wants to test a new meeting room",false]],"p":2,"ref":"ISO 9001:2015 9.3.1"},{"t":"multi","q":"For consolidating inputs across a multi-site organization, which approaches preserve decision quality? (Select all that apply)","o":[["Showing organization-level trends",true],["Retaining the ability to drill into individual sites",true],["Flagging outlier sites for targeted decisions",true],["Averaging away poor-performing sites",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"What distinguishes a management review input from a management review output?","o":[["Inputs are the evidence considered; outputs are the decisions and actions resulting from the review",true],["Inputs and outputs are interchangeable terms",false],["Inputs are decisions and outputs are evidence",false]],"p":1,"ref":"ISO 9001:2015 9.3"},{"t":"single","q":"A reviewer presents the adequacy of resources input. Which finding most clearly warrants an output decision?","o":[["Recurring nonconformities traced to insufficient competence in a key process",true],["A minor underspend on stationery",false],["A preference for a different meeting time",false]],"p":2,"ref":"ISO 9001:2015 9.3.3"},{"t":"single","q":"Why should monitoring and measurement results be reconciled with quality objective results before the review?","o":[["To ensure the evidence is consistent and the review can make sound decisions on performance",true],["To make the agenda appear longer",false],["Because the standard forbids presenting them together",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"After the review, an assigned action is overdue with no progress. What is the best governance response in preparing the next review?","o":[["Report it as open under 'status of actions from previous reviews' and escalate for a fresh decision",true],["Silently re-date the action to appear current",false],["Remove the action from the record",false]],"p":2,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"Which statement best reflects how risks and opportunities connect to the management review?","o":[["The review evaluates the effectiveness of actions taken to address them and decides on further action",true],["Risks and opportunities are never discussed in management review",false],["Only opportunities, never risks, are reviewed",false]],"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"single","q":"A draft management review record lists decisions but omits who will act and by when. What is the most important fix?","o":[["Add owners and due dates so actions are trackable and outputs are complete",true],["Add a company logo to the header",false],["Delete the decisions to keep the record short",false]],"p":1,"ref":"ISO 9001:2015 9.3.3"},{"t":"tf","q":"A management review may be conducted as a single event or as a series of activities over a period, provided all required inputs and outputs are addressed.","a":true,"p":1,"ref":"ISO 9001:2015 9.3"},{"t":"tf","q":"It is acceptable to exclude poorly performing processes from the review evidence to keep the meeting positive.","a":false,"p":1,"ref":"ISO 9001:2015 9.3.2"},{"t":"short","q":"You are asked to design a management review process for a newly certified organization. Outline the inputs you would collect, how you would prepare the agenda and evidence, and how you would capture and track outputs.","m":"Looks for: full set of 9.3.2 inputs mapped to data owners, agenda structured around inputs then decisions, evidence summarised as trends, outputs covering improvement/QMS changes/resource needs, actions with owners and due dates, and retention of documented information.","p":3},{"t":"short","q":"A previous management review produced decisions but none were implemented before the next cycle. Explain how preparation for the upcoming review should handle this and what outputs you would expect.","m":"Looks for: report open prior-action status as an input, root-cause the implementation failure, escalate for fresh decisions, consider resource/accountability changes, and strengthen tracking with owners and due dates.","p":3},{"t":"short","q":"Explain why management review must be a top-management responsibility and what risks arise if it is delegated entirely to a quality manager.","m":"Looks for: top management owns strategic alignment, resource decisions and authority to act; full delegation risks decisions without authority, weak resource commitment, and a compliance gap against 9.3.1.","p":3},{"t":"short","q":"Describe how you would present three years of audit, complaint and supplier data so the review can make sound decisions rather than just observe numbers.","m":"Looks for: trend analysis over time, linking data to objectives and processes, highlighting items needing decisions, segmenting outliers, and proposing candidate outputs for management to decide.","p":3},{"t":"short","q":"In an integrated management system covering quality, environment and safety, explain how you would prepare a single management review while remaining compliant with each standard.","m":"Looks for: ensuring each standard's required inputs and outputs are covered, retaining documented information for all systems, mapping shared inputs, and confirming decisions address each system's needs.","p":3}]}}};
